(function () {
  'use strict';
  var T = {"study":{"dp-600":{"s0":{"sectionTitle":"Key Fabric Concepts"},"s0i0":{"title":"Direct Lake","content":"<strong>Direct Lake</strong> is an innovative feature of semantic models in Power BI within Microsoft Fabric. It lets you load data directly from the data lake (OneLake) into the Power BI engine without having to import the data or use DirectQuery. This delivers the performance of Import mode with real-time data freshness."},"s0i1":{"title":"OneLake","content":"<strong>OneLake</strong> is a single, unified, logical data lake for the entire organization. It is the 'OneDrive for data'. All Fabric artifacts (Lakehouses, Warehouses, KQL databases) automatically store their data in OneLake in Delta Parquet format."},"s0i2":{"title":"Delta Parquet","content":"The underlying storage format in Fabric. <strong>Parquet</strong> is a highly compressed columnar format, and <strong>Delta</strong> adds a transaction log layer (ACID) and time control (Time Travel) on top of the Parquet files."},"s1":{"sectionTitle":"Modeling and DAX"},"s1i0":{"title":"Star Schema","content":"The recommended design for Power BI models. It consists of a central <strong>Fact</strong> table (metrics, transactions) surrounded by <strong>Dimension</strong> tables (descriptive attributes). It offers the best performance and simplicity for DAX."},"s1i1":{"title":"CALCULATE()","content":"The most important function in DAX. It evaluates an expression in a modified filter context. <br><code>CALCULATE(Medida, Filtro1, Filtro2...)</code>. It is essential for Time Intelligence and percentage calculations."},"s2":{"sectionTitle":"Lifecycle Processes"},"s2i0":{"title":"Deployment Pipelines","content":"A tool for managing the content lifecycle (ALM). It lets you move content between stages: <strong>Development</strong>, <strong>Test</strong>, and <strong>Production</strong>. It supports deployment rules to change parameters (such as connection strings) between stages."},"s2i1":{"title":"Git Integration","content":"Fabric lets you sync workspaces with a Git repository (Azure DevOps). This enables version control, multi-developer collaboration, and backup of the source code (.pbip, .bim files, etc.)."}},"unir-viz-interactiva":{"s0":{"sectionTitle":"1. Introduction to Infographics and Visualization"},"s0i0":{"title":"Fundamental Concepts","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M12 4.5C7 4.5 2.73 7.61 1 12c1.73 4.39 6 7.5 11 7.5s9.27-3.11 11-7.5c-1.73-4.39-6-7.5-11-7.5zM12 17c-2.76 0-5-2.24-5-5s2.24-5 5-5 5 2.24 5 5-2.24 5-5 5zm0-8c-1.66 0-3 1.34-3 3s1.34 3 3 3 3-1.34 3-3-1.34-3-3-3z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Purpose of Visualization</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <p style=\"font-size:1.05em; margin-top:0;\"><strong>Inform, expand knowledge, and invite reflection</strong> — visualization extends the capacity of the human visual system.</p>\n                            \n        <div style=\"\n            background: #4f6ef708;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #4f6ef7; font-size: 0.92rem;\">\n                Cognitive Amplification\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">Visualization takes advantage of the human eye's natural ability to detect patterns at high speed (pre-attentive perception). It is an extension of the visual system.</div>\n        </div>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #f97316, #ef4444);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M11.99 18.54l-7.37-5.73L3 14.07l9 7 9-7-1.63-1.27zM12 16l7.36-5.73L21 9l-9-7-9 7 1.63 1.27L12 16z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Infographics vs Visualization</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <div style=\"display:grid; grid-template-columns:1fr 1fr; gap:16px;\">\n                                <div style=\"background:#f973160a; border-radius:12px; padding:14px; border:1px solid #f9731620;\">\n                                    <div style=\"font-weight:700; color:#f97316; margin-bottom:6px;\">Infographic</div>\n                                    <ul style=\"margin:0; padding-left:18px; font-size:0.9rem;\">\n                                        <li><strong>Narrative and closed</strong></li>\n                                        <li>The author tells a predefined story</li>\n                                        <li>Fixed piece, a single path</li>\n                                    </ul>\n                                </div>\n                                <div style=\"background:#4f6ef70a; border-radius:12px; padding:14px; border:1px solid #4f6ef720;\">\n                                    <div style=\"font-weight:700; color:#4f6ef7; margin-bottom:6px;\">Visualization</div>\n                                    <ul style=\"margin:0; padding-left:18px; font-size:0.9rem;\">\n                                        <li><strong>Exploratory and open</strong></li>\n                                        <li>The user interacts and discovers</li>\n                                        <li>Dynamic system with filters</li>\n                                    </ul>\n                                </div>\n                            </div>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #10b981, #059669);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M3 13h8V3H3v10zm0 8h8v-6H3v6zm10 0h8V11h-8v10zm0-18v6h8V3h-8z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Data Hierarchy</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <div style=\"display:flex; align-items:center; justify-content:center; gap:12px; padding:10px; flex-wrap:wrap;\">\n                                \n        <span style=\"\n            display: inline-block;\n            background: #6b728018;\n            color: #6b7280;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #6b728030;\n            margin: 2px 3px;\n        \">Data (raw value)</span>\n                                <span style=\"font-size:1.3em; color:#10b981;\">→</span>\n                                \n        <span style=\"\n            display: inline-block;\n            background: #f59e0b18;\n            color: #f59e0b;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #f59e0b30;\n            margin: 2px 3px;\n        \">Information (processed data)</span>\n                                <span style=\"font-size:1.3em; color:#10b981;\">→</span>\n                                \n        <span style=\"\n            display: inline-block;\n            background: #10b98118;\n            color: #10b981;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #10b98130;\n            margin: 2px 3px;\n        \">Knowledge (understanding)</span>\n                            </div>\n                            <p style=\"text-align:center; font-size:0.9em; color:#666; margin-bottom:0;\">Visualization facilitates this transition by making data understandable.</p>\n                        \n            </div>\n        </div>\n                    "},"s0i1":{"title":"5 Phases of the Process","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #8b5cf6, #6d28d9);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M22.7 19l-9.1-9.1c.9-2.3.4-5-1.5-6.9-2-2-5-2.4-7.4-1.3L9 6 6 9 1.6 4.7C.4 7.1.9 10.1 2.9 12.1c1.9 1.9 4.6 2.4 6.9 1.5l9.1 9.1c.4.4 1 .4 1.4 0l2.3-2.3c.5-.4.5-1.1.1-1.4z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Creation Process</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <div style=\"display:flex; flex-direction:column; gap:8px;\">\n                                \n                                    <div style=\"display:flex; align-items:center; gap:12px; padding:10px 14px; background:rgba(139,92,246,0.05); border-radius:10px;\">\n                                        <div style=\"\n                                            width:32px; height:32px; border-radius:50%;\n                                            background: linear-gradient(135deg, #8b5cf6, #6d28d9);\n                                            color: #fff; font-weight:700; font-size:0.85rem;\n                                            display:flex; align-items:center; justify-content:center;\n                                            flex-shrink:0;\n                                        \">1</div>\n                                        <span style=\"font-size:0.95rem;\">Research — Gather sources and data</span>\n                                    </div>\n                                \n                                    <div style=\"display:flex; align-items:center; gap:12px; padding:10px 14px; background:transparent; border-radius:10px;\">\n                                        <div style=\"\n                                            width:32px; height:32px; border-radius:50%;\n                                            background: linear-gradient(135deg, #8b5cf6, #6d28d9);\n                                            color: #fff; font-weight:700; font-size:0.85rem;\n                                            display:flex; align-items:center; justify-content:center;\n                                            flex-shrink:0;\n                                        \">2</div>\n                                        <span style=\"font-size:0.95rem;\">Selection — Curate and filter what is relevant</span>\n                                    </div>\n                                \n                                    <div style=\"display:flex; align-items:center; gap:12px; padding:10px 14px; background:rgba(139,92,246,0.05); border-radius:10px;\">\n                                        <div style=\"\n                                            width:32px; height:32px; border-radius:50%;\n                                            background: linear-gradient(135deg, #8b5cf6, #6d28d9);\n                                            color: #fff; font-weight:700; font-size:0.85rem;\n                                            display:flex; align-items:center; justify-content:center;\n                                            flex-shrink:0;\n                                        \">3</div>\n                                        <span style=\"font-size:0.95rem;\">Sketch — Plan the visual structure</span>\n                                    </div>\n                                \n                                    <div style=\"display:flex; align-items:center; gap:12px; padding:10px 14px; background:transparent; border-radius:10px;\">\n                                        <div style=\"\n                                            width:32px; height:32px; border-radius:50%;\n                                            background: linear-gradient(135deg, #8b5cf6, #6d28d9);\n                                            color: #fff; font-weight:700; font-size:0.85rem;\n                                            display:flex; align-items:center; justify-content:center;\n                                            flex-shrink:0;\n                                        \">4</div>\n                                        <span style=\"font-size:0.95rem;\">Production — Build the piece with tools</span>\n                                    </div>\n                                \n                                    <div style=\"display:flex; align-items:center; gap:12px; padding:10px 14px; background:rgba(139,92,246,0.05); border-radius:10px;\">\n                                        <div style=\"\n                                            width:32px; height:32px; border-radius:50%;\n                                            background: linear-gradient(135deg, #8b5cf6, #6d28d9);\n                                            color: #fff; font-weight:700; font-size:0.85rem;\n                                            display:flex; align-items:center; justify-content:center;\n                                            flex-shrink:0;\n                                        \">5</div>\n                                        <span style=\"font-size:0.95rem;\">Reception — The receiver generates knowledge</span>\n                                    </div>\n                                \n                            </div>\n                        \n            </div>\n        </div>\n                    "},"s1":{"sectionTitle":"2. History of Infographics"},"s1i0":{"title":"Historical Milestones","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #f59e0b, #d97706);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M13 3a9 9 0 0 0-9 9H1l3.89 3.89.07.14L9 12H6c0-3.87 3.13-7 7-7s7 3.13 7 7-3.13 7-7 7c-1.93 0-3.68-.79-4.94-2.06l-1.42 1.42A8.954 8.954 0 0 0 13 21a9 9 0 0 0 0-18zm-1 5v5l4.28 2.54.72-1.21-3.5-2.08V8H12z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Timeline</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <table style=\"\n            width: 100%;\n            border-collapse: collapse;\n            border-radius: 12px;\n            overflow: hidden;\n            box-shadow: 0 1px 6px rgba(0,0,0,0.06);\n            margin: 12px 0;\n        \"><thead><tr><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Milestone</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Date</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Detail</th></tr></thead><tbody><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Da Vinci</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Renaissance</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Technical drawing as empirical research</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Mercator</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">1569</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Projection: preserves angles, distorts sizes</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>L'Encyclopédie</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">18th c.</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Diderot and D'Alembert: technical engravings</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Isotype</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">1920s</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Neurath and Arntz: standardized pictograms</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>The Times</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">1806</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">First newspaper infographic</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>USA Today</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">1982</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Snapshots: daily color graphics</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Gulf War</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">1991</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Infographics replaced photography</td></tr></tbody></table>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            background: #ef444408;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #ef4444; font-size: 0.92rem;\">\n                Exam Trap — Mercator\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">The Mercator projection (1569) preserves <strong>angles</strong> (navigation) but distorts <strong>sizes</strong> in polar regions. Greenland appears to be the size of Africa when in reality it is <strong>14 times smaller</strong>.</div>\n        </div>\n                        \n        <div style=\"\n            background: #8b5cf608;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #8b5cf6; font-size: 0.92rem;\">\n                Isotype (1920s)\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">Neurath and Arntz created a system of <strong>standardized pictograms</strong> to communicate social and economic statistics to people of any educational level or language.</div>\n        </div>\n                    "},"s2":{"sectionTitle":"3. Working with Data"},"s2i0":{"title":"Variable Types and Data Wrangling","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #10b981, #059669);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M3 13h8V3H3v10zm0 8h8v-6H3v6zm10 0h8V11h-8v10zm0-18v6h8V3h-8z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Variables</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <div style=\"display:grid; grid-template-columns:1fr 1fr; gap:16px;\">\n                                <div style=\"background:#10b98110; border-radius:12px; padding:14px; border:1px solid #10b98125;\">\n                                    <div style=\"font-weight:700; color:#10b981; margin-bottom:6px;\">Categorical</div>\n                                    <p style=\"margin:0; font-size:0.9rem;\">Groups / labels<br>E.g.: Country, Gender, Type<br>Encoding: \n        <span style=\"\n            display: inline-block;\n            background: #10b98118;\n            color: #10b981;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #10b98130;\n            margin: 2px 3px;\n        \">Color</span> \n        <span style=\"\n            display: inline-block;\n            background: #10b98118;\n            color: #10b981;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #10b98130;\n            margin: 2px 3px;\n        \">Shape</span></p>\n                                </div>\n                                <div style=\"background:#3b82f610; border-radius:12px; padding:14px; border:1px solid #3b82f625;\">\n                                    <div style=\"font-weight:700; color:#3b82f6; margin-bottom:6px;\">Quantitative</div>\n                                    <p style=\"margin:0; font-size:0.9rem;\">Numeric magnitudes<br>E.g.: Sales, Temperature<br>Encoding: \n        <span style=\"\n            display: inline-block;\n            background: #3b82f618;\n            color: #3b82f6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #3b82f630;\n            margin: 2px 3px;\n        \">Position</span> \n        <span style=\"\n            display: inline-block;\n            background: #3b82f618;\n            color: #3b82f6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #3b82f630;\n            margin: 2px 3px;\n        \">Length</span></p>\n                                </div>\n                            </div>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #6366f1, #4f46e5);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M5 9.2h3V19H5V9.2zM10.6 5h2.8v14h-2.8V5zm5.6 8H19v6h-2.8v-6z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">NOIR Scales (Measurement Types)</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <p>Data is classified as <strong>qualitative</strong> vs <strong>quantitative</strong>, and is measured on 4 scales:</p>\n                            <table style=\"\n            width: 100%;\n            border-collapse: collapse;\n            border-radius: 12px;\n            overflow: hidden;\n            box-shadow: 0 1px 6px rgba(0,0,0,0.06);\n            margin: 12px 0;\n        \"><thead><tr><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Scale</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Type</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Example</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Operations</th></tr></thead><tbody><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Nominal</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #10b98118;\n            color: #10b981;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #10b98130;\n            margin: 2px 3px;\n        \">Qualitative</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Country, Color, Gender</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">= ≠</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Ordinal</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #10b98118;\n            color: #10b981;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #10b98130;\n            margin: 2px 3px;\n        \">Qualitative</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Low/Medium/High, Ranking</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">= ≠ < ></td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Interval</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #3b82f618;\n            color: #3b82f6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #3b82f630;\n            margin: 2px 3px;\n        \">Quantitative</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Temperature °C, Date</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">= ≠ < > + −</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Ratio</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #3b82f618;\n            color: #3b82f6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #3b82f630;\n            margin: 2px 3px;\n        \">Quantitative</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Weight, Income, Distance</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">= ≠ < > + − × ÷</td></tr></tbody></table>\n                            \n        <div style=\"\n            background: #6366f108;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #6366f1; font-size: 0.92rem;\">\n                Key difference: Interval vs Ratio\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\"><strong>Interval:</strong> zero is arbitrary (0°C is not \"absence of temperature\").<br><strong>Ratio:</strong> zero is absolute (0 kg = no weight). Only Ratio allows you to say \"twice as...\".</div>\n        </div>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #f59e0b, #d97706);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M22.7 19l-9.1-9.1c.9-2.3.4-5-1.5-6.9-2-2-5-2.4-7.4-1.3L9 6 6 9 1.6 4.7C.4 7.1.9 10.1 2.9 12.1c1.9 1.9 4.6 2.4 6.9 1.5l9.1 9.1c.4.4 1 .4 1.4 0l2.3-2.3c.5-.4.5-1.1.1-1.4z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Data Wrangling</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <p>Process of cleaning, transforming, and preparing raw data:</p>\n                            <div style=\"display:grid; grid-template-columns:1fr 1fr; gap:8px;\">\n                                \n                                    <div style=\"display:flex; align-items:center; gap:8px; padding:8px 12px; background:#f59e0b08; border-radius:8px; border:1px solid #f59e0b15;\">\n                                        <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#f59e0b\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M22.7 19l-9.1-9.1c.9-2.3.4-5-1.5-6.9-2-2-5-2.4-7.4-1.3L9 6 6 9 1.6 4.7C.4 7.1.9 10.1 2.9 12.1c1.9 1.9 4.6 2.4 6.9 1.5l9.1 9.1c.4.4 1 .4 1.4 0l2.3-2.3c.5-.4.5-1.1.1-1.4z\"/></svg> <span style=\"font-size:0.9rem;\">Remove duplicates</span>\n                                    </div>\n                                \n                                    <div style=\"display:flex; align-items:center; gap:8px; padding:8px 12px; background:#f59e0b08; border-radius:8px; border:1px solid #f59e0b15;\">\n                                        <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#f59e0b\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M22.7 19l-9.1-9.1c.9-2.3.4-5-1.5-6.9-2-2-5-2.4-7.4-1.3L9 6 6 9 1.6 4.7C.4 7.1.9 10.1 2.9 12.1c1.9 1.9 4.6 2.4 6.9 1.5l9.1 9.1c.4.4 1 .4 1.4 0l2.3-2.3c.5-.4.5-1.1.1-1.4z\"/></svg> <span style=\"font-size:0.9rem;\">Handle null values</span>\n                                    </div>\n                                \n                                    <div style=\"display:flex; align-items:center; gap:8px; padding:8px 12px; background:#f59e0b08; border-radius:8px; border:1px solid #f59e0b15;\">\n                                        <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#f59e0b\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M22.7 19l-9.1-9.1c.9-2.3.4-5-1.5-6.9-2-2-5-2.4-7.4-1.3L9 6 6 9 1.6 4.7C.4 7.1.9 10.1 2.9 12.1c1.9 1.9 4.6 2.4 6.9 1.5l9.1 9.1c.4.4 1 .4 1.4 0l2.3-2.3c.5-.4.5-1.1.1-1.4z\"/></svg> <span style=\"font-size:0.9rem;\">Normalize dates</span>\n                                    </div>\n                                \n                                    <div style=\"display:flex; align-items:center; gap:8px; padding:8px 12px; background:#f59e0b08; border-radius:8px; border:1px solid #f59e0b15;\">\n                                        <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#f59e0b\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M22.7 19l-9.1-9.1c.9-2.3.4-5-1.5-6.9-2-2-5-2.4-7.4-1.3L9 6 6 9 1.6 4.7C.4 7.1.9 10.1 2.9 12.1c1.9 1.9 4.6 2.4 6.9 1.5l9.1 9.1c.4.4 1 .4 1.4 0l2.3-2.3c.5-.4.5-1.1.1-1.4z\"/></svg> <span style=\"font-size:0.9rem;\">Restructure tables</span>\n                                    </div>\n                                \n                            </div>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            background: #ef444408;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #ef4444; font-size: 0.92rem;\">\n                Garbage In, Garbage Out\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">If the input data is wrong, <strong>no visual design can make up for it</strong>. The quality of the result depends directly on the quality of the data.</div>\n        </div>\n                    "},"s3":{"sectionTitle":"4. Psychology of Perception (Gestalt)"},"s3i0":{"title":"Types of Memory","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #8b5cf6, #7c3aed);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M12 2a9 9 0 0 0-9 9c0 3.07 1.98 5.73 4.73 6.73A1 1 0 0 1 8.5 19H12v3h1v-3h3.5a1 1 0 0 1 .77-1.27A7 7 0 0 0 21 11a9 9 0 0 0-9-9z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Visual Memory System</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <table style=\"\n            width: 100%;\n            border-collapse: collapse;\n            border-radius: 12px;\n            overflow: hidden;\n            box-shadow: 0 1px 6px rgba(0,0,0,0.06);\n            margin: 12px 0;\n        \"><thead><tr><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Type</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Function</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Speed</th></tr></thead><tbody><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong style=\"color:#ef4444;\">Iconic</strong> (sensory)</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">First filter: captures color, position</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><em>Milliseconds</em></td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong style=\"color:#f59e0b;\">Short-term</strong> (working)</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Consciously processes information</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><em>Seconds</em></td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong style=\"color:#10b981;\">Long-term</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Learned conventions and symbols</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><em>Permanent</em></td></tr></tbody></table>\n                            \n        <div style=\"\n            background: #4f6ef708;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #4f6ef7; font-size: 0.92rem;\">\n                Pre-attentive Attributes\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">Properties detected <strong>automatically and instantly</strong>: color, size, orientation, shape. They are the foundation of design because they guide attention without conscious effort.</div>\n        </div>\n                        \n            </div>\n        </div>\n                    "},"s3i1":{"title":"Gestalt Principles","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #ec4899, #db2777);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M12 4.5C7 4.5 2.73 7.61 1 12c1.73 4.39 6 7.5 11 7.5s9.27-3.11 11-7.5c-1.73-4.39-6-7.5-11-7.5zM12 17c-2.76 0-5-2.24-5-5s2.24-5 5-5 5 2.24 5 5-2.24 5-5 5zm0-8c-1.66 0-3 1.34-3 3s1.34 3 3 3 3-1.34 3-3-1.34-3-3-3z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Laws of Perception</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <table style=\"\n            width: 100%;\n            border-collapse: collapse;\n            border-radius: 12px;\n            overflow: hidden;\n            box-shadow: 0 1px 6px rgba(0,0,0,0.06);\n            margin: 12px 0;\n        \"><thead><tr><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Principle</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">What It Says</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Example in Visualization</th></tr></thead><tbody><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Proximity</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Nearby elements = group</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Points close together in a scatter plot</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Similarity</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Similar elements = group</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Same color = same category</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Continuity</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">The eye follows smooth lines</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Smooth line chart</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Closure</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">The brain completes incomplete shapes</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Arcs perceived as circles</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Figure-ground</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">We separate the object from the background</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Data on a neutral background</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Connection</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Connecting line = relationship</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Connected nodes in a diagram</td></tr></tbody></table>\n                        \n            </div>\n        </div>\n                    "},"s4":{"sectionTitle":"5. Design Applied to Visualization"},"s4i0":{"title":"Typography and Color","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #f97316, #ea580c);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M7 14c-1.66 0-3 1.34-3 3 0 1.31-1.16 2-2 2 .92 1.22 2.49 2 4 2 2.21 0 4-1.79 4-4 0-1.66-1.34-3-3-3zm13.71-9.37l-1.34-1.34a.996.996 0 0 0-1.41 0L9 12.25 11.75 15l8.96-8.96a.996.996 0 0 0 0-1.41z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Typography</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <div style=\"display:grid; grid-template-columns:1fr 1fr; gap:16px;\">\n                                <div style=\"background:#f9731610; border-radius:12px; padding:14px; border:1px solid #f9731625; text-align:center;\">\n                                    <div style=\"font-family: Georgia, serif; font-size:1.6rem; color:#f97316; margin-bottom:4px;\">Aa</div>\n                                    <div style=\"font-weight:700; margin-bottom:4px;\">Serif</div>\n                                    <p style=\"margin:0; font-size:0.85rem;\">With finishing strokes. They guide the eye.<br><strong>Best for: printed paper</strong></p>\n                                </div>\n                                <div style=\"background:#4f6ef710; border-radius:12px; padding:14px; border:1px solid #4f6ef725; text-align:center;\">\n                                    <div style=\"font-family: Arial, sans-serif; font-size:1.6rem; color:#4f6ef7; margin-bottom:4px;\">Aa</div>\n                                    <div style=\"font-weight:700; margin-bottom:4px;\">Sans Serif</div>\n                                    <p style=\"margin:0; font-size:0.85rem;\">Without finishing strokes. Clean.<br><strong>Best for: screens</strong></p>\n                                </div>\n                            </div>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M12 3c-4.97 0-9 4.03-9 9s4.03 9 9 9c.83 0 1.5-.67 1.5-1.5 0-.39-.15-.74-.39-1.01-.23-.26-.38-.61-.38-1-.01-.83.67-1.5 1.5-1.5H16c2.76 0 5-2.24 5-5 0-4.42-4.03-8-9-8zm-5.5 9c-.83 0-1.5-.67-1.5-1.5S5.67 9 6.5 9 8 9.67 8 10.5 7.33 12 6.5 12zm3-4C8.67 8 8 7.33 8 6.5S8.67 5 9.5 5s1.5.67 1.5 1.5S10.33 8 9.5 8zm5 0c-.83 0-1.5-.67-1.5-1.5S13.67 5 14.5 5s1.5.67 1.5 1.5S15.33 8 14.5 8zm3 4c-.83 0-1.5-.67-1.5-1.5S16.67 9 17.5 9s1.5.67 1.5 1.5-.67 1.5-1.5 1.5z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Color Models</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <div style=\"display:grid; grid-template-columns:1fr 1fr 1fr; gap:12px;\">\n                                <div style=\"background: linear-gradient(135deg, #ff000020, #00ff0020, #0000ff20); border-radius:12px; padding:14px; border:1px solid #4f6ef720; text-align:center;\">\n                                    <div style=\"font-weight:700; font-size:1.1rem; margin-bottom:4px;\">RGB</div>\n                                    <p style=\"margin:0; font-size:0.85rem;\">Additive (lights)<br>\n        <span style=\"\n            display: inline-block;\n            background: #3b82f618;\n            color: #3b82f6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #3b82f630;\n            margin: 2px 3px;\n        \">Screens</span></p>\n                                </div>\n                                <div style=\"background: linear-gradient(135deg, #00ffff20, #ff00ff20, #ffff0020); border-radius:12px; padding:14px; border:1px solid #8b5cf620; text-align:center;\">\n                                    <div style=\"font-weight:700; font-size:1.1rem; margin-bottom:4px;\">CMYK</div>\n                                    <p style=\"margin:0; font-size:0.85rem;\">Subtractive (inks)<br>\n        <span style=\"\n            display: inline-block;\n            background: #8b5cf618;\n            color: #8b5cf6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #8b5cf630;\n            margin: 2px 3px;\n        \">Printing</span></p>\n                                </div>\n                                <div style=\"background: linear-gradient(135deg, #e11d4820, #f59e0b20, #10b98120); border-radius:12px; padding:14px; border:1px solid #f59e0b20; text-align:center;\">\n                                    <div style=\"font-weight:700; font-size:1.1rem; margin-bottom:4px;\">HSL / HSB</div>\n                                    <p style=\"margin:0; font-size:0.85rem;\">Hue, Saturation, Lightness<br>\n        <span style=\"\n            display: inline-block;\n            background: #f59e0b18;\n            color: #f59e0b;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #f59e0b30;\n            margin: 2px 3px;\n        \">Intuitive</span></p>\n                                </div>\n                            </div>\n                            \n        <div style=\"\n            background: #7c3aed08;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #7c3aed; font-size: 0.92rem;\">\n                Pre-attentive Color Processing\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">The brain detects differences in <strong>hue</strong> in a <strong>pre-attentive</strong> manner (before reasoning), which makes it possible to identify categories instantly. That is why color is ideal for qualitative/categorical data, but <strong>not for quantitative magnitudes</strong>.</div>\n        </div>\n                        \n            </div>\n        </div>\n                    "},"s4i1":{"title":"Image Formats","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #10b981, #059669);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M9.4 16.6L4.8 12l4.6-4.6L8 6l-6 6 6 6 1.4-1.4zm5.2 0l4.6-4.6-4.6-4.6L16 6l6 6-6 6-1.4-1.4z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Formats</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <table style=\"\n            width: 100%;\n            border-collapse: collapse;\n            border-radius: 12px;\n            overflow: hidden;\n            box-shadow: 0 1px 6px rgba(0,0,0,0.06);\n            margin: 12px 0;\n        \"><thead><tr><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Format</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Type</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Main Use</th></tr></thead><tbody><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>SVG</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #10b98118;\n            color: #10b981;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #10b98130;\n            margin: 2px 3px;\n        \">Vector</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Web — infinitely scalable</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>JPEG</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #f59e0b18;\n            color: #f59e0b;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #f59e0b30;\n            margin: 2px 3px;\n        \">Raster</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Web photographs (lossy)</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>PNG</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #f59e0b18;\n            color: #f59e0b;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #f59e0b30;\n            margin: 2px 3px;\n        \">Raster</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Web transparency (lossless)</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>TIFF</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #f59e0b18;\n            color: #f59e0b;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #f59e0b30;\n            margin: 2px 3px;\n        \">Raster</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Professional printing</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>EPS</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #10b98118;\n            color: #10b981;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #10b98130;\n            margin: 2px 3px;\n        \">Vector</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Printing — does NOT work in browsers</td></tr></tbody></table>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            background: #8b5cf608;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #8b5cf6; font-size: 0.92rem;\">\n                Fundamental Principle\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\"><strong>\"Form must be at the service of function\"</strong> — aesthetics must never compromise the clarity of the data's message.</div>\n        </div>\n                    "},"s5":{"sectionTitle":"6. Anatomy of a Chart"},"s5i0":{"title":"Chart Elements and Types","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #3b82f6, #2563eb);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M5 9.2h3V19H5V9.2zM10.6 5h2.8v14h-2.8V5zm5.6 8H19v6h-2.8v-6z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Elements of a Chart</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <div style=\"display:flex; flex-wrap:wrap; gap:6px; justify-content:center; padding:10px 0;\">\n                                \n        <span style=\"\n            display: inline-block;\n            background: #3b82f618;\n            color: #3b82f6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #3b82f630;\n            margin: 2px 3px;\n        \">Title</span> → \n        <span style=\"\n            display: inline-block;\n            background: #3b82f618;\n            color: #3b82f6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #3b82f630;\n            margin: 2px 3px;\n        \">Subtitle</span> → \n        <span style=\"\n            display: inline-block;\n            background: #3b82f618;\n            color: #3b82f6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #3b82f630;\n            margin: 2px 3px;\n        \">X-axis</span> → \n        <span style=\"\n            display: inline-block;\n            background: #3b82f618;\n            color: #3b82f6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #3b82f630;\n            margin: 2px 3px;\n        \">Y-axis</span> → \n        <span style=\"\n            display: inline-block;\n            background: #3b82f618;\n            color: #3b82f6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #3b82f630;\n            margin: 2px 3px;\n        \">Legend</span> → \n        <span style=\"\n            display: inline-block;\n            background: #3b82f618;\n            color: #3b82f6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #3b82f630;\n            margin: 2px 3px;\n        \">Data area</span> → \n        <span style=\"\n            display: inline-block;\n            background: #3b82f618;\n            color: #3b82f6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #3b82f630;\n            margin: 2px 3px;\n        \">Labels</span> → \n        <span style=\"\n            display: inline-block;\n            background: #3b82f618;\n            color: #3b82f6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #3b82f630;\n            margin: 2px 3px;\n        \">Source</span> → \n        <span style=\"\n            display: inline-block;\n            background: #3b82f618;\n            color: #3b82f6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #3b82f630;\n            margin: 2px 3px;\n        \">Scale</span> → \n        <span style=\"\n            display: inline-block;\n            background: #3b82f618;\n            color: #3b82f6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #3b82f630;\n            margin: 2px 3px;\n        \">Grid</span>\n                            </div>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #8b5cf6, #6d28d9);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M11.99 18.54l-7.37-5.73L3 14.07l9 7 9-7-1.63-1.27zM12 16l7.36-5.73L21 9l-9-7-9 7 1.63 1.27L12 16z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Chart Types</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <table style=\"\n            width: 100%;\n            border-collapse: collapse;\n            border-radius: 12px;\n            overflow: hidden;\n            box-shadow: 0 1px 6px rgba(0,0,0,0.06);\n            margin: 12px 0;\n        \"><thead><tr><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Type</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Best For</th></tr></thead><tbody><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Bars</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Comparing categories</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Lines</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Trends over time</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Pie (circular)</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Part-to-whole relationship (criticized for imprecision)</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Choropleths</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Statistical data by geographic region</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Timeline</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Placing events in chronological order</td></tr></tbody></table>\n                            <div style=\"display:grid; grid-template-columns:1fr 1fr; gap:12px; margin-top:12px;\">\n                                <div style=\"text-align:center; padding:10px; background:#f9731610; border-radius:10px; border:1px solid #f9731620;\">\n                                    <strong style=\"color:#f97316;\">Figurative</strong><br>\n                                    <span style=\"font-size:0.85rem;\">Resembles reality (maps, illustrations)</span>\n                                </div>\n                                <div style=\"text-align:center; padding:10px; background:#4f6ef710; border-radius:10px; border:1px solid #4f6ef720;\">\n                                    <strong style=\"color:#4f6ef7;\">Non-figurative</strong><br>\n                                    <span style=\"font-size:0.85rem;\">Abstract shapes (bars, lines, areas)</span>\n                                </div>\n                            </div>\n                        \n            </div>\n        </div>\n                    "},"s6":{"sectionTitle":"7. Graphical Encoding"},"s6i0":{"title":"Cleveland and McGill Hierarchy","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #ef4444, #dc2626);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M7 2v11h3v9l7-12h-4l4-8z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">CRITICAL EXAM CONCEPT</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <div style=\"\n                                text-align:center;\n                                padding: 20px;\n                                background: linear-gradient(135deg, #ef444410, #dc262610);\n                                border-radius: 12px;\n                                margin-bottom: 12px;\n                            \">\n                                <div style=\"font-weight:800; font-size:1.1rem; margin-bottom:12px; color:#ef4444;\">Effectiveness Hierarchy (most → least accurate)</div>\n                                <div style=\"display:flex; align-items:center; justify-content:center; gap:6px; flex-wrap:wrap; font-size:0.95rem;\">\n                                    \n        <span style=\"\n            display: inline-block;\n            background: #10b98118;\n            color: #10b981;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #10b98130;\n            margin: 2px 3px;\n        \">Position</span>\n                                    <span style=\"color:#ef4444; font-weight:700;\">></span>\n                                    \n        <span style=\"\n            display: inline-block;\n            background: #3b82f618;\n            color: #3b82f6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #3b82f630;\n            margin: 2px 3px;\n        \">Length</span>\n                                    <span style=\"color:#ef4444; font-weight:700;\">></span>\n                                    \n        <span style=\"\n            display: inline-block;\n            background: #f59e0b18;\n            color: #f59e0b;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #f59e0b30;\n            margin: 2px 3px;\n        \">Angle</span>\n                                    <span style=\"color:#ef4444; font-weight:700;\">></span>\n                                    \n        <span style=\"\n            display: inline-block;\n            background: #f9731618;\n            color: #f97316;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #f9731630;\n            margin: 2px 3px;\n        \">Area</span>\n                                    <span style=\"color:#ef4444; font-weight:700;\">></span>\n                                    \n        <span style=\"\n            display: inline-block;\n            background: #ef444418;\n            color: #ef4444;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #ef444430;\n            margin: 2px 3px;\n        \">Color</span>\n                                </div>\n                            </div>\n                            <table style=\"\n            width: 100%;\n            border-collapse: collapse;\n            border-radius: 12px;\n            overflow: hidden;\n            box-shadow: 0 1px 6px rgba(0,0,0,0.06);\n            margin: 12px 0;\n        \"><thead><tr><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Attribute</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Accuracy</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Example</th></tr></thead><tbody><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Position</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #10b98118;\n            color: #10b981;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #10b98130;\n            margin: 2px 3px;\n        \">Highest</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Scatter plots, points</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Length</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #3b82f618;\n            color: #3b82f6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #3b82f630;\n            margin: 2px 3px;\n        \">Very high</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Bar charts</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Angle</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #f59e0b18;\n            color: #f59e0b;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #f59e0b30;\n            margin: 2px 3px;\n        \">Medium</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Pie charts — criticized!</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Area</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #f9731618;\n            color: #f97316;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #f9731630;\n            margin: 2px 3px;\n        \">Low</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Bubble charts</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Color</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #ef444418;\n            color: #ef4444;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #ef444430;\n            margin: 2px 3px;\n        \">Categorical</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Best for types, NOT magnitudes</td></tr></tbody></table>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M12 10.9c-.61 0-1.1.49-1.1 1.1s.49 1.1 1.1 1.1c.61 0 1.1-.49 1.1-1.1s-.49-1.1-1.1-1.1zM12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm2.19 12.19L6 18l3.81-8.19L18 6l-3.81 8.19z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Two Branches of Visualization</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <div style=\"display:grid; grid-template-columns:1fr 1fr; gap:16px;\">\n                                <div style=\"background:#10b98110; border-radius:12px; padding:14px; border:1px solid #10b98125;\">\n                                    <div style=\"font-weight:700; color:#10b981; margin-bottom:6px;\">Scientific Viz.</div>\n                                    <p style=\"margin:0; font-size:0.9rem;\">Data with <strong>physical structure</strong>: anatomy, climate, molecules, terrain.</p>\n                                </div>\n                                <div style=\"background:#4f6ef710; border-radius:12px; padding:14px; border:1px solid #4f6ef725;\">\n                                    <div style=\"font-weight:700; color:#4f6ef7; margin-bottom:6px;\">Information Viz.</div>\n                                    <p style=\"margin:0; font-size:0.9rem;\">Data that is <strong>abstract</strong>: sales, social networks, finance, logistics.</p>\n                                </div>\n                            </div>\n                        \n            </div>\n        </div>\n                    "},"s7":{"sectionTitle":"8. Static Visualization"},"s7i0":{"title":"Tools and Formats","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #f97316, #ea580c);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M7 14c-1.66 0-3 1.34-3 3 0 1.31-1.16 2-2 2 .92 1.22 2.49 2 4 2 2.21 0 4-1.79 4-4 0-1.66-1.34-3-3-3zm13.71-9.37l-1.34-1.34a.996.996 0 0 0-1.41 0L9 12.25 11.75 15l8.96-8.96a.996.996 0 0 0 0-1.41z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Professional Tools</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <table style=\"\n            width: 100%;\n            border-collapse: collapse;\n            border-radius: 12px;\n            overflow: hidden;\n            box-shadow: 0 1px 6px rgba(0,0,0,0.06);\n            margin: 12px 0;\n        \"><thead><tr><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Tool</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Type</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Use</th></tr></thead><tbody><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Adobe Illustrator</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #f9731618;\n            color: #f97316;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #f9731630;\n            margin: 2px 3px;\n        \">Professional</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Industry standard for vector infographics</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Inkscape</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #10b98118;\n            color: #10b981;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #10b98130;\n            margin: 2px 3px;\n        \">Free</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Open-source alternative (native SVG)</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Canva</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #e11d4818;\n            color: #e11d48;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #e11d4830;\n            margin: 2px 3px;\n        \">Web</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Drag-and-drop templates, no design skills required</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Infogram</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #3b82f618;\n            color: #3b82f6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #3b82f630;\n            margin: 2px 3px;\n        \">Web</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Create infographics and interactive charts online</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Piktochart</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #8b5cf618;\n            color: #8b5cf6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #8b5cf630;\n            margin: 2px 3px;\n        \">Web</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Quick infographics with templates</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Easelly</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #05966918;\n            color: #059669;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #05966930;\n            margin: 2px 3px;\n        \">Web</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Simple drag-and-drop infographics</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Tableau</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #e9762718;\n            color: #e97627;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #e9762730;\n            margin: 2px 3px;\n        \">Dashboard</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Interactive dashboards, KPIs, visual analysis</td></tr></tbody></table>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #8b5cf6, #7c3aed);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M12 4.5C7 4.5 2.73 7.61 1 12c1.73 4.39 6 7.5 11 7.5s9.27-3.11 11-7.5c-1.73-4.39-6-7.5-11-7.5zM12 17c-2.76 0-5-2.24-5-5s2.24-5 5-5 5 2.24 5 5-2.24 5-5 5zm0-8c-1.66 0-3 1.34-3 3s1.34 3 3 3 3-1.34 3-3-1.34-3-3-3z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Resolutions</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <div style=\"display:grid; grid-template-columns:1fr 1fr; gap:16px;\">\n                                <div style=\"text-align:center; padding:14px; background:#8b5cf610; border-radius:12px;\">\n                                    <div style=\"font-size:2rem; font-weight:800; color:#8b5cf6;\">300</div>\n                                    <div style=\"font-weight:600; font-size:0.85rem;\">dpi (DPI) — Printing</div>\n                                </div>\n                                <div style=\"text-align:center; padding:14px; background:#6b728010; border-radius:12px;\">\n                                    <div style=\"font-size:2rem; font-weight:800; color:#6b7280;\">72-96</div>\n                                    <div style=\"font-weight:600; font-size:0.85rem;\">ppi — Screens</div>\n                                </div>\n                            </div>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            background: #ef444408;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #ef4444; font-size: 0.92rem;\">\n                Exam Trap\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\"><strong>EPS</strong> is a vector format for printing but <strong>is NOT compatible</strong> with web browsers. <strong>SVG</strong> is the web vector format.</div>\n        </div>\n                    "},"s8":{"sectionTitle":"9. Exploratory Visualization"},"s8i0":{"title":"Tools and Technologies","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M9.4 16.6L4.8 12l4.6-4.6L8 6l-6 6 6 6 1.4-1.4zm5.2 0l4.6-4.6-4.6-4.6L16 6l6 6-6 6-1.4-1.4z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Web Technologies</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <div style=\"display:flex; gap:12px; justify-content:center; flex-wrap:wrap; padding:10px 0;\">\n                                <div style=\"padding: 10px 20px; background: linear-gradient(135deg, #f97316, #ea580c); border-radius:10px; color:#fff; font-weight:700;\">HTML<br><span style=\"font-size:0.75rem; opacity:0.8;\">Structure</span></div>\n                                <div style=\"padding: 10px 20px; background: linear-gradient(135deg, #3b82f6, #2563eb); border-radius:10px; color:#fff; font-weight:700;\">CSS<br><span style=\"font-size:0.75rem; opacity:0.8;\">Style</span></div>\n                                <div style=\"padding: 10px 20px; background: linear-gradient(135deg, #f59e0b, #d97706); border-radius:10px; color:#fff; font-weight:700;\">JavaScript<br><span style=\"font-size:0.75rem; opacity:0.8;\">Interactivity</span></div>\n                            </div>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #10b981, #059669);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M12 10.9c-.61 0-1.1.49-1.1 1.1s.49 1.1 1.1 1.1c.61 0 1.1-.49 1.1-1.1s-.49-1.1-1.1-1.1zM12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm2.19 12.19L6 18l3.81-8.19L18 6l-3.81 8.19z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Key Tools</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <table style=\"\n            width: 100%;\n            border-collapse: collapse;\n            border-radius: 12px;\n            overflow: hidden;\n            box-shadow: 0 1px 6px rgba(0,0,0,0.06);\n            margin: 12px 0;\n        \"><thead><tr><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Tool</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Type</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Feature</th></tr></thead><tbody><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Gapminder</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Animated viz.</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Bubbles, ~200 indicators, open data</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Google Data Explorer</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Exploration</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">World Bank, OECD, Eurostat</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>CartoDB (CARTO)</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Interactive maps</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Free account for 12 months</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Flourish</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Visual storytelling</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Interactive templates for data journalism</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Tableau</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Dashboards and KPIs</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Drag and drop, interactive zoom, filters</td></tr></tbody></table>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            background: #10b98108;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #10b981; font-size: 0.92rem;\">\n                Gapminder World — Hans Rosling\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">Animated bubble chart: <strong>life expectancy</strong> (Y-axis) vs <strong>income per capita</strong> (X-axis). Bubble size = population. Data from public sources (<strong>open data</strong>).</div>\n        </div>\n                        \n        <div style=\"\n            background: #4f6ef708;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #4f6ef7; font-size: 0.92rem;\">\n                Shneiderman's Mantra\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\"><strong>\"Overview first, zoom and filter, then details-on-demand\"</strong><br>Fundamental principle of exploratory visualization: first an overview, then zoom to filter, and finally details on demand.</div>\n        </div>\n                    "},"s9":{"sectionTitle":"10. Visualization to Communicate"},"s9i0":{"title":"Datawrapper, Timeline, and Data Storytelling","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #ec4899, #db2777);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M18 11v2h4v-2h-4zm-2 6.61c.96.71 2.21 1.65 3.2 2.39.4-.53.8-1.07 1.2-1.6-.99-.74-2.24-1.68-3.2-2.4-.4.54-.8 1.08-1.2 1.61zM20.4 5.6c-.4-.53-.8-1.07-1.2-1.6-.99.74-2.24 1.68-3.2 2.4.4.53.8 1.07 1.2 1.6.96-.72 2.21-1.65 3.2-2.4zM4 9c-1.1 0-2 .9-2 2v2c0 1.1.9 2 2 2h1l5 3V6L5 9H4zm11.5 3c0-1.33-.58-2.53-1.5-3.35v6.69c.92-.81 1.5-2.01 1.5-3.34z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Communication Tools</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <table style=\"\n            width: 100%;\n            border-collapse: collapse;\n            border-radius: 12px;\n            overflow: hidden;\n            box-shadow: 0 1px 6px rgba(0,0,0,0.06);\n            margin: 12px 0;\n        \"><thead><tr><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Tool</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">What It Is</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Limitation</th></tr></thead><tbody><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Datawrapper</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Web platform: charts, maps, tables</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Focused on viz., not in-depth analysis</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Timeline.js</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Interactive timeline (Knight Lab)</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Requires Google Sheets as a source</td></tr></tbody></table>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #f59e0b, #d97706);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Data Storytelling</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <div style=\"display:flex; align-items:center; justify-content:center; gap:12px; padding:10px 0; flex-wrap:wrap; margin-bottom:10px;\">\n                                \n        <span style=\"\n            display: inline-block;\n            background: #3b82f618;\n            color: #3b82f6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #3b82f630;\n            margin: 2px 3px;\n        \">Data (evidence)</span>\n                                <span style=\"font-size:1.5em; color:#f59e0b;\">+</span>\n                                \n        <span style=\"\n            display: inline-block;\n            background: #10b98118;\n            color: #10b981;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #10b98130;\n            margin: 2px 3px;\n        \">Visualization (form)</span>\n                                <span style=\"font-size:1.5em; color:#f59e0b;\">+</span>\n                                \n        <span style=\"\n            display: inline-block;\n            background: #8b5cf618;\n            color: #8b5cf6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #8b5cf630;\n            margin: 2px 3px;\n        \">Narrative (common thread)</span>\n                            </div>\n                            \n        <div style=\"\n            background: #f59e0b08;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #f59e0b; font-size: 0.92rem;\">\n                Narrative Structure\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\"><strong>Introduction</strong> → <strong>Development</strong> → <strong>Conclusion</strong><br>Goal: not only to inform, but to <strong>persuade and inspire</strong>.</div>\n        </div>\n                        \n            </div>\n        </div>\n                    "},"s10":{"sectionTitle":"11. Ethics and Responsible Representation"},"s10i0":{"title":"Good and Bad Practices","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #6366f1, #4f46e5);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Edward Tufte — Data-Ink Ratio</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            \n        <div style=\"\n            background: #6366f108;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #6366f1; font-size: 0.92rem;\">\n                Data-Ink Ratio\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\"><strong>Edward Tufte</strong> coined the concept of the \"data-ink ratio\": the proportion of ink devoted to data vs. the total. Goal: <strong>maximize the ink that communicates data</strong> and eliminate <strong>chartjunk</strong> (unnecessary decorations).</div>\n        </div>\n                            \n        <div style=\"\n            background: #ef444408;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #ef4444; font-size: 0.92rem;\">\n                Chartjunk\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">Visual elements that do NOT provide information: 3D borders, decorative shadows, patterned backgrounds, effects that distract from the actual data.</div>\n        </div>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #10b981, #059669);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M12 1L3 5v6c0 5.55 3.84 10.74 9 12 5.16-1.26 9-6.45 9-12V5l-9-4z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Good Practices</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <div style=\"display:flex; flex-direction:column; gap:6px;\">\n                                \n                                    <div style=\"display:flex; align-items:center; gap:10px; padding:8px 12px; background:#10b98108; border-radius:8px;\">\n                                        <span style=\"color:#10b981; font-size:1.1rem;\">✓</span>\n                                        <span style=\"font-size:0.9rem;\">The Y-axis starts at zero (in bar charts)</span>\n                                    </div>\n                                \n                                    <div style=\"display:flex; align-items:center; gap:10px; padding:8px 12px; background:#10b98108; border-radius:8px;\">\n                                        <span style=\"color:#10b981; font-size:1.1rem;\">✓</span>\n                                        <span style=\"font-size:0.9rem;\">Proportional and linear scales</span>\n                                    </div>\n                                \n                                    <div style=\"display:flex; align-items:center; gap:10px; padding:8px 12px; background:#10b98108; border-radius:8px;\">\n                                        <span style=\"color:#10b981; font-size:1.1rem;\">✓</span>\n                                        <span style=\"font-size:0.9rem;\">Cite the original source of the data</span>\n                                    </div>\n                                \n                                    <div style=\"display:flex; align-items:center; gap:10px; padding:8px 12px; background:#10b98108; border-radius:8px;\">\n                                        <span style=\"color:#10b981; font-size:1.1rem;\">✓</span>\n                                        <span style=\"font-size:0.9rem;\">Clear and descriptive legends</span>\n                                    </div>\n                                \n                                    <div style=\"display:flex; align-items:center; gap:10px; padding:8px 12px; background:#10b98108; border-radius:8px;\">\n                                        <span style=\"color:#10b981; font-size:1.1rem;\">✓</span>\n                                        <span style=\"font-size:0.9rem;\">Use \"Own elaboration\" when appropriate</span>\n                                    </div>\n                                \n                            </div>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #ef4444, #dc2626);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M1 21h22L12 2 1 21zm12-3h-2v-2h2v2zm0-4h-2v-4h2v4z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Bad Practices (Red Flags)</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <div style=\"display:flex; flex-direction:column; gap:6px;\">\n                                \n                                    <div style=\"display:flex; align-items:center; gap:10px; padding:8px 12px; background:#ef444408; border-radius:8px;\">\n                                        <span style=\"color:#ef4444; font-size:1.1rem;\">✗</span>\n                                        <div><strong style=\"font-size:0.9rem;\">Truncated axes:</strong> <span style=\"font-size:0.85rem; color:#666;\">Exaggerate small differences</span></div>\n                                    </div>\n                                \n                                    <div style=\"display:flex; align-items:center; gap:10px; padding:8px 12px; background:#ef444408; border-radius:8px;\">\n                                        <span style=\"color:#ef4444; font-size:1.1rem;\">✗</span>\n                                        <div><strong style=\"font-size:0.9rem;\">Unnecessary 3D:</strong> <span style=\"font-size:0.85rem; color:#666;\">Distorts proportions (especially pie charts)</span></div>\n                                    </div>\n                                \n                                    <div style=\"display:flex; align-items:center; gap:10px; padding:8px 12px; background:#ef444408; border-radius:8px;\">\n                                        <span style=\"color:#ef4444; font-size:1.1rem;\">✗</span>\n                                        <div><strong style=\"font-size:0.9rem;\">Cherry-picking:</strong> <span style=\"font-size:0.85rem; color:#666;\">Selecting only data that supports the narrative</span></div>\n                                    </div>\n                                \n                                    <div style=\"display:flex; align-items:center; gap:10px; padding:8px 12px; background:#ef444408; border-radius:8px;\">\n                                        <span style=\"color:#ef4444; font-size:1.1rem;\">✗</span>\n                                        <div><strong style=\"font-size:0.9rem;\">Misleading colors:</strong> <span style=\"font-size:0.85rem; color:#666;\">Induce incorrect associations</span></div>\n                                    </div>\n                                \n                                    <div style=\"display:flex; align-items:center; gap:10px; padding:8px 12px; background:#ef444408; border-radius:8px;\">\n                                        <span style=\"color:#ef4444; font-size:1.1rem;\">✗</span>\n                                        <div><strong style=\"font-size:0.9rem;\">Non-linear scales:</strong> <span style=\"font-size:0.85rem; color:#666;\">Without technical justification</span></div>\n                                    </div>\n                                \n                                    <div style=\"display:flex; align-items:center; gap:10px; padding:8px 12px; background:#ef444408; border-radius:8px;\">\n                                        <span style=\"color:#ef4444; font-size:1.1rem;\">✗</span>\n                                        <div><strong style=\"font-size:0.9rem;\">Chartjunk (Tufte):</strong> <span style=\"font-size:0.85rem; color:#666;\">Decorations that do not provide information</span></div>\n                                    </div>\n                                \n                            </div>\n                        \n            </div>\n        </div>\n                    "},"s10i1":{"title":"Guiding Principle","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M12 1L3 5v6c0 5.55 3.84 10.74 9 12 5.16-1.26 9-6.45 9-12V5l-9-4z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Fundamental Principle</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <div style=\"\n                                text-align:center;\n                                padding: 30px 20px;\n                                background: linear-gradient(135deg, #4f6ef708, #7c3aed08);\n                                border-radius: 16px;\n                                border: 2px solid #4f6ef720;\n                            \">\n                                <div style=\"font-size:2.5rem; margin-bottom:12px;\"><svg viewBox=\"0 0 24 24\" width=\"40\" height=\"40\" fill=\"#4f6ef7\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M12 4.5C7 4.5 2.73 7.61 1 12c1.73 4.39 6 7.5 11 7.5s9.27-3.11 11-7.5c-1.73-4.39-6-7.5-11-7.5zM12 17c-2.76 0-5-2.24-5-5s2.24-5 5-5 5 2.24 5 5-2.24 5-5 5zm0-8c-1.66 0-3 1.34-3 3s1.34 3 3 3 3-1.34 3-3-1.34-3-3-3z\"/></svg></div>\n                                <div style=\"\n                                    font-size: 1.25rem;\n                                    font-weight: 800;\n                                    background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n                                    -webkit-background-clip: text;\n                                    -webkit-text-fill-color: transparent;\n                                    margin-bottom: 12px;\n                                \">\"Visualization should illuminate, not obscure.\"</div>\n                                <p style=\"margin:0; font-size:0.95rem; color:var(--text-color, #555);\">\n                                    Every choice of color, chart, scale, or perspective must represent the reality of the data <strong>faithfully</strong>.\n                                </p>\n                            </div>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            background: #f59e0b08;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #f59e0b; font-size: 0.92rem;\">\n                Case: London Underground Map (Harry Beck, 1933)\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\"><strong>Positive:</strong> extremely functional — easy to use and read.<br><strong>Criticism:</strong> it is a <strong>topological diagram</strong>; it does not reflect the actual geographic location of the stations. It sacrificed geographic accuracy for legibility.</div>\n        </div>\n                        \n        <div style=\"\n            background: #ef444408;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #ef4444; font-size: 0.92rem;\">\n                Criticism of Pie Charts\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">Angle and area are <strong>low-effectiveness</strong> attributes according to Cleveland and McGill. Better alternative: a <strong>bar chart</strong> (length is more accurate than angle).</div>\n        </div>\n                    "},"s11":{"sectionTitle":"12. FREQUENT EXAM TOPICS"},"s11i0":{"title":"Typography in Depth","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #f97316, #ea580c);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M7 14c-1.66 0-3 1.34-3 3 0 1.31-1.16 2-2 2 .92 1.22 2.49 2 4 2 2.21 0 4-1.79 4-4 0-1.66-1.34-3-3-3zm13.71-9.37l-1.34-1.34a.996.996 0 0 0-1.41 0L9 12.25 11.75 15l8.96-8.96a.996.996 0 0 0 0-1.41z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Typography — Key Concepts for the Exam</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <div style=\"display:grid; grid-template-columns:1fr 1fr; gap:16px; margin-bottom:14px;\">\n                                <div style=\"background:#f9731610; border-radius:12px; padding:14px; border:1px solid #f9731625; text-align:center;\">\n                                    <div style=\"font-family: Georgia, 'Times New Roman', serif; font-size:2rem; color:#f97316; margin-bottom:6px;\">Aa</div>\n                                    <div style=\"font-weight:700; margin-bottom:4px; font-size:1.05rem;\">SERIF (With serifs)</div>\n                                    <ul style=\"margin:0; padding-left:18px; font-size:0.88rem; text-align:left;\">\n                                        <li>They have <strong>small decorative strokes</strong> at the end of each letter</li>\n                                        <li>They guide the eye horizontally in long text</li>\n                                        <li><strong>Best for: PRINTED PAPER</strong></li>\n                                        <li>Examples: <em>Times New Roman, Georgia, Garamond</em></li>\n                                        <li>They convey: tradition, seriousness, trust</li>\n                                    </ul>\n                                </div>\n                                <div style=\"background:#4f6ef710; border-radius:12px; padding:14px; border:1px solid #4f6ef725; text-align:center;\">\n                                    <div style=\"font-family: Arial, Helvetica, sans-serif; font-size:2rem; color:#4f6ef7; margin-bottom:6px;\">Aa</div>\n                                    <div style=\"font-weight:700; margin-bottom:4px; font-size:1.05rem;\">SANS SERIF (Without serifs)</div>\n                                    <ul style=\"margin:0; padding-left:18px; font-size:0.88rem; text-align:left;\">\n                                        <li><strong>No decorative strokes</strong>, clean look</li>\n                                        <li>Better legibility at small sizes on screen</li>\n                                        <li><strong>Best for: DIGITAL SCREENS</strong></li>\n                                        <li>Examples: <em>Arial, Helvetica, Inter, Roboto</em></li>\n                                        <li>They convey: modernity, cleanliness, technology</li>\n                                    </ul>\n                                </div>\n                            </div>\n                            <table style=\"\n            width: 100%;\n            border-collapse: collapse;\n            border-radius: 12px;\n            overflow: hidden;\n            box-shadow: 0 1px 6px rgba(0,0,0,0.06);\n            margin: 12px 0;\n        \"><thead><tr><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Property</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Serif</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Sans Serif</th></tr></thead><tbody><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Serifs</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">✓ With serifs (\"feet\")</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">✗ Without serifs</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Ideal medium</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #f9731618;\n            color: #f97316;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #f9731630;\n            margin: 2px 3px;\n        \">Print / paper</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #4f6ef718;\n            color: #4f6ef7;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #4f6ef730;\n            margin: 2px 3px;\n        \">Digital screens</span></td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Long-form reading</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Better on paper (they guide the eye)</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Better on screen (sharpness)</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Feel</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Tradition, authority</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Modernity, simplicity</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">In visualization</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Formal titles</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Labels, axes, data</td></tr></tbody></table>\n                            \n        <div style=\"\n            background: #8b5cf608;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #8b5cf6; font-size: 0.92rem;\">\n                Other font types (supplementary)\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\"><strong>Monospaced:</strong> Every character takes up the same width (Courier, Consolas). Useful for code and data tables.<br><strong>Display/Decorative:</strong> Only for large titles. NEVER for body text or data labels — it reduces legibility.</div>\n        </div>\n                            \n        <div style=\"\n            background: #ef444408;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #ef4444; font-size: 0.92rem;\">\n                EXAM TRAP — Typography\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">Which type of font is best for <strong>screens</strong>? → <strong>Sans Serif</strong>.<br>Which type guides the eye better on <strong>printed paper</strong>? → <strong>Serif</strong>.<br>The key is to remember: <strong>Serif = paper, Sans Serif = screen</strong>.</div>\n        </div>\n                        \n            </div>\n        </div>\n                    "},"s11i1":{"title":"Color, Shape, and Visual Elements","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #8b5cf6, #6d28d9);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M12 3c-4.97 0-9 4.03-9 9s4.03 9 9 9c.83 0 1.5-.67 1.5-1.5 0-.39-.15-.74-.39-1.01-.23-.26-.38-.61-.38-1-.01-.83.67-1.5 1.5-1.5H16c2.76 0 5-2.24 5-5 0-4.42-4.03-8-9-8zm-5.5 9c-.83 0-1.5-.67-1.5-1.5S5.67 9 6.5 9 8 9.67 8 10.5 7.33 12 6.5 12zm3-4C8.67 8 8 7.33 8 6.5S8.67 5 9.5 5s1.5.67 1.5 1.5S10.33 8 9.5 8zm5 0c-.83 0-1.5-.67-1.5-1.5S13.67 5 14.5 5s1.5.67 1.5 1.5S15.33 8 14.5 8zm3 4c-.83 0-1.5-.67-1.5-1.5S16.67 9 17.5 9s1.5.67 1.5 1.5-.67 1.5-1.5 1.5z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Color Theory in Visualization</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <h4 style=\"margin:0 0 10px; color:#8b5cf6;\">Color Properties</h4>\n                            <table style=\"\n            width: 100%;\n            border-collapse: collapse;\n            border-radius: 12px;\n            overflow: hidden;\n            box-shadow: 0 1px 6px rgba(0,0,0,0.06);\n            margin: 12px 0;\n        \"><thead><tr><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Property</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">What it controls</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Use in Visualization</th></tr></thead><tbody><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Hue</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">The color itself (red, blue, green)</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #10b98118;\n            color: #10b981;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #10b98130;\n            margin: 2px 3px;\n        \">CATEGORICAL data</span> — distinguishing groups</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Saturation</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Color intensity (vivid vs. gray)</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Highlighting vs. de-emphasizing elements</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Lightness/Value</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Light vs. dark</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #3b82f618;\n            color: #3b82f6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #3b82f630;\n            margin: 2px 3px;\n        \">SEQUENTIAL data</span> — gradual magnitude</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Opacity/Alpha</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Color transparency</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Overlaying data layers</td></tr></tbody></table>\n                            \n        <div style=\"\n            background: #ef444408;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #ef4444; font-size: 0.92rem;\">\n                Fundamental Color Rule\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\"><strong>HUE</strong> is ideal for <strong>categorical/qualitative</strong> data (distinguishing groups instantly).<br>Color is <strong>NOT suitable for quantitative data</strong> — the human eye cannot order intensities precisely.<br>For magnitudes, use: <strong>position and length</strong>.</div>\n        </div>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #3b82f6, #2563eb);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M12 3c-4.97 0-9 4.03-9 9s4.03 9 9 9c.83 0 1.5-.67 1.5-1.5 0-.39-.15-.74-.39-1.01-.23-.26-.38-.61-.38-1-.01-.83.67-1.5 1.5-1.5H16c2.76 0 5-2.24 5-5 0-4.42-4.03-8-9-8zm-5.5 9c-.83 0-1.5-.67-1.5-1.5S5.67 9 6.5 9 8 9.67 8 10.5 7.33 12 6.5 12zm3-4C8.67 8 8 7.33 8 6.5S8.67 5 9.5 5s1.5.67 1.5 1.5S10.33 8 9.5 8zm5 0c-.83 0-1.5-.67-1.5-1.5S13.67 5 14.5 5s1.5.67 1.5 1.5S15.33 8 14.5 8zm3 4c-.83 0-1.5-.67-1.5-1.5S16.67 9 17.5 9s1.5.67 1.5 1.5-.67 1.5-1.5 1.5z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Color Models — RGB vs. CMYK</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <div style=\"display:grid; grid-template-columns:1fr 1fr; gap:16px; margin-bottom:14px;\">\n                                <div style=\"background: linear-gradient(135deg, #ff000015, #00ff0015, #0000ff15); border-radius:14px; padding:18px; border:2px solid #3b82f630;\">\n                                    <div style=\"font-weight:800; font-size:1.2rem; text-align:center; margin-bottom:8px;\">RGB</div>\n                                    <div style=\"text-align:center; margin-bottom:8px;\">\n                                        <span style=\"color:#ff0000; font-weight:700; font-size:1.1rem;\">R</span> <span style=\"color:#00aa00; font-weight:700; font-size:1.1rem;\">G</span> <span style=\"color:#0000ff; font-weight:700; font-size:1.1rem;\">B</span>\n                                    </div>\n                                    <ul style=\"margin:0; padding-left:18px; font-size:0.88rem;\">\n                                        <li><strong>ADDITIVE</strong> model (adds light)</li>\n                                        <li>Red + Green + Blue</li>\n                                        <li>The sum of all = <strong>WHITE</strong></li>\n                                        <li>Absence of light = <strong>BLACK</strong></li>\n                                        <li>Use: <strong>SCREENS</strong> (monitors, TV, phones)</li>\n                                        <li>Creators: <strong>Thomas Young</strong> and <strong>Hermann von Helmholtz</strong> (Trichromatic Theory, 19th century)</li>\n                                    </ul>\n                                </div>\n                                <div style=\"background: linear-gradient(135deg, #00ffff15, #ff00ff15, #ffff0015); border-radius:14px; padding:18px; border:2px solid #8b5cf630;\">\n                                    <div style=\"font-weight:800; font-size:1.2rem; text-align:center; margin-bottom:8px;\">CMYK</div>\n                                    <div style=\"text-align:center; margin-bottom:8px;\">\n                                        <span style=\"color:#00bcd4; font-weight:700; font-size:1.1rem;\">C</span> <span style=\"color:#e91e63; font-weight:700; font-size:1.1rem;\">M</span> <span style=\"color:#fdd835; font-weight:700; font-size:1.1rem;\">Y</span> <span style=\"color:#333; font-weight:700; font-size:1.1rem;\">K</span>\n                                    </div>\n                                    <ul style=\"margin:0; padding-left:18px; font-size:0.88rem;\">\n                                        <li><strong>SUBTRACTIVE</strong> model (mixes inks)</li>\n                                        <li>Cyan + Magenta + Yellow + Key (black)</li>\n                                        <li>The sum of all = <strong>BLACK</strong></li>\n                                        <li>Absence of ink = <strong>WHITE</strong> (paper)</li>\n                                        <li>Use: <strong>PRINTING</strong> (documents, posters, magazines)</li>\n                                        <li>K (Key = black) is added because pure CMY does not produce pure black</li>\n                                    </ul>\n                                </div>\n                            </div>\n                            <div style=\"background:#f59e0b10; border-radius:12px; padding:14px; border:1px solid #f59e0b25; margin-bottom:10px;\">\n                                <div style=\"font-weight:700; color:#f59e0b; margin-bottom:6px;\">HSL / HSB — Intuitive Model</div>\n                                <p style=\"margin:0; font-size:0.9rem;\">\n                                    <strong>H</strong> = Hue (0°-360°) • <strong>S</strong> = Saturation (0-100%) • <strong>L</strong> = Lightness (0-100%)<br> It is the most <strong>intuitive model for designers</strong> because it lets you select color, vividness, and brightness separately.\n                                </p>\n                            </div>\n                            \n        <div style=\"\n            background: #ef444408;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #ef4444; font-size: 0.92rem;\">\n                EXAM TRAP — RGB vs. CMYK\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\"><strong>RGB = Screens</strong> (additive, sum = white). <strong>CMYK = Printing</strong> (subtractive, sum = black).<br>Colors on screen can look different when printed because RGB has a wider <strong>gamut</strong> (range of colors) than CMYK.</div>\n        </div>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #10b981, #059669);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M11.99 18.54l-7.37-5.73L3 14.07l9 7 9-7-1.63-1.27zM12 16l7.36-5.73L21 9l-9-7-9 7 1.63 1.27L12 16z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Visual Elements: Shape and Encoding</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <p>In visualization, <strong>visual elements</strong> are the pieces that encode data:</p>\n                            <table style=\"\n            width: 100%;\n            border-collapse: collapse;\n            border-radius: 12px;\n            overflow: hidden;\n            box-shadow: 0 1px 6px rgba(0,0,0,0.06);\n            margin: 12px 0;\n        \"><thead><tr><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Element</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Ideal Data Type</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Effectiveness</th></tr></thead><tbody><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Position</strong> (on X/Y axes)</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #3b82f618;\n            color: #3b82f6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #3b82f630;\n            margin: 2px 3px;\n        \">Quantitative</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #10b98118;\n            color: #10b981;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #10b98130;\n            margin: 2px 3px;\n        \">Highest</span></td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Length</strong> (bars)</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #3b82f618;\n            color: #3b82f6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #3b82f630;\n            margin: 2px 3px;\n        \">Quantitative</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #3b82f618;\n            color: #3b82f6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #3b82f630;\n            margin: 2px 3px;\n        \">Very High</span></td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Shape</strong> (circle, triangle, square)</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #10b98118;\n            color: #10b981;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #10b98130;\n            margin: 2px 3px;\n        \">Categorical</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #f59e0b18;\n            color: #f59e0b;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #f59e0b30;\n            margin: 2px 3px;\n        \">Medium</span></td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Color (Hue)</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #10b98118;\n            color: #10b981;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #10b98130;\n            margin: 2px 3px;\n        \">Categorical</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #8b5cf618;\n            color: #8b5cf6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #8b5cf630;\n            margin: 2px 3px;\n        \">High for categories</span></td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Size</strong> (area)</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #3b82f618;\n            color: #3b82f6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #3b82f630;\n            margin: 2px 3px;\n        \">Quantitative</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #ef444418;\n            color: #ef4444;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #ef444430;\n            margin: 2px 3px;\n        \">Low</span></td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Orientation</strong> (mark angle)</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #10b98118;\n            color: #10b981;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #10b98130;\n            margin: 2px 3px;\n        \">Categorical</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #ef444418;\n            color: #ef4444;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #ef444430;\n            margin: 2px 3px;\n        \">Low</span></td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Texture</strong> (fill pattern)</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #10b98118;\n            color: #10b981;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #10b98130;\n            margin: 2px 3px;\n        \">Categorical</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #ef444418;\n            color: #ef4444;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #ef444430;\n            margin: 2px 3px;\n        \">Low</span></td></tr></tbody></table>\n                            \n        <div style=\"\n            background: #10b98108;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #10b981; font-size: 0.92rem;\">\n                Shape as a Visual Element\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\"><strong>Shape</strong> (circle, square, triangle, star) is a <strong>pre-attentive</strong> attribute — the brain detects it instantly. It is used to distinguish <strong>categories</strong>, not magnitudes. Example: in a scatter plot, different shapes represent different groups.</div>\n        </div>\n                        \n            </div>\n        </div>\n                    "},"s11i2":{"title":"Cartography: History and Projections","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #3b82f6, #1d4ed8);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M20.5 3l-.16.03L15 5.1 9 3 3.36 4.9c-.21.07-.36.25-.36.48V20.5c0 .28.22.5.5.5l.16-.03L9 18.9l6 2.1 5.64-1.9c.21-.07.36-.25.36-.48V3.5c0-.28-.22-.5-.5-.5zM15 19l-6-2.11V5l6 2.11V19z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">History of Cartography</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <p style=\"font-size:1.02em; margin-top:0;\">Cartography is the art and science of representing the Earth on maps. It is one of the <strong>oldest forms of information visualization</strong>.</p>\n                            <table style=\"\n            width: 100%;\n            border-collapse: collapse;\n            border-radius: 12px;\n            overflow: hidden;\n            box-shadow: 0 1px 6px rgba(0,0,0,0.06);\n            margin: 12px 0;\n        \"><thead><tr><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Figure</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Era</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Contribution</th></tr></thead><tbody><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Claudius Ptolemy</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">2nd century AD</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Author of <em>Geographía</em>: the first <strong>world maps</strong> with coordinates. The foundation of Western cartography for more than 1,000 years.</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Eratosthenes</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">3rd century BC</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">First <strong>measurement of the Earth's circumference</strong> (~40,000 km). He laid the foundations of ancient cartography.</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Gerhardus Mercator</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">1569</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">He created the <strong>most famous map projection</strong>. It allowed sailors to plot routes as straight lines (rhumb lines).</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Abraham Ortelius</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">1570</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">He published the <em>Theatrum Orbis Terrarum</em>, considered the <strong>first modern atlas</strong>.</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>John Snow</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">1854</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Map of <strong>cholera in London</strong>: a pioneer of geospatial visualization for epidemiological analysis.</td></tr></tbody></table>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #ef4444, #dc2626);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M20.5 3l-.16.03L15 5.1 9 3 3.36 4.9c-.21.07-.36.25-.36.48V20.5c0 .28.22.5.5.5l.16-.03L9 18.9l6 2.1 5.64-1.9c.21-.07.36-.25.36-.48V3.5c0-.28-.22-.5-.5-.5zM15 19l-6-2.11V5l6 2.11V19z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Mercator Projection — Key Detail</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <div style=\"display:grid; grid-template-columns:1fr 1fr; gap:16px; margin-bottom:12px;\">\n                                <div style=\"background:#10b98110; border-radius:12px; padding:14px; border:1px solid #10b98125;\">\n                                    <div style=\"font-weight:700; color:#10b981; margin-bottom:6px;\">✓ What it PRESERVES</div>\n                                    <ul style=\"margin:0; padding-left:18px; font-size:0.9rem;\">\n                                        <li><strong>ANGLES</strong> (conformal)</li>\n                                        <li>Local shapes keep their proportions</li>\n                                        <li>Ideal for <strong>maritime navigation</strong> — routes are straight lines</li>\n                                    </ul>\n                                </div>\n                                <div style=\"background:#ef444410; border-radius:12px; padding:14px; border:1px solid #ef444425;\">\n                                    <div style=\"font-weight:700; color:#ef4444; margin-bottom:6px;\">✗ What it DISTORTS</div>\n                                    <ul style=\"margin:0; padding-left:18px; font-size:0.9rem;\">\n                                        <li><strong>SIZES (areas)</strong> in polar regions</li>\n                                        <li>Greenland looks the size of Africa</li>\n                                        <li>In reality, Africa is <strong>14 times larger</strong></li>\n                                    </ul>\n                                </div>\n                            </div>\n                            \n        <div style=\"\n            background: #3b82f608;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #3b82f6; font-size: 0.92rem;\">\n                Who created the most famous map projection?\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\"><strong>Gerhardus Mercator</strong> (Gerardus Mercator) in <strong>1569</strong>. He was a Flemish cartographer, geographer, and mathematician. His <strong>conformal</strong> cylindrical projection became the standard for navigation maps and is still the most widely used in web applications such as Google Maps.</div>\n        </div>\n                        \n            </div>\n        </div>\n                    "},"s11i3":{"title":"Resolution: DPI, PPI, and Formats","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #8b5cf6, #7c3aed);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M12 4.5C7 4.5 2.73 7.61 1 12c1.73 4.39 6 7.5 11 7.5s9.27-3.11 11-7.5c-1.73-4.39-6-7.5-11-7.5zM12 17c-2.76 0-5-2.24-5-5s2.24-5 5-5 5 2.24 5 5-2.24 5-5 5zm0-8c-1.66 0-3 1.34-3 3s1.34 3 3 3 3-1.34 3-3-1.34-3-3-3z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Resolution: DPI vs. PPI</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <div style=\"display:grid; grid-template-columns:1fr 1fr; gap:16px; margin-bottom:14px;\">\n                                <div style=\"text-align:center; padding:20px; background:linear-gradient(135deg, #8b5cf610, #6d28d910); border-radius:14px; border:2px solid #8b5cf630;\">\n                                    <div style=\"font-size:3rem; font-weight:900; color:#8b5cf6;\">300</div>\n                                    <div style=\"font-weight:700; font-size:1.1rem; margin-bottom:4px;\">DPI</div>\n                                    <div style=\"font-size:0.85rem; color:#666;\">Dots Per Inch</div>\n                                    <div style=\"margin-top:8px; font-size:0.9rem;\"><strong>PRINTING</strong></div>\n                                    <p style=\"font-size:0.82rem; margin:6px 0 0;\">Minimum resolution for professional-quality printing. Magazines, posters, books.</p>\n                                </div>\n                                <div style=\"text-align:center; padding:20px; background:linear-gradient(135deg, #6b728010, #37415110); border-radius:14px; border:2px solid #6b728030;\">\n                                    <div style=\"font-size:3rem; font-weight:900; color:#6b7280;\">72-96</div>\n                                    <div style=\"font-weight:700; font-size:1.1rem; margin-bottom:4px;\">PPI</div>\n                                    <div style=\"font-size:0.85rem; color:#666;\">Pixels Per Inch</div>\n                                    <div style=\"margin-top:8px; font-size:0.9rem;\"><strong>SCREENS</strong></div>\n                                    <p style=\"font-size:0.82rem; margin:6px 0 0;\">Standard resolution for monitors and web screens. Sufficient for digital viewing.</p>\n                                </div>\n                            </div>\n                            <table style=\"\n            width: 100%;\n            border-collapse: collapse;\n            border-radius: 12px;\n            overflow: hidden;\n            box-shadow: 0 1px 6px rgba(0,0,0,0.06);\n            margin: 12px 0;\n        \"><thead><tr><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Concept</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Meaning</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Medium</th></tr></thead><tbody><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>DPI</strong> (Dots Per Inch)</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Ink dots per inch</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #8b5cf618;\n            color: #8b5cf6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #8b5cf630;\n            margin: 2px 3px;\n        \">Printing</span></td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>PPI</strong> (Pixels Per Inch)</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Pixels per inch on screen</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #6b728018;\n            color: #6b7280;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #6b728030;\n            margin: 2px 3px;\n        \">Screens</span></td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>High Resolution</strong> (Retina)</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">≥ 200 PPI on modern screens</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #3b82f618;\n            color: #3b82f6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #3b82f630;\n            margin: 2px 3px;\n        \">Phones/Tablets</span></td></tr></tbody></table>\n                            \n        <div style=\"\n            background: #ef444408;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #ef4444; font-size: 0.92rem;\">\n                EXAM TRAP — DPI\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\"><strong>300 DPI</strong> = professional printing.<br><strong>72-96 PPI</strong> = standard web screens.<br>A 72 PPI image will look fine on screen but <strong>blurry when printed</strong>. Always design at 300 DPI if the final product is printed.</div>\n        </div>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #10b981, #059669);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M9.4 16.6L4.8 12l4.6-4.6L8 6l-6 6 6 6 1.4-1.4zm5.2 0l4.6-4.6-4.6-4.6L16 6l6 6-6 6-1.4-1.4z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Vector vs. Raster — Reminder</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <div style=\"display:grid; grid-template-columns:1fr 1fr; gap:16px;\">\n                                <div style=\"background:#10b98110; border-radius:12px; padding:14px; border:1px solid #10b98125;\">\n                                    <div style=\"font-weight:700; color:#10b981; margin-bottom:6px;\">VECTOR</div>\n                                    <ul style=\"margin:0; padding-left:18px; font-size:0.88rem;\">\n                                        <li>Mathematical formulas</li>\n                                        <li>Scales <strong>infinitely</strong> without losing quality</li>\n                                        <li>Formats: SVG, AI, EPS</li>\n                                        <li>Ideal for: logos, charts, icons, infographics</li>\n                                    </ul>\n                                </div>\n                                <div style=\"background:#f5920b10; border-radius:12px; padding:14px; border:1px solid #f59e0b25;\">\n                                    <div style=\"font-weight:700; color:#f59e0b; margin-bottom:6px;\">RASTER (Bitmap)</div>\n                                    <ul style=\"margin:0; padding-left:18px; font-size:0.88rem;\">\n                                        <li>Pixel grid</li>\n                                        <li>It <strong>pixelates</strong> when enlarged</li>\n                                        <li>Formats: JPEG, PNG, TIFF, GIF</li>\n                                        <li>Ideal for: photographs, complex images</li>\n                                    </ul>\n                                </div>\n                            </div>\n                        \n            </div>\n        </div>\n                    "},"s11i4":{"title":"Charles Minard — The Best Infographic in History","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #ef4444, #b91c1c);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M20.5 3l-.16.03L15 5.1 9 3 3.36 4.9c-.21.07-.36.25-.36.48V20.5c0 .28.22.5.5.5l.16-.03L9 18.9l6 2.1 5.64-1.9c.21-.07.36-.25.36-.48V3.5c0-.28-.22-.5-.5-.5zM15 19l-6-2.11V5l6 2.11V19z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Minard's Map (1869)</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <div style=\"text-align:center; padding:16px; background:linear-gradient(135deg, #ef444408, #b91c1c08); border-radius:14px; border:1px solid #ef444420; margin-bottom:14px;\">\n                                <div style=\"font-size:1.2rem; font-weight:800; color:#ef4444; margin-bottom:8px;\">Napoleon's Campaign in Russia (1812-1813)</div>\n                                <p style=\"margin:0; font-size:0.95rem;\">Considered by Edward Tufte to be <strong>\"the best statistical graphic ever drawn\"</strong>.</p>\n                            </div>\n                            <p><strong>Charles Joseph Minard</strong> (1781-1870) was a French civil engineer who revolutionized data visualization with his flow maps.</p>\n                            <h4 style=\"color:#ef4444; margin:14px 0 8px;\">What does the map show?</h4>\n                            <p style=\"font-size:0.93rem;\">Minard's map represents <strong>6 variables</strong> simultaneously in a single static image:</p>\n                            <table style=\"\n            width: 100%;\n            border-collapse: collapse;\n            border-radius: 12px;\n            overflow: hidden;\n            box-shadow: 0 1px 6px rgba(0,0,0,0.06);\n            margin: 12px 0;\n        \"><thead><tr><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Variable</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">How It Is Encoded</th></tr></thead><tbody><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>1. Size of the army</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Width of the band/line</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>2. Geographic location</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Position on the map (latitude/longitude)</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>3. Direction of movement</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #f59e0b18;\n            color: #f59e0b;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #f59e0b30;\n            margin: 2px 3px;\n        \">Gold = advance</span> <span style=\"\n            display: inline-block;\n            background: #33318;\n            color: #333;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #33330;\n            margin: 2px 3px;\n        \">Black = retreat</span></td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>4. Temperature</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Lower chart (down to -37°C during the retreat)</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>5. Dates</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Marked on the temperature chart</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>6. Rivers and geography</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Base map elements</td></tr></tbody></table>\n                            \n        <div style=\"\n            background: #ef444408;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #ef4444; font-size: 0.92rem;\">\n                Striking Fact\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">Napoleon began the campaign with <strong>422,000 soldiers</strong>. Only <strong>10,000</strong> returned. The map shows this devastation in a visual and immediate way — the width of the band shrinks drastically.</div>\n        </div>\n                            \n        <div style=\"\n            background: #4f6ef708;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #4f6ef7; font-size: 0.92rem;\">\n                Why does it matter for the exam?\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">1. It is the classic example of effective <strong>static multivariate visualization</strong>.<br>2. It shows that <strong>multiple dimensions can be represented without interactivity</strong>.<br>3. Tufte uses it as the reference for the ideal <strong>data-ink ratio</strong>: all the space communicates data.<br>4. Minard was a pioneer of <strong>flow maps</strong>.</div>\n        </div>\n                        \n            </div>\n        </div>\n                    "},"s11i5":{"title":"Visual Psychology and Perception","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #8b5cf6, #7c3aed);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M12 2a9 9 0 0 0-9 9c0 3.07 1.98 5.73 4.73 6.73A1 1 0 0 1 8.5 19H12v3h1v-3h3.5a1 1 0 0 1 .77-1.27A7 7 0 0 0 21 11a9 9 0 0 0-9-9z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Psychology of Visual Perception</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <h4 style=\"margin:0 0 10px; color:#8b5cf6;\">Human Visual Processing</h4>\n                            <p>The human visual system is the <strong>most powerful sensory channel</strong>. We process images much faster than text.</p>\n                            <table style=\"\n            width: 100%;\n            border-collapse: collapse;\n            border-radius: 12px;\n            overflow: hidden;\n            box-shadow: 0 1px 6px rgba(0,0,0,0.06);\n            margin: 12px 0;\n        \"><thead><tr><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Type of Memory</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Speed</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Capacity</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Role in Visualization</th></tr></thead><tbody><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong style=\"color:#ef4444;\">Iconic</strong> (sensory)</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Milliseconds</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Large but fleeting</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Captures color, position, and orientation automatically</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong style=\"color:#f59e0b;\">Short-Term</strong> (working)</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Seconds</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">~7 items (±2)</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Consciously processes visual information</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong style=\"color:#10b981;\">Long-Term</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Permanent</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Unlimited</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Recognizes learned conventions and symbols</td></tr></tbody></table>\n                            <div style=\"display:flex; align-items:center; justify-content:center; gap:10px; padding:12px; margin:12px 0; background:#8b5cf608; border-radius:10px;\">\n                                \n        <span style=\"\n            display: inline-block;\n            background: #ef444418;\n            color: #ef4444;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #ef444430;\n            margin: 2px 3px;\n        \">Iconic</span> <span style=\"font-size:1.3em; color:#8b5cf6;\">→</span> <span style=\"\n            display: inline-block;\n            background: #f59e0b18;\n            color: #f59e0b;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #f59e0b30;\n            margin: 2px 3px;\n        \">Short-Term</span> <span style=\"font-size:1.3em; color:#8b5cf6;\">→</span> <span style=\"\n            display: inline-block;\n            background: #10b98118;\n            color: #10b981;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #10b98130;\n            margin: 2px 3px;\n        \">Long-Term</span>\n                            </div>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #f59e0b, #d97706);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M7 2v11h3v9l7-12h-4l4-8z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Pre-attentive Attributes</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <p>These are visual properties that the brain detects <strong>automatically and instantly</strong>, without conscious effort (in less than 250 ms):</p>\n                            <div style=\"display:grid; grid-template-columns:repeat(3, 1fr); gap:10px; margin:12px 0;\">\n                                <div style=\"text-align:center;padding:12px;background:#ef444408;border-radius:10px;border:1px solid #ef444420;\"><div style=\"font-size:1.3rem;margin-bottom:4px;\">🔴🔵🟢</div><div style=\"font-weight:600;font-size:0.85rem;color:#ef4444;\">Color (hue)</div></div><div style=\"text-align:center;padding:12px;background:#3b82f608;border-radius:10px;border:1px solid #3b82f620;\"><div style=\"font-size:1.3rem;margin-bottom:4px;\">● ◉ ⬤</div><div style=\"font-weight:600;font-size:0.85rem;color:#3b82f6;\">Size</div></div><div style=\"text-align:center;padding:12px;background:#10b98108;border-radius:10px;border:1px solid #10b98120;\"><div style=\"font-size:1.3rem;margin-bottom:4px;\">/ | \\</div><div style=\"font-weight:600;font-size:0.85rem;color:#10b981;\">Orientation</div></div><div style=\"text-align:center;padding:12px;background:#f59e0b08;border-radius:10px;border:1px solid #f59e0b20;\"><div style=\"font-size:1.3rem;margin-bottom:4px;\">● ■ ▲</div><div style=\"font-weight:600;font-size:0.85rem;color:#f59e0b;\">Shape</div></div><div style=\"text-align:center;padding:12px;background:#8b5cf608;border-radius:10px;border:1px solid #8b5cf620;\"><div style=\"font-size:1.3rem;margin-bottom:4px;\">→ ⟹</div><div style=\"font-weight:600;font-size:0.85rem;color:#8b5cf6;\">Motion</div></div><div style=\"text-align:center;padding:12px;background:#ec489908;border-radius:10px;border:1px solid #ec489920;\"><div style=\"font-size:1.3rem;margin-bottom:4px;\">· · ·</div><div style=\"font-weight:600;font-size:0.85rem;color:#ec4899;\">Position</div></div>\n                            </div>\n                            \n        <div style=\"\n            background: #4f6ef708;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #4f6ef7; font-size: 0.92rem;\">\n                For the Exam\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">Pre-attentive attributes are the foundation of visualization design because they let the user <strong>detect patterns without thinking</strong>. <strong>Hue</strong> is the most effective for distinguishing categories. <strong>Size and position</strong> are better for magnitudes.</div>\n        </div>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #ec4899, #db2777);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M12 2a9 9 0 0 0-9 9c0 3.07 1.98 5.73 4.73 6.73A1 1 0 0 1 8.5 19H12v3h1v-3h3.5a1 1 0 0 1 .77-1.27A7 7 0 0 0 21 11a9 9 0 0 0-9-9z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Cognitive Load</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <p><strong>Cognitive load</strong> is the mental effort required to process visual information:</p>\n                            <div style=\"display:grid; grid-template-columns:1fr 1fr; gap:16px;\">\n                                <div style=\"background:#10b98110; border-radius:12px; padding:14px;\">\n                                    <div style=\"font-weight:700; color:#10b981; margin-bottom:6px;\">✓ Low Load (ideal)</div>\n                                    <ul style=\"margin:0; padding-left:18px; font-size:0.88rem;\">\n                                        <li>Clean, clear design</li>\n                                        <li>A maximum of 7 colors per chart</li>\n                                        <li>Clear visual hierarchy</li>\n                                        <li>Well-used pre-attentive attributes</li>\n                                    </ul>\n                                </div>\n                                <div style=\"background:#ef444410; border-radius:12px; padding:14px;\">\n                                    <div style=\"font-weight:700; color:#ef4444; margin-bottom:6px;\">✗ High Load (avoid)</div>\n                                    <ul style=\"margin:0; padding-left:18px; font-size:0.88rem;\">\n                                        <li>Too many elements</li>\n                                        <li>Colors without logic</li>\n                                        <li>Chartjunk (useless decorations)</li>\n                                        <li>Lack of visual hierarchy</li>\n                                    </ul>\n                                </div>\n                            </div>\n                        \n            </div>\n        </div>\n                    "},"s11i6":{"title":"Gestalt Principles — Expanded","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #ec4899, #db2777);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M12 4.5C7 4.5 2.73 7.61 1 12c1.73 4.39 6 7.5 11 7.5s9.27-3.11 11-7.5c-1.73-4.39-6-7.5-11-7.5zM12 17c-2.76 0-5-2.24-5-5s2.24-5 5-5 5 2.24 5 5-2.24 5-5 5zm0-8c-1.66 0-3 1.34-3 3s1.34 3 3 3 3-1.34 3-3-1.34-3-3-3z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Gestalt Laws in Visualization</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <p><strong>Gestalt</strong> (from German: \"form\" or \"configuration\") is a school of psychology that studies <strong>how we perceive patterns and organize visual information</strong>.</p>\n                            <table style=\"\n            width: 100%;\n            border-collapse: collapse;\n            border-radius: 12px;\n            overflow: hidden;\n            box-shadow: 0 1px 6px rgba(0,0,0,0.06);\n            margin: 12px 0;\n        \"><thead><tr><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Principle</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Definition</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Example in Viz.</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Importance</th></tr></thead><tbody><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Proximity</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Elements close together are perceived as a group</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Nearby points in a scatter plot = cluster</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #ef444418;\n            color: #ef4444;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #ef444430;\n            margin: 2px 3px;\n        \">VERY HIGH</span></td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Similarity</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Elements with the same shape/color = group</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Same color = same category</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #ef444418;\n            color: #ef4444;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #ef444430;\n            margin: 2px 3px;\n        \">VERY HIGH</span></td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Continuity</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">The eye follows smooth lines and curves</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Line chart: we follow the trend</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #f59e0b18;\n            color: #f59e0b;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #f59e0b30;\n            margin: 2px 3px;\n        \">HIGH</span></td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Closure</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">The brain completes incomplete shapes</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Arcs perceived as whole circles</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #f59e0b18;\n            color: #f59e0b;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #f59e0b30;\n            margin: 2px 3px;\n        \">HIGH</span></td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Figure-Ground</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">We separate an object (figure) from the background</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Highlighted data on a neutral background</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #3b82f618;\n            color: #3b82f6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #3b82f630;\n            margin: 2px 3px;\n        \">MEDIUM</span></td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Common Fate</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Elements that move together = group</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Data animations moving in the same direction</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #3b82f618;\n            color: #3b82f6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #3b82f630;\n            margin: 2px 3px;\n        \">MEDIUM</span></td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Connection</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">A line joining two points = relationship</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Network diagrams, graphs, trees</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #f59e0b18;\n            color: #f59e0b;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #f59e0b30;\n            margin: 2px 3px;\n        \">HIGH</span></td></tr></tbody></table>\n                            \n        <div style=\"\n            background: #ec489908;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #ec4899; font-size: 0.92rem;\">\n                IMPORTANT for the Exam\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">The 4 <strong>most frequently asked</strong> principles are: <strong>Proximity, Similarity, Closure, and Continuity</strong>.<br>Remember: Gestalt explains <strong>why</strong> a good chart works — because it takes advantage of how our brain <strong>automatically organizes</strong> visual information.</div>\n        </div>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #4f6ef7, #3b44d1);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M5 9.2h3V19H5V9.2zM10.6 5h2.8v14h-2.8V5zm5.6 8H19v6h-2.8v-6z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Gestalt Applied to Chart Design</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <div style=\"display:grid; grid-template-columns:1fr 1fr; gap:14px;\">\n                                <div style=\"padding:14px; background:#4f6ef708; border-radius:12px;\">\n                                    <strong style=\"color:#4f6ef7;\">Proximity in action:</strong><br> <span style=\"font-size:0.9rem;\">In a grouped bar chart, the bars of the same category are placed <strong>together</strong>, separated from the others by a larger gap.</span>\n                                </div>\n                                <div style=\"padding:14px; background:#10b98108; border-radius:12px;\">\n                                    <strong style=\"color:#10b981;\">Similarity in action:</strong><br> <span style=\"font-size:0.9rem;\">All the bars in the same group use the <strong>same color</strong>. The eye instantly groups them as \"the same thing.\"</span>\n                                </div>\n                                <div style=\"padding:14px; background:#f59e0b08; border-radius:12px;\">\n                                    <strong style=\"color:#f59e0b;\">Closure in action:</strong><br> <span style=\"font-size:0.9rem;\">Donut charts use a partial arc — our brain mentally <strong>completes the circle</strong>.</span>\n                                </div>\n                                <div style=\"padding:14px; background:#ef444408; border-radius:12px;\">\n                                    <strong style=\"color:#ef4444;\">Continuity in action:</strong><br> <span style=\"font-size:0.9rem;\">In line charts, we naturally follow the trend thanks to the principle of <strong>continuity</strong>.</span>\n                                </div>\n                            </div>\n                        \n            </div>\n        </div>\n                    "},"s11i7":{"title":"Ethics in Visualization — Expanded","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #6366f1, #4f46e5);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M12 1L3 5v6c0 5.55 3.84 10.74 9 12 5.16-1.26 9-6.45 9-12V5l-9-4z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Ethics and Responsibility in Visualization</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <p>Ethics in visualization refers to the <strong>duty to represent data faithfully</strong>, without manipulating the reader's perception.</p>\n                            \n                            <h4 style=\"color:#6366f1; margin:14px 0 8px;\">Edward Tufte — Pillars of Visual Ethics</h4>\n                            <table style=\"\n            width: 100%;\n            border-collapse: collapse;\n            border-radius: 12px;\n            overflow: hidden;\n            box-shadow: 0 1px 6px rgba(0,0,0,0.06);\n            margin: 12px 0;\n        \"><thead><tr><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Concept</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Definition</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Consequence</th></tr></thead><tbody><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Data-Ink Ratio</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Proportion of ink devoted to data vs. the total</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Maximize → more data, less decoration</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Chartjunk</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Elements that do NOT provide information</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Remove: 3D, shadows, decorative gradients</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Lie Factor</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Visual effect / Effect in the data</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">= 1 faithful · > 1 exaggerates · < 1 minimizes</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Data Density</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Amount of data per unit of area</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">More data in less space = more efficient</td></tr></tbody></table>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #ef4444, #dc2626);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M1 21h22L12 2 1 21zm12-3h-2v-2h2v2zm0-4h-2v-4h2v4z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Visual Manipulations — Red Flags</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <div style=\"display:grid; grid-template-columns:1fr 1fr; gap:12px;\">\n                                <div style=\"padding:14px;background:#ef444408;border-radius:12px;border:1px solid #ef444420;\"><div style=\"font-weight:700;color:#ef4444;margin-bottom:4px;font-size:0.95rem;\">✗ Truncated Axes</div><p style=\"margin:0;font-size:0.85rem;line-height:1.5;\">Cutting the Y axis at a high value to exaggerate differences. Example: bars showing 98% vs. 99% as if they were enormously different.</p></div><div style=\"padding:14px;background:#f9731608;border-radius:12px;border:1px solid #f9731620;\"><div style=\"font-weight:700;color:#f97316;margin-bottom:4px;font-size:0.95rem;\">✗ Unnecessary 3D</div><p style=\"margin:0;font-size:0.85rem;line-height:1.5;\">Three-dimensional projection in pie and bar charts that distorts proportions. The perspective angle changes the perception of size.</p></div><div style=\"padding:14px;background:#f59e0b08;border-radius:12px;border:1px solid #f59e0b20;\"><div style=\"font-weight:700;color:#f59e0b;margin-bottom:4px;font-size:0.95rem;\">✗ Cherry-Picking</div><p style=\"margin:0;font-size:0.85rem;line-height:1.5;\">Selecting only the data that supports a narrative and ignoring the data that contradicts it. Visual confirmation bias.</p></div><div style=\"padding:14px;background:#8b5cf608;border-radius:12px;border:1px solid #8b5cf620;\"><div style=\"font-weight:700;color:#8b5cf6;margin-bottom:4px;font-size:0.95rem;\">✗ Misleading Dual Axis</div><p style=\"margin:0;font-size:0.85rem;line-height:1.5;\">Two Y axes with different scales to suggest false correlations between unrelated variables.</p></div><div style=\"padding:14px;background:#ec489908;border-radius:12px;border:1px solid #ec489920;\"><div style=\"font-weight:700;color:#ec4899;margin-bottom:4px;font-size:0.95rem;\">✗ Misleading Colors</div><p style=\"margin:0;font-size:0.85rem;line-height:1.5;\">Using red for growth and green for decline (inverted), or colors that induce incorrect associations.</p></div><div style=\"padding:14px;background:#3b82f608;border-radius:12px;border:1px solid #3b82f620;\"><div style=\"font-weight:700;color:#3b82f6;margin-bottom:4px;font-size:0.95rem;\">✗ Non-Linear Scale</div><p style=\"margin:0;font-size:0.85rem;line-height:1.5;\">Using logarithmic scales without indicating it, making enormous differences look small.</p></div>\n                            </div>\n                            \n        <div style=\"\n            background: #6366f108;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #6366f1; font-size: 0.92rem;\">\n                Guiding Principle\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">\"<strong>Visualization should illuminate, not obscure.</strong>\" — Every choice (color, chart, scale, perspective) must represent the reality of the data <strong>faithfully</strong>.</div>\n        </div>\n                        \n            </div>\n        </div>\n                    "},"s11i8":{"title":"Chart Types — Complete Guide","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #4f6ef7, #3b44d1);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M5 9.2h3V19H5V9.2zM10.6 5h2.8v14h-2.8V5zm5.6 8H19v6h-2.8v-6z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Choosing Charts by Purpose</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <table style=\"\n            width: 100%;\n            border-collapse: collapse;\n            border-radius: 12px;\n            overflow: hidden;\n            box-shadow: 0 1px 6px rgba(0,0,0,0.06);\n            margin: 12px 0;\n        \"><thead><tr><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Chart</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Purpose</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Variables</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Effectiveness</th></tr></thead><tbody><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Bars</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Compare categories</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #3b82f618;\n            color: #3b82f6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #3b82f630;\n            margin: 2px 3px;\n        \">Categorical + Quantitative</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #10b98118;\n            color: #10b981;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #10b98130;\n            margin: 2px 3px;\n        \">Highest</span></td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Lines</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Trend over time</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #3b82f618;\n            color: #3b82f6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #3b82f630;\n            margin: 2px 3px;\n        \">Temporal + Quantitative</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #10b98118;\n            color: #10b981;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #10b98130;\n            margin: 2px 3px;\n        \">Highest</span></td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Scatter</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Relationship between 2 variables</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #3b82f618;\n            color: #3b82f6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #3b82f630;\n            margin: 2px 3px;\n        \">2 Quantitative</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #3b82f618;\n            color: #3b82f6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #3b82f630;\n            margin: 2px 3px;\n        \">Very High</span></td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Bubbles</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Like scatter + a 3rd variable</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #3b82f618;\n            color: #3b82f6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #3b82f630;\n            margin: 2px 3px;\n        \">3 Quantitative</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #f59e0b18;\n            color: #f59e0b;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #f59e0b30;\n            margin: 2px 3px;\n        \">High</span></td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Pie (Circular)</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Part of a whole</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #10b98118;\n            color: #10b981;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #10b98130;\n            margin: 2px 3px;\n        \">Categorical</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #ef444418;\n            color: #ef4444;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #ef444430;\n            margin: 2px 3px;\n        \">LOW ⚠️</span></td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Choropleth</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Data by geographic region</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #8b5cf618;\n            color: #8b5cf6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #8b5cf630;\n            margin: 2px 3px;\n        \">Geographic + Quantitative</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #f59e0b18;\n            color: #f59e0b;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #f59e0b30;\n            margin: 2px 3px;\n        \">High</span></td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Cartogram</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Areas distorted by the data</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #8b5cf618;\n            color: #8b5cf6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #8b5cf630;\n            margin: 2px 3px;\n        \">Geographic + Quantitative</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #f59e0b18;\n            color: #f59e0b;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #f59e0b30;\n            margin: 2px 3px;\n        \">Medium</span></td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Treemap</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Hierarchies by area</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #ec489918;\n            color: #ec4899;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #ec489930;\n            margin: 2px 3px;\n        \">Hierarchical + Quantitative</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #f59e0b18;\n            color: #f59e0b;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #f59e0b30;\n            margin: 2px 3px;\n        \">Medium</span></td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Sparkline</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Inline micro-trend</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #6b728018;\n            color: #6b7280;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #6b728030;\n            margin: 2px 3px;\n        \">Temporal</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #6b728018;\n            color: #6b7280;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #6b728030;\n            margin: 2px 3px;\n        \">Contextual</span></td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Heat map</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Density or intensity</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #f9731618;\n            color: #f97316;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #f9731630;\n            margin: 2px 3px;\n        \">2 Categorical + 1 Quantitative</span></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">\n        <span style=\"\n            display: inline-block;\n            background: #f59e0b18;\n            color: #f59e0b;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #f59e0b30;\n            margin: 2px 3px;\n        \">High</span></td></tr></tbody></table>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #ef4444, #dc2626);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M1 21h22L12 2 1 21zm12-3h-2v-2h2v2zm0-4h-2v-4h2v4z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Criticism of Pie Charts</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <div style=\"text-align:center; padding:16px; background:#ef444408; border-radius:14px; border:1px solid #ef444420; margin-bottom:12px;\">\n                                <div style=\"font-size:1.1rem; font-weight:800; color:#ef4444; margin-bottom:8px;\">Why are pie charts criticized?</div>\n                            </div>\n                            <ul style=\"padding-left:20px; font-size:0.93rem; line-height:1.8;\">\n                                <li>They use <strong>angle and area</strong> → <strong>LOW</strong> levels in the Cleveland and McGill hierarchy</li>\n                                <li>The human eye has <strong>difficulty comparing angles</strong> precisely</li>\n                                <li>With more than 5-6 categories, they become <strong>unreadable</strong></li>\n                                <li>Better alternative: a <strong>bar chart</strong> (length > angle in precision)</li>\n                            </ul>\n                            \n        <div style=\"\n            background: #4f6ef708;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #4f6ef7; font-size: 0.92rem;\">\n                Cleveland and McGill Hierarchy — Reminder\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">From MOST to LEAST precise for quantitative data:<br><strong>Position > Length > Angle > Area > Color</strong><br>BARS (length) always beat PIES (angle).</div>\n        </div>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #10b981, #059669);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M11.99 18.54l-7.37-5.73L3 14.07l9 7 9-7-1.63-1.27zM12 16l7.36-5.73L21 9l-9-7-9 7 1.63 1.27L12 16z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Figurative vs. Non-Figurative</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <div style=\"display:grid; grid-template-columns:1fr 1fr; gap:16px;\">\n                                <div style=\"text-align:center; padding:14px; background:#f9731610; border-radius:12px; border:1px solid #f9731625;\">\n                                    <div style=\"font-weight:700; color:#f97316; font-size:1.05rem; margin-bottom:6px;\">Figurative</div>\n                                    <p style=\"margin:0; font-size:0.9rem;\">It resembles reality: <strong>maps, pictograms, illustrations</strong>.<br>More <strong>intuitive</strong> but less precise.</p>\n                                </div>\n                                <div style=\"text-align:center; padding:14px; background:#4f6ef710; border-radius:12px; border:1px solid #4f6ef725;\">\n                                    <div style=\"font-weight:700; color:#4f6ef7; font-size:1.05rem; margin-bottom:6px;\">Non-Figurative</div>\n                                    <p style=\"margin:0; font-size:0.9rem;\">Abstract shapes: <strong>bars, lines, areas, scatter</strong>.<br>More <strong>precise</strong> but requires learning.</p>\n                                </div>\n                            </div>\n                        \n            </div>\n        </div>\n                    "}},"unir-herramientas-viz":{"s0":{"sectionTitle":"Topic 1: Introduction and Tools"},"s0i0":{"title":"Tools Landscape","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M22.7 19l-9.1-9.1c.9-2.3.4-5-1.5-6.9-2-2-5-2.4-7.4-1.3L9 6 6 9 1.6 4.7C.4 7.1.9 10.1 2.9 12.1c1.9 1.9 4.6 2.4 6.9 1.5l9.1 9.1c.4.4 1 .4 1.4 0l2.3-2.3c.5-.4.5-1.1.1-1.4z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Course Objective</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <p>The objective is to cover different <strong>visualization libraries and tools</strong> with a fully practical approach. The aim is to:</p>\n                            <ul style=\"padding-left: 20px; margin: 10px 0;\">\n                                <li>Understand what data you have</li>\n                                <li>Represent it graphically with the appropriate tools</li>\n                                <li>Verify that the recipients understand the message</li>\n                            </ul>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #059669, #10b981);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M9.4 16.6L4.8 12l4.6-4.6L8 6l-6 6 6 6 1.4-1.4zm5.2 0l4.6-4.6-4.6-4.6L16 6l6 6-6 6-1.4-1.4z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Tools for Developers</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <p>They require programming knowledge but offer <strong>unlimited customization</strong>:</p>\n                            <table style=\"\n            width: 100%;\n            border-collapse: collapse;\n            border-radius: 12px;\n            overflow: hidden;\n            box-shadow: 0 1px 6px rgba(0,0,0,0.06);\n            margin: 12px 0;\n        \"><thead><tr><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Tool</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Description</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Language</th></tr></thead><tbody><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Google Chart</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Google Spreadsheets charting API</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">JavaScript</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>D3.js</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Library for SVG with complex data</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">JavaScript + SVG</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>R</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Statistical package for large datasets</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">R / Python</td></tr></tbody></table>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #f59e0b, #ef4444);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M5 9.2h3V19H5V9.2zM10.6 5h2.8v14h-2.8V5zm5.6 8H19v6h-2.8v-6z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Tools for Non-Developers</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <p>They maximize <strong>ease of use</strong>. The end user can extract and handle data without a development team:</p>\n                            <table style=\"\n            width: 100%;\n            border-collapse: collapse;\n            border-radius: 12px;\n            overflow: hidden;\n            box-shadow: 0 1px 6px rgba(0,0,0,0.06);\n            margin: 12px 0;\n        \"><thead><tr><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Tool</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Key Advantage</th></tr></thead><tbody><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Tableau</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Drag and drop, real-time updates</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Power BI</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Microsoft integration, multiple data sources</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Qlik Sense</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Data discovery, associative model</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>CARTO</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Tabular data + geographic maps</td></tr></tbody></table>\n                        \n            </div>\n        </div>\n                    "},"s0i1":{"title":"Gartner Criteria and the Web","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #7c3aed, #a855f7);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M12 1L3 5v6c0 5.55 3.84 10.74 9 12 5.16-1.26 9-6.45 9-12V5l-9-4z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Gartner's 15 Capabilities for ABI Platforms</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <p>Gartner evaluates <strong>Analytics and Business Intelligence</strong> platforms using these criteria:</p>\n                            <div style=\"display: flex; flex-wrap: wrap; gap: 4px; margin: 10px 0;\">\n                                \n        <span style=\"\n            display: inline-block;\n            background: #4f6ef718;\n            color: #4f6ef7;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #4f6ef730;\n            margin: 2px 3px;\n        \">Security</span>\n                                \n        <span style=\"\n            display: inline-block;\n            background: #05966918;\n            color: #059669;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #05966930;\n            margin: 2px 3px;\n        \">Management</span>\n                                \n        <span style=\"\n            display: inline-block;\n            background: #0ea5e918;\n            color: #0ea5e9;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #0ea5e930;\n            margin: 2px 3px;\n        \">Cloud</span>\n                                \n        <span style=\"\n            display: inline-block;\n            background: #8b5cf618;\n            color: #8b5cf6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #8b5cf630;\n            margin: 2px 3px;\n        \">Connectivity</span>\n                                \n        <span style=\"\n            display: inline-block;\n            background: #f59e0b18;\n            color: #f59e0b;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #f59e0b30;\n            margin: 2px 3px;\n        \">Data preparation</span>\n                                \n        <span style=\"\n            display: inline-block;\n            background: #ef444418;\n            color: #ef4444;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #ef444430;\n            margin: 2px 3px;\n        \">Model complexity</span>\n                                \n        <span style=\"\n            display: inline-block;\n            background: #6366f118;\n            color: #6366f1;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #6366f130;\n            margin: 2px 3px;\n        \">Catalog</span>\n                                \n        <span style=\"\n            display: inline-block;\n            background: #14b8a618;\n            color: #14b8a6;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #14b8a630;\n            margin: 2px 3px;\n        \">Automated insights</span>\n                                \n        <span style=\"\n            display: inline-block;\n            background: #e11d4818;\n            color: #e11d48;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #e11d4830;\n            margin: 2px 3px;\n        \">Advanced analytics</span>\n                                \n        <span style=\"\n            display: inline-block;\n            background: #4f6ef718;\n            color: #4f6ef7;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #4f6ef730;\n            margin: 2px 3px;\n        \">Data visualization</span>\n                                \n        <span style=\"\n            display: inline-block;\n            background: #7c3aed18;\n            color: #7c3aed;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #7c3aed30;\n            margin: 2px 3px;\n        \">Natural language query</span>\n                                \n        <span style=\"\n            display: inline-block;\n            background: #05966918;\n            color: #059669;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #05966930;\n            margin: 2px 3px;\n        \">Data storytelling</span>\n                                \n        <span style=\"\n            display: inline-block;\n            background: #0ea5e918;\n            color: #0ea5e9;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #0ea5e930;\n            margin: 2px 3px;\n        \">Embedded analytics</span>\n                                \n        <span style=\"\n            display: inline-block;\n            background: #f59e0b18;\n            color: #f59e0b;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #f59e0b30;\n            margin: 2px 3px;\n        \">NLG</span>\n                                \n        <span style=\"\n            display: inline-block;\n            background: #ef444418;\n            color: #ef4444;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #ef444430;\n            margin: 2px 3px;\n        \">Reporting</span>\n                            </div>\n                            \n        <div style=\"\n            background: #e11d4808;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #e11d48; font-size: 0.92rem;\">\n                They NO longer differentiate on visualization\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">Today, modern ABI platforms <strong>no longer differentiate themselves</strong> through their data visualization capabilities. Their differentiation lies in <strong>enterprise integration</strong> and <strong>augmented capabilities</strong> (AI/ML).</div>\n        </div>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #1e293b, #334155);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M9.4 16.6L4.8 12l4.6-4.6L8 6l-6 6 6 6 1.4-1.4zm5.2 0l4.6-4.6-4.6-4.6L16 6l6 6-6 6-1.4-1.4z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Structure of a Web Page</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <table style=\"\n            width: 100%;\n            border-collapse: collapse;\n            border-radius: 12px;\n            overflow: hidden;\n            box-shadow: 0 1px 6px rgba(0,0,0,0.06);\n            margin: 12px 0;\n        \"><thead><tr><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Level</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Function</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Language</th></tr></thead><tbody><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Structure and Content</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Text, images, links, paragraphs, tables</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">HTML</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Appearance</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Colors, typography, backgrounds, sizes</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">CSS</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Behavior</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Effects, animations, validations, APIs</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">JavaScript</td></tr></tbody></table>\n                            \n        <div style=\"\n            background: #4f6ef708;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #4f6ef7; font-size: 0.92rem;\">\n                CSS Selectors\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\"><strong>Element:</strong> div { ... }<br><strong>Identifier (#):</strong> #header { ... } &mdash; unique per page<br><strong>Class (.):</strong> .highlight { ... } &mdash; reusable</div>\n        </div>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #6d28d9, #4c1d95);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M9.4 16.6L4.8 12l4.6-4.6L8 6l-6 6 6 6 1.4-1.4zm5.2 0l4.6-4.6-4.6-4.6L16 6l6 6-6 6-1.4-1.4z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Brackets: Web Code Editor</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <p><strong>Brackets</strong> is a code editor from Adobe specialized in front-end web development (HTML, CSS, JavaScript). It is not oriented toward Python or back-end development.</p>\n                            \n        <div style=\"\n            background: #05966908;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #059669; font-size: 0.92rem;\">\n                Live Preview\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">Opens a direct connection with the browser so that any change in HTML or CSS is reflected <strong>instantly without reloading</strong> the page.</div>\n        </div>\n                            \n        <div style=\"\n            background: #0ea5e908;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #0ea5e9; font-size: 0.92rem;\">\n                Quick Edit (Ctrl+E)\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">Lets you edit the <strong>CSS associated with an HTML tag</strong> without opening the CSS file. A pop-up window opens inside the same file.</div>\n        </div>\n                            \n        <div style=\"\n            background: #ef444408;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #ef4444; font-size: 0.92rem;\">\n                Real-Time Validation\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">If an HTML tag is not properly closed, it is <strong>marked in red</strong> along with the affected subsequent tags.</div>\n        </div>\n                        \n            </div>\n        </div>\n                    "},"s1":{"sectionTitle":"Topic 2: Google Chart"},"s1i0":{"title":"Google Chart Library","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #4285f4, #0d47a1);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M5 9.2h3V19H5V9.2zM10.6 5h2.8v14h-2.8V5zm5.6 8H19v6h-2.8v-6z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Google Chart: Fundamentals</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <p>Google's charting API, used internally by Google Spreadsheets. It offers:</p>\n                            <ul style=\"padding-left: 20px; margin: 10px 0;\">\n                                <li><strong>Variety:</strong> Pie Chart, Bar Chart, Line Chart, GeoChart, Scatter Plot, etc.</li>\n                                <li><strong>Simplicity:</strong> Just a few steps to get a working visualization</li>\n                                <li><strong>Interactivity:</strong> Native event support</li>\n                            </ul>\n                            \n        <div style=\"\n            background: #4285f408;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #4285f4; font-size: 0.92rem;\">\n                Basic Google Chart Pipeline\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">1. Load the library: <code>google.charts.load()</code> with <code>setOnLoadCallback(drawChart)</code><br>2. Define the data: <code>DataTable</code><br>3. Configure options (title, colors, <code>is3D: true</code>)<br>4. Render: <code>drawChart()</code> calls <code>chart.draw()</code></div>\n        </div>\n                            \n        <div style=\"\n            background: #7c3aed08;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #7c3aed; font-size: 0.92rem;\">\n                DataView vs DataTable\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\"><strong>DataTable:</strong> the main data container (typed columns + rows).<br><strong>DataView:</strong> acts as a <strong>mask</strong> over the DataTable, showing only a subset of columns/rows to a specific chart without altering the original data.</div>\n        </div>\n                            \n        <div style=\"\n            background: #e11d4808;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #e11d48; font-size: 0.92rem;\">\n                GeoChart\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">Visualizes data on a <strong>world or regional map</strong>, shading areas according to the intensity of a numeric value. Unlike PieChart (proportions), it uses <strong>geographic locations</strong>.</div>\n        </div>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #059669, #10b981);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M3 13h8V3H3v10zm0 8h8v-6H3v6zm10 0h8V11h-8v10zm0-18v6h8V3h-8z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">External Data and Events</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            \n        <div style=\"\n            background: #05966908;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #059669; font-size: 0.92rem;\">\n                Google Spreadsheets as a source\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">It requires <strong>public read permissions</strong> or \"anyone with the link\". You use <code>google.visualization.Query</code>. The <code>handleQueryResponse</code> function processes the response (or shows an error if the URL is incorrect).</div>\n        </div>\n                            \n        <div style=\"\n            background: #0ea5e908;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #0ea5e9; font-size: 0.92rem;\">\n                CSV Files\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">They are loaded with <code>$.get()</code> (jQuery) and parsed with <code>$.csv.toArrays()</code> to convert them into a two-dimensional array compatible with DataTable.</div>\n        </div>\n                            \n        <div style=\"\n            background: #f59e0b08;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #f59e0b; font-size: 0.92rem;\">\n                Events\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\"><code>google.visualization.events.addListener()</code> lets you connect visualizations with actions: click, sort, hover. It allows you to create coordinated dashboards.</div>\n        </div>\n                            \n        <div style=\"\n            background: #ef444408;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #ef4444; font-size: 0.92rem;\">\n                Callback and Execution Order\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">If <code>drawChart()</code> runs <strong>before</strong> the library has loaded, an error is thrown. That is why you always use <code>google.charts.setOnLoadCallback(drawChart)</code> to ensure the correct order.</div>\n        </div>\n                        \n            </div>\n        </div>\n                    "},"s2":{"sectionTitle":"Topic 3: D3.js Introduction"},"s2i0":{"title":"D3.js: Basic Concepts","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #f59e0b, #d97706);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M9.4 16.6L4.8 12l4.6-4.6L8 6l-6 6 6 6 1.4-1.4zm5.2 0l4.6-4.6-4.6-4.6L16 6l6 6-6 6-1.4-1.4z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">D3.js: Data-Driven Documents</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <p><strong>D3.js</strong> is a JavaScript library created by <strong>Mike Bostock</strong> that uses HTML, CSS, and SVG to create advanced, dynamic, and interactive visualizations in web browsers.</p>\n                            \n        <div style=\"\n            background: #4f6ef708;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #4f6ef7; font-size: 0.92rem;\">\n                Selectors\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\"><code>d3.select()</code> &mdash; selects one element<br><code>d3.selectAll()</code> &mdash; selects all matching elements</div>\n        </div>\n                            \n        <div style=\"\n            background: #05966908;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #059669; font-size: 0.92rem;\">\n                Data Binding\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">The <code>.data()</code> method binds an array of data to DOM elements.<br>Combined with <code>.enter()</code>, it creates new elements for each data item without a match.</div>\n        </div>\n                            \n        <div style=\"\n            background: #7c3aed08;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #7c3aed; font-size: 0.92rem;\">\n                Chaining\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\"><code>d3.select().data().enter().append().attr().style()</code><br>D3 lets you chain multiple methods in a single fluent expression.</div>\n        </div>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #059669, #10b981);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Advantages of D3.js</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <ul style=\"padding-left: 20px; margin: 10px 0;\">\n                                <li><strong>Full control</strong> over every pixel of the visualization</li>\n                                <li>Rendering in <strong>SVG</strong> (scalable, does not lose quality)</li>\n                                <li>Large community and <strong>thousands of examples</strong> on GitHub</li>\n                                <li>Capability for <strong>highly advanced and customized visualizations</strong></li>\n                            </ul>\n                        \n            </div>\n        </div>\n                    "},"s3":{"sectionTitle":"Topic 4: D3.js Data and SVG"},"s3i0":{"title":"Data Structures and SVG","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #6366f1, #8b5cf6);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M3 13h8V3H3v10zm0 8h8v-6H3v6zm10 0h8V11h-8v10zm0-18v6h8V3h-8z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Data Formats in D3</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <table style=\"\n            width: 100%;\n            border-collapse: collapse;\n            border-radius: 12px;\n            overflow: hidden;\n            box-shadow: 0 1px 6px rgba(0,0,0,0.06);\n            margin: 12px 0;\n        \"><thead><tr><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Format</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">D3 Method</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Description</th></tr></thead><tbody><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>JSON</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><code>d3.json()</code></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Objects with key-value pairs, ideal for hierarchical data</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>CSV</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><code>d3.csv()</code></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Comma-separated values, easy to generate from Excel</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>TSV</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><code>d3.tsv()</code></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Tab-separated values</td></tr></tbody></table>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #e11d48, #f43f5e);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M12 3c-4.97 0-9 4.03-9 9s4.03 9 9 9c.83 0 1.5-.67 1.5-1.5 0-.39-.15-.74-.39-1.01-.23-.26-.38-.61-.38-1-.01-.83.67-1.5 1.5-1.5H16c2.76 0 5-2.24 5-5 0-4.42-4.03-8-9-8zm-5.5 9c-.83 0-1.5-.67-1.5-1.5S5.67 9 6.5 9 8 9.67 8 10.5 7.33 12 6.5 12zm3-4C8.67 8 8 7.33 8 6.5S8.67 5 9.5 5s1.5.67 1.5 1.5S10.33 8 9.5 8zm5 0c-.83 0-1.5-.67-1.5-1.5S13.67 5 14.5 5s1.5.67 1.5 1.5S15.33 8 14.5 8zm3 4c-.83 0-1.5-.67-1.5-1.5S16.67 9 17.5 9s1.5.67 1.5 1.5-.67 1.5-1.5 1.5z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">SVG: Scalable Vector Graphics</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <p>A graphics format that is <strong>vector-based and built on XML</strong>. Main elements:</p>\n                            <table style=\"\n            width: 100%;\n            border-collapse: collapse;\n            border-radius: 12px;\n            overflow: hidden;\n            box-shadow: 0 1px 6px rgba(0,0,0,0.06);\n            margin: 12px 0;\n        \"><thead><tr><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Element</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Use</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Key Attributes</th></tr></thead><tbody><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><code>rect</code></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Rectangles (bars)</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">x, y, width, height</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><code>circle</code></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Circles (points)</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">cx, cy, r</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><code>line</code></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Lines</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">x1, y1, x2, y2</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><code>text</code></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Text labels</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">x, y, font-size</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><code>path</code></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Complex paths</td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">d (instructions)</td></tr></tbody></table>\n                            \n        <div style=\"\n            background: #e11d4808;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #e11d48; font-size: 0.92rem;\">\n                SVG Coordinate System\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">The origin (0,0) is in the <strong>top-left corner</strong>. The Y axis grows <strong>downward</strong>, which requires inverting calculations for conventional charts.</div>\n        </div>\n                        \n            </div>\n        </div>\n                    "},"s4":{"sectionTitle":"Topic 5: D3.js Scales and Axes"},"s4i0":{"title":"Scales and Axes in D3","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #0ea5e9, #0284c7);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M5 9.2h3V19H5V9.2zM10.6 5h2.8v14h-2.8V5zm5.6 8H19v6h-2.8v-6z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Scales</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <p>Scales are <strong>functions that map an input domain to an output range</strong> (Mike Bostock).</p>\n                            <table style=\"\n            width: 100%;\n            border-collapse: collapse;\n            border-radius: 12px;\n            overflow: hidden;\n            box-shadow: 0 1px 6px rgba(0,0,0,0.06);\n            margin: 12px 0;\n        \"><thead><tr><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Type</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Method</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Use</th></tr></thead><tbody><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Linear</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><code>d3.scale.linear()</code></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Continuous, numeric data</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Ordinal</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><code>d3.scale.ordinal()</code></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Categorical, discrete data</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Logarithmic</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><code>d3.scale.log()</code></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Data with exponential ranges</td></tr></tbody></table>\n                            \n        <div style=\"\n            background: #0ea5e908;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #0ea5e9; font-size: 0.92rem;\">\n                Domain vs Range\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\"><strong>Domain (.domain()):</strong> range of values of the input data<br><strong>Range (.range()):</strong> range of visual output pixels<br><br>Example: domain [0, 1000] &rarr; range [0, 500px]</div>\n        </div>\n                            \n        <div style=\"\n            background: #f59e0b08;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #f59e0b; font-size: 0.92rem;\">\n                rangeRoundBands\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\"><code>.rangeRoundBands([min, max], padding)</code> divides the available space into <strong>discrete bands</strong> for categorical data. The <strong>padding</strong> parameter controls the spacing between bands. Ideal for bar charts with categories.</div>\n        </div>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #7c3aed, #a855f7);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M22.7 19l-9.1-9.1c.9-2.3.4-5-1.5-6.9-2-2-5-2.4-7.4-1.3L9 6 6 9 1.6 4.7C.4 7.1.9 10.1 2.9 12.1c1.9 1.9 4.6 2.4 6.9 1.5l9.1 9.1c.4.4 1 .4 1.4 0l2.3-2.3c.5-.4.5-1.1.1-1.4z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Axes</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <p><code>d3.svg.axis()</code> automatically generates reference lines, marks (<strong>ticks</strong>) and labels.</p>\n                            \n        <div style=\"\n            background: #7c3aed08;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #7c3aed; font-size: 0.92rem;\">\n                Axis Configuration\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\"><code>.orient()</code> &mdash; position: bottom, left, top, right<br><code>.ticks()</code> &mdash; number of ticks<br><code>.tickFormat()</code> &mdash; label format<br><br>CSS styles are applied to the classes <code>.axis</code>, <code>.tick</code>, <code>path</code> and <code>line</code>.</div>\n        </div>\n                        \n            </div>\n        </div>\n                    "},"s5":{"sectionTitle":"Topic 6: Interactivity and Transitions"},"s5i0":{"title":"Force Layout and Transitions","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #ef4444, #dc2626);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M17 16l-4-4V8.82C14.16 8.4 15 7.3 15 6c0-1.66-1.34-3-3-3S9 4.34 9 6c0 1.3.84 2.4 2 2.82V12l-4 4H3v5h5v-3.05l4-4.2 4 4.2V21h5v-5h-4z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Force Layout (Force-Directed Graph)</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <p>A physics simulation that positions <strong>nodes</strong> automatically based on repulsion and attraction forces.</p>\n                            \n        <div style=\"\n            background: #ef444408;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #ef4444; font-size: 0.92rem;\">\n                Key Parameters\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\"><code>.charge()</code> &mdash; repulsion/attraction force between nodes<br><code>.linkDistance()</code> &mdash; ideal distance between connected nodes<br><code>force.on(\"tick\", ...)</code> &mdash; updates positions at each simulation step</div>\n        </div>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #f59e0b, #d97706);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M7 2v11h3v9l7-12h-4l4-8z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Transitions and Events</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            \n        <div style=\"\n            background: #05966908;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #059669; font-size: 0.92rem;\">\n                User Events\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\"><code>.on(\"click\")</code>, <code>.on(\"mouseover\")</code>, <code>.on(\"mouseout\")</code><br>They let you add interactivity to charts.</div>\n        </div>\n                            \n        <div style=\"\n            background: #f59e0b08;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #f59e0b; font-size: 0.92rem;\">\n                Transitions\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\"><code>.transition()</code> automatically interpolates values between an initial and a final state.<br><code>.duration()</code> &mdash; duration in milliseconds<br><code>.delay()</code> &mdash; delay before starting</div>\n        </div>\n                            \n        <div style=\"\n            background: #7c3aed08;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #7c3aed; font-size: 0.92rem;\">\n                Enter-Update-Exit Pattern\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\"><code>.enter()</code> &mdash; new data (create elements)<br>Direct update &mdash; existing data<br><code>.exit().remove()</code> &mdash; removed data (remove elements)</div>\n        </div>\n                            \n        <div style=\"\n            background: #4f6ef708;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #4f6ef7; font-size: 0.92rem;\">\n                Export\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\"><strong>SVG:</strong> vector, editable<br><strong>PDF:</strong> from the browser<br><strong>PNG/Bitmap:</strong> rasterized, loses scalability</div>\n        </div>\n                        \n            </div>\n        </div>\n                    "},"s6":{"sectionTitle":"Topic 7: Power BI"},"s6i0":{"title":"Microsoft Power BI","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #4f6ef7, #2563eb);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M5 9.2h3V19H5V9.2zM10.6 5h2.8v14h-2.8V5zm5.6 8H19v6h-2.8v-6z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Power BI: Fundamentals</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <p>A Microsoft tool that is a <strong>leader in the Gartner Magic Quadrant</strong>. It integrates multiple data sources and generates interactive visualizations.</p>\n                            <table style=\"\n            width: 100%;\n            border-collapse: collapse;\n            border-radius: 12px;\n            overflow: hidden;\n            box-shadow: 0 1px 6px rgba(0,0,0,0.06);\n            margin: 12px 0;\n        \"><thead><tr><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Version</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Description</th></tr></thead><tbody><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Desktop</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Free, personal analysis</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Pro</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Cloud collaboration</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Premium</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Enterprise capacity</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Server</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">On-premises</td></tr></tbody></table>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #059669, #10b981);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M11.99 18.54l-7.37-5.73L3 14.07l9 7 9-7-1.63-1.27zM12 16l7.36-5.73L21 9l-9-7-9 7 1.63 1.27L12 16z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Interface and Features</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            \n        <div style=\"\n            background: #4f6ef708;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #4f6ef7; font-size: 0.92rem;\">\n                Interface\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\"><strong>Left pane:</strong> Report, Data, Model<br><strong>Right pane:</strong> Visualizations and Fields</div>\n        </div>\n                            \n        <div style=\"\n            background: #05966908;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #059669; font-size: 0.92rem;\">\n                Power Query (ETL)\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">An editor to <strong>transform data</strong> before loading it into the model. It lets you remove columns, filter rows, change types, and combine queries.</div>\n        </div>\n                            \n        <div style=\"\n            background: #f59e0b08;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #f59e0b; font-size: 0.92rem;\">\n                Visualizations\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">Table, bar charts, line, pie, map, scatter, <strong>Slicers</strong> (data segmentation).</div>\n        </div>\n                        \n            </div>\n        </div>\n                    "},"s7":{"sectionTitle":"Topic 8: Qlik Sense"},"s7i0":{"title":"Qlik Sense: BI Platform","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #59a14f, #2d6a4f);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M12 10.9c-.61 0-1.1.49-1.1 1.1s.49 1.1 1.1 1.1c.61 0 1.1-.49 1.1-1.1s-.49-1.1-1.1-1.1zM12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm2.19 12.19L6 18l3.81-8.19L18 6l-3.81 8.19z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Qlik Sense: Data Discovery</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <p>A complete platform oriented toward <strong>information discovery</strong>. Not just visualization, but complete Business Intelligence capabilities.</p>\n                            <table style=\"\n            width: 100%;\n            border-collapse: collapse;\n            border-radius: 12px;\n            overflow: hidden;\n            box-shadow: 0 1px 6px rgba(0,0,0,0.06);\n            margin: 12px 0;\n        \"><thead><tr><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Version</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Description</th></tr></thead><tbody><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Business</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">SaaS, small teams, API limitations</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Enterprise</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Multi-cloud, massive deployment, Nprinting, GeoAnalytics</td></tr></tbody></table>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #6366f1, #8b5cf6);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M3 13h8V3H3v10zm0 8h8v-6H3v6zm10 0h8V11h-8v10zm0-18v6h8V3h-8z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Key Qlik Sense Concepts</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            \n        <div style=\"\n            background: #6366f108;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #6366f1; font-size: 0.92rem;\">\n                Apps\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">The unit of work in Qlik Sense. They are created empty or from templates and are fed by data connectors.</div>\n        </div>\n                            \n        <div style=\"\n            background: #05966908;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #059669; font-size: 0.92rem;\">\n                Dimensions vs. Measures\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\"><strong>Dimensions:</strong> grouping categories<br><strong>Measures:</strong> numeric values to calculate (sum, avg, count)</div>\n        </div>\n                            \n        <div style=\"\n            background: #f59e0b08;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #f59e0b; font-size: 0.92rem;\">\n                Features\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\"><strong>Filter Pane:</strong> interactive filter selection<br><strong>Pivot Tables:</strong> breakdown by multiple dimensions<br><strong>Stories:</strong> narrative presentations<br><strong>Scatter Plot:</strong> relationships between two variables<br><strong>Bookmarks:</strong> saving analysis states</div>\n        </div>\n                        \n            </div>\n        </div>\n                    "},"s8":{"sectionTitle":"Topic 9: Tableau Introduction"},"s8i0":{"title":"Tableau: Fundamentals","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #e97627, #c75b12);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M5 9.2h3V19H5V9.2zM10.6 5h2.8v14h-2.8V5zm5.6 8H19v6h-2.8v-6z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Tableau: Visual Platform</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <p>A highly visual tool and a leader in the Gartner quadrant. Founded at <strong>Stanford University</strong> by Pat Hanrahan and Chris Stolte.</p>\n                            \n        <div style=\"\n            background: #e9762708;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #e97627; font-size: 0.92rem;\">\n                VizQL (Visual Query Language)\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">Patented technology that translates <strong>drag-and-drop</strong> actions into optimized database queries. VizQL formed the core of the <strong>Polaris</strong> system, the original interface for exploring large multidimensional databases.</div>\n        </div>\n                            \n        <div style=\"\n            background: #05966908;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #059669; font-size: 0.92rem;\">\n                Hyper Engine\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">Enables fast ad hoc analysis of <strong>massive data</strong> even on computers with standard specifications.</div>\n        </div>\n                            \n        <div style=\"\n            background: #4f6ef708;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #4f6ef7; font-size: 0.92rem;\">\n                Acquisition by Salesforce\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">In <strong>2019 Salesforce</strong> signed a definitive agreement to acquire Tableau, consolidating the platform within the CRM and enterprise analytics ecosystem.</div>\n        </div>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M11.99 18.54l-7.37-5.73L3 14.07l9 7 9-7-1.63-1.27zM12 16l7.36-5.73L21 9l-9-7-9 7 1.63 1.27L12 16z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Versions and Interface</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <table style=\"\n            width: 100%;\n            border-collapse: collapse;\n            border-radius: 12px;\n            overflow: hidden;\n            box-shadow: 0 1px 6px rgba(0,0,0,0.06);\n            margin: 12px 0;\n        \"><thead><tr><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Version</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Description</th></tr></thead><tbody><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Desktop</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Personal analysis</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Server</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">On-premises</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Online/Cloud</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">SaaS</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Public</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Free, public data</td></tr></tbody></table>\n                            \n        <div style=\"\n            background: #4f6ef708;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #4f6ef7; font-size: 0.92rem;\">\n                Interface Elements\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\"><strong>Rows/Columns Shelves:</strong> define the structure of the chart<br><strong>Marks Card:</strong> Color, Size, Text, Detail, Shape, Tooltip<br><strong>Filters Shelf:</strong> restricts the visible data</div>\n        </div>\n                        \n            </div>\n        </div>\n                    "},"s9":{"sectionTitle":"Topic 10: Advanced Tableau"},"s9i0":{"title":"Filters, Dashboards, and Stories","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #7c3aed, #a855f7);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M10 18h4v-2h-4v2zM3 6v2h18V6H3zm3 7h12v-2H6v2z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Filters and Pages</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            \n        <div style=\"\n            background: #7c3aed08;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #7c3aed; font-size: 0.92rem;\">\n                Advanced Filters\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">Conditions based on ranges, thresholds, <strong>Top N</strong> and custom formulas for granular control.</div>\n        </div>\n                            \n        <div style=\"\n            background: #0ea5e908;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #0ea5e9; font-size: 0.92rem;\">\n                Pages\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">They split the visualization into <strong>sequential</strong> views based on a field (usually a time field).<br><br><strong>Difference from filters:</strong> pages do NOT remove data; they organize it into navigable layers.</div>\n        </div>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #059669, #10b981);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M3 3v18h18V3H3zm8 16H5v-6h6v6zm0-8H5V5h6v6zm8 8h-6v-6h6v6zm0-8h-6V5h6v6z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Dashboards and Stories</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            \n        <div style=\"\n            background: #05966908;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #059669; font-size: 0.92rem;\">\n                Dashboards\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">A collection of <strong>interactive worksheets</strong> on a single screen. They are created from the icon in the bottom bar.</div>\n        </div>\n                            \n        <div style=\"\n            background: #f59e0b08;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #f59e0b; font-size: 0.92rem;\">\n                Dynamic Filter in Dashboards\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">\"Funnel\" icon (<strong>Use as Filter</strong>) so that when you select a mark, the other sheets are filtered automatically.</div>\n        </div>\n                            \n        <div style=\"\n            background: #4f6ef708;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #4f6ef7; font-size: 0.92rem;\">\n                Actions\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\"><strong>Filter:</strong> filter data across sheets<br><strong>Highlight:</strong> highlight related marks<br><strong>Navigation:</strong> \"Go to Sheet\" for dynamic exploration</div>\n        </div>\n                            \n        <div style=\"\n            background: #e11d4808;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #e11d48; font-size: 0.92rem;\">\n                Stories\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">Narrative presentations that guide the user through a <strong>sequence of visualizations</strong>.</div>\n        </div>\n                        \n            </div>\n        </div>\n                    "},"s10":{"sectionTitle":"Topic 11: CARTO - Location Intelligence"},"s10i0":{"title":"CARTO and Geospatial Data","content":"\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #e11d48, #be123c);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M20.5 3l-.16.03L15 5.1 9 3 3.36 4.9c-.21.07-.36.25-.36.48V20.5c0 .28.22.5.5.5l.16-.03L9 18.9l6 2.1 5.64-1.9c.21-.07.36-.25.36-.48V3.5c0-.28-.22-.5-.5-.5zM15 19l-6-2.11V5l6 2.11V19z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">CARTO: Location Intelligence</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <p>A leading <strong>Location Intelligence</strong> platform that transforms location data into strategic decisions. Founded in 2007, used by NASA, Google, and the Wall Street Journal.</p>\n                            \n        <div style=\"\n            background: #4f6ef708;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #4f6ef7; font-size: 0.92rem;\">\n                GIS (Geographic Information System)\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">It lets you <strong>overlay data layers on maps</strong> to identify spatial patterns.</div>\n        </div>\n                            \n        <div style=\"\n            background: #05966908;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #059669; font-size: 0.92rem;\">\n                Location Intelligence\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">It emerged with the mass adoption of GPS in smartphones (2008). It combines <strong>Big Data, cloud computing, and IoT</strong> to optimize geospatial processes.</div>\n        </div>\n                        \n            </div>\n        </div>\n                        \n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(79,110,247,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #6366f1, #8b5cf6);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M11.99 18.54l-7.37-5.73L3 14.07l9 7 9-7-1.63-1.27zM12 16l7.36-5.73L21 9l-9-7-9 7 1.63 1.27L12 16z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">CARTO Features</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n                            <table style=\"\n            width: 100%;\n            border-collapse: collapse;\n            border-radius: 12px;\n            overflow: hidden;\n            box-shadow: 0 1px 6px rgba(0,0,0,0.06);\n            margin: 12px 0;\n        \"><thead><tr><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Feature</th><th style=\"\n            background: linear-gradient(135deg, #4f6ef7, #7c3aed);\n            color: #fff;\n            padding: 10px 14px;\n            font-weight: 600;\n            font-size: 0.85rem;\n            text-align: left;\n            border: none;\n        \">Description</th></tr></thead><tbody><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Deployment</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">On-premises or cloud SaaS</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Data loading</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Drag and drop (CSV, Excel, GeoJSON)</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>the_geom</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Geometry column for mapping records (lat/long)</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Widgets</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Category, Histogram, Formula, Time Series</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Spatial Analysis</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Create Lines from Points, Group By, Transform</td></tr><tr style=\"transition: background 0.2s;\"><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \"><strong>Inline SQL</strong></td><td style=\"\n                padding: 10px 14px;\n                border-bottom: 1px solid var(--border-color, #e8e8e8);\n                font-size: 0.9rem;\n            \">Direct SQL queries in the interface</td></tr></tbody></table>\n                            \n        <div style=\"\n            background: #e11d4808;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #e11d48; font-size: 0.92rem;\">\n                PostgreSQL/PostGIS Engine\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">CARTO uses PostgreSQL with the <strong>PostGIS</strong> extension in the cloud to run high-performance spatial queries.</div>\n        </div>\n                        \n            </div>\n        </div>\n                    "}},"unah-tesis":{"s0":{"sectionTitle":"4. TCROC and Its Variants"},"s0i0":{"title":"4.1 — Unified General Framework (Master Equation)","content":"\n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(0,100,60,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #1a5276, #2e86c1);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M5 3h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2zm4.5 5L7 11l2.5 3H11l-2-2.5L11 9H9.5zm5 0H13l2 2.5L13 13h1.5L17 10l-2.5-3z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">General TCROC Equation</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                <p>This is the <b>master equation</b> of the entire thesis. All the variants are derived from it.</p>\n                        \n        <div style=\"\n            background: #1a527608;\n            border-left: 4px solid #1a5276;\n            border-radius: 0 12px 12px 0;\n            padding: 16px 18px;\n            margin: 14px 0;\n        \">\n            <div style=\"font-size: 1.05rem; font-weight: 600; text-align: center; margin-bottom: 10px; padding: 12px; background: rgba(0,0,0,0.03); border-radius: 8px; font-family: 'Courier New', Consolas, monospace; color: var(--text-color);\">\n                &alpha;<sub>t,&lambda;,W</sub> = &minus;1 + argmin<sub>&beta;&isin;&reals;</sub> &sum;<sub>k=t&minus;W+1</sub><sup>t</sup> &lambda;<sup>t&minus;k</sup> (v(k) &minus; &beta; &middot; v(k&minus;1))<sup>2</sup>\n            </div>\n            <div style=\"margin-top: 10px;\">\n                <div style=\"font-weight: 700; color: #2e86c1; font-size: 0.85rem; margin-bottom: 4px; display:flex; align-items:center; gap:6px;\">\n                    <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#2e86c1\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M18 2H6c-1.1 0-2 .9-2 2v16c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2zM6 4h5v8l-2.5-1.5L6 12V4z\"/></svg> How to read it (without reading it literally):\n                </div>\n                <div style=\"font-size: 0.9rem; line-height: 1.6; color: var(--text-color); padding-left: 8px; border-left: 2px solid #2e86c188; margin-left: 4px;\">\"The relative rate of change alpha at time t, with parameters lambda and W, is obtained by subtracting one from the value of beta that minimizes the weighted sum of squared errors between the observed value and its multiplicative prediction, evaluated within a window of W observations with weights that decay exponentially according to lambda.\"</div>\n            </div>\n            <div style=\"margin-top: 10px;\">\n                <div style=\"font-weight: 700; color: #8e44ad; font-size: 0.85rem; margin-bottom: 4px; display:flex; align-items:center; gap:6px;\">\n                    <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#8e44ad\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M19 5h-2V3H7v2H5c-1.1 0-2 .9-2 2v1c0 2.55 1.92 4.63 4.39 4.94.63 1.5 1.98 2.63 3.61 2.96V19H7v2h10v-2h-4v-3.1c1.63-.33 2.98-1.46 3.61-2.96C19.08 12.63 21 10.55 21 8V7c0-1.1-.9-2-2-2z\"/></svg> In the defense (before master's and doctoral faculty):\n                </div>\n                <div style=\"font-size: 0.9rem; line-height: 1.6; color: var(--text-color); padding-left: 8px; border-left: 2px solid #8e44ad88; margin-left: 4px;\">\"This equation defines a transformation operator that converts the raw series into relative rates of change. It is the foundation of the entire TCROC family. Its elegance lies in the fact that it admits a closed-form analytical solution, unlike iterative methods such as MLE or ARIMA, and it satisfies four axioms: bounded locality, geometric proportionality, global convexity, and Lipschitz stability.\"</div>\n            </div>\n        </div>\n                        \n        <div style=\"\n            background: #00664408;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #006644; font-size: 0.92rem;\">\n                Why do we use TCROC?\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">\n                            The raw time series (GDP, fuel prices) is non-stationary and noisy.\n                            The TCROC operator transforms this series into a sequence of relative rates of change that <b>are stationary</b>,\n                            which is a prerequisite for discretizing into Markov chains.\n                            It is the mathematical foundation that prepares the data before any stochastic modeling.\n                        </div>\n        </div>\n                        <div style=\"overflow-x:auto; margin:10px 0;\"><table style=\"width:100%;border-collapse:collapse;font-size:0.88rem;\"><thead><tr><th style=\"background:#00664415;color:#006644;padding:8px 10px;text-align:left;border-bottom:2px solid #00664430;font-weight:700;\">Variant</th><th style=\"background:#00664415;color:#006644;padding:8px 10px;text-align:left;border-bottom:2px solid #00664430;font-weight:700;\">Parameters</th><th style=\"background:#00664415;color:#006644;padding:8px 10px;text-align:left;border-bottom:2px solid #00664430;font-weight:700;\">Use</th></tr></thead><tbody><tr><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">TCROC</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">&lambda;=1, W=T</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">Theoretical baseline (degenerate)</td></tr><tr><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">TCROCM</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">&lambda;=1, W&lt;T</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">Moving window, uniform weights</td></tr><tr><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">ETCROC</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">&lambda;&lt;1, W=T</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">Global exponential decay</td></tr><tr><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">ETCROCM</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">&lambda;&lt;1, W&lt;T</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">Most general form (uses both)</td></tr></tbody></table></div>\n                        \n            </div>\n        </div>"},"s0i1":{"title":"4.2 — Closed-Form Analytical Solution","content":"\n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(0,100,60,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #1a5276, #154360);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M12 1L3 5v6c0 5.55 3.84 10.74 9 12 5.16-1.26 9-6.45 9-12V5l-9-4z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Existence and Uniqueness Theorem</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                <p><b>Theorem:</b> If there is at least one nonzero value in the window, the minimizer is unique.</p>\n                        \n        <div style=\"\n            background: #1a527608;\n            border-left: 4px solid #1a5276;\n            border-radius: 0 12px 12px 0;\n            padding: 16px 18px;\n            margin: 14px 0;\n        \">\n            <div style=\"font-size: 1.05rem; font-weight: 600; text-align: center; margin-bottom: 10px; padding: 12px; background: rgba(0,0,0,0.03); border-radius: 8px; font-family: 'Courier New', Consolas, monospace; color: var(--text-color);\">\n                &beta;<sup>&#x0302;</sup><sub>t,&lambda;,W</sub> = &sum; &lambda;<sup>t&minus;k</sup> v(k) v(k&minus;1) &frasl; &sum; &lambda;<sup>t&minus;k</sup> v(k&minus;1)<sup>2</sup>\n            </div>\n            <div style=\"margin-top: 10px;\">\n                <div style=\"font-weight: 700; color: #2e86c1; font-size: 0.85rem; margin-bottom: 4px; display:flex; align-items:center; gap:6px;\">\n                    <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#2e86c1\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M18 2H6c-1.1 0-2 .9-2 2v16c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2zM6 4h5v8l-2.5-1.5L6 12V4z\"/></svg> How to read it (without reading it literally):\n                </div>\n                <div style=\"font-size: 0.9rem; line-height: 1.6; color: var(--text-color); padding-left: 8px; border-left: 2px solid #2e86c188; margin-left: 4px;\">\"Beta hat is computed as the ratio between the weighted sum of the cross products of consecutive values and the weighted sum of the squares of the previous values, both evaluated within the window W with exponential weights lambda.\"</div>\n            </div>\n            <div style=\"margin-top: 10px;\">\n                <div style=\"font-weight: 700; color: #8e44ad; font-size: 0.85rem; margin-bottom: 4px; display:flex; align-items:center; gap:6px;\">\n                    <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#8e44ad\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M19 5h-2V3H7v2H5c-1.1 0-2 .9-2 2v1c0 2.55 1.92 4.63 4.39 4.94.63 1.5 1.98 2.63 3.61 2.96V19H7v2h10v-2h-4v-3.1c1.63-.33 2.98-1.46 3.61-2.96C19.08 12.63 21 10.55 21 8V7c0-1.1-.9-2-2-2z\"/></svg> In the defense (before master's and doctoral faculty):\n                </div>\n                <div style=\"font-size: 0.9rem; line-height: 1.6; color: var(--text-color); padding-left: 8px; border-left: 2px solid #8e44ad88; margin-left: 4px;\">\"This result is central because it shows that our operator has a closed-form solution — it does not need numerical iteration. It is a ratio of two weighted dot products. The proof rests on the strict convexity of the quadratic functional.\"</div>\n            </div>\n        </div>\n                        \n        <div style=\"\n            background: #00664408;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #006644; font-size: 0.92rem;\">\n                Relationship with OLS and GLS\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">\n                            \n        <span style=\"\n            display: inline-block;\n            background: #1a527618;\n            color: #1a5276;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #1a527630;\n            margin: 2px 3px;\n        \">TCROC &equiv; OLS</span> when &lambda;=1: it coincides with ordinary least squares.<br>\n                            \n        <span style=\"\n            display: inline-block;\n            background: #8e44ad18;\n            color: #8e44ad;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #8e44ad30;\n            margin: 2px 3px;\n        \">ETCROC &equiv; GLS</span> when &lambda;&lt;1: it coincides with generalized least squares.<br>\n                            The generalized Gauss-Markov Theorem (Aitken, 1936) guarantees that it is BLUE (Best Linear Unbiased Estimator).\n                        </div>\n        </div>\n                        \n            </div>\n        </div>"},"s0i2":{"title":"4.3 — Asymptotic Consistency","content":"\n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(0,100,60,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #27ae60, #1e8449);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41L9 16.17z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Consistency Theorem</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                <p><b>Theorem:</b> Under a stationary AR(1) model, as W &rarr; &infin;, the estimator converges to the true value.</p>\n                        \n        <div style=\"\n            background: #1a527608;\n            border-left: 4px solid #1a5276;\n            border-radius: 0 12px 12px 0;\n            padding: 16px 18px;\n            margin: 14px 0;\n        \">\n            <div style=\"font-size: 1.05rem; font-weight: 600; text-align: center; margin-bottom: 10px; padding: 12px; background: rgba(0,0,0,0.03); border-radius: 8px; font-family: 'Courier New', Consolas, monospace; color: var(--text-color);\">\n                &beta;<sup>&#x0302;</sup><sub>t,&lambda;,W</sub> &xrarr;<sup>p</sup> &beta;* &nbsp;&nbsp; and &nbsp;&nbsp; &alpha;<sub>t,&lambda;,W</sub> &xrarr;<sup>p</sup> &beta;* &minus; 1\n            </div>\n            <div style=\"margin-top: 10px;\">\n                <div style=\"font-weight: 700; color: #2e86c1; font-size: 0.85rem; margin-bottom: 4px; display:flex; align-items:center; gap:6px;\">\n                    <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#2e86c1\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M18 2H6c-1.1 0-2 .9-2 2v16c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2zM6 4h5v8l-2.5-1.5L6 12V4z\"/></svg> How to read it (without reading it literally):\n                </div>\n                <div style=\"font-size: 0.9rem; line-height: 1.6; color: var(--text-color); padding-left: 8px; border-left: 2px solid #2e86c188; margin-left: 4px;\">\"Beta hat converges in probability to the true beta star as the window W grows toward infinity, and consequently alpha converges to beta star minus one.\"</div>\n            </div>\n            <div style=\"margin-top: 10px;\">\n                <div style=\"font-weight: 700; color: #8e44ad; font-size: 0.85rem; margin-bottom: 4px; display:flex; align-items:center; gap:6px;\">\n                    <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#8e44ad\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M19 5h-2V3H7v2H5c-1.1 0-2 .9-2 2v1c0 2.55 1.92 4.63 4.39 4.94.63 1.5 1.98 2.63 3.61 2.96V19H7v2h10v-2h-4v-3.1c1.63-.33 2.98-1.46 3.61-2.96C19.08 12.63 21 10.55 21 8V7c0-1.1-.9-2-2-2z\"/></svg> In the defense (before master's and doctoral faculty):\n                </div>\n                <div style=\"font-size: 0.9rem; line-height: 1.6; color: var(--text-color); padding-left: 8px; border-left: 2px solid #8e44ad88; margin-left: 4px;\">\"Asymptotic consistency validates that, with enough data, our estimator gets arbitrarily close to the true value. The proof uses the Law of Large Numbers for stationary weighted sequences and Slutsky's Lemma to handle the ratio.\"</div>\n            </div>\n        </div>\n                        \n        <div style=\"\n            background: #00664408;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #006644; font-size: 0.92rem;\">\n                <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#c0392b\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M1 21h22L12 2 1 21zm12-3h-2v-2h2v2zm0-4h-2v-4h2v4z\"/></svg> Note on stationarity\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">\n                            Economic series such as GDP usually have &beta;* &asymp; 1 (unit root).\n                            However, the <b>&alpha; operator<sub>t</sub></b> acts as a local differencing filter,\n                            and the resulting series {&alpha;<sub>t</sub>} is generally stationary.\n                            This is verified empirically with the ADF test (p &lt; 0.01) in Chapter 7.\n                        </div>\n        </div>\n                        \n            </div>\n        </div>"},"s0i3":{"title":"4.4 — Lipschitz Stability","content":"\n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(0,100,60,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #d35400, #e67e22);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M12 1L3 5v6c0 5.55 3.84 10.74 9 12 5.16-1.26 9-6.45 9-12V5l-9-4z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Stability Lemma</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                <p><b>Lemma:</b> Bounded perturbations in the series produce controlled deviations in the rate &alpha;.</p>\n                        \n        <div style=\"\n            background: #1a527608;\n            border-left: 4px solid #1a5276;\n            border-radius: 0 12px 12px 0;\n            padding: 16px 18px;\n            margin: 14px 0;\n        \">\n            <div style=\"font-size: 1.05rem; font-weight: 600; text-align: center; margin-bottom: 10px; padding: 12px; background: rgba(0,0,0,0.03); border-radius: 8px; font-family: 'Courier New', Consolas, monospace; color: var(--text-color);\">\n                |&alpha;'<sub>t,&lambda;,W</sub> &minus; &alpha;<sub>t,&lambda;,W</sub>| &le; C<sub>t</sub> &middot; &epsilon;\n            </div>\n            <div style=\"margin-top: 10px;\">\n                <div style=\"font-weight: 700; color: #2e86c1; font-size: 0.85rem; margin-bottom: 4px; display:flex; align-items:center; gap:6px;\">\n                    <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#2e86c1\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M18 2H6c-1.1 0-2 .9-2 2v16c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2zM6 4h5v8l-2.5-1.5L6 12V4z\"/></svg> How to read it (without reading it literally):\n                </div>\n                <div style=\"font-size: 0.9rem; line-height: 1.6; color: var(--text-color); padding-left: 8px; border-left: 2px solid #2e86c188; margin-left: 4px;\">\"The absolute difference between the alpha rates of the perturbed series and the original series is bounded by a constant C sub t multiplied by the magnitude of the perturbation epsilon.\"</div>\n            </div>\n            <div style=\"margin-top: 10px;\">\n                <div style=\"font-weight: 700; color: #8e44ad; font-size: 0.85rem; margin-bottom: 4px; display:flex; align-items:center; gap:6px;\">\n                    <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#8e44ad\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M19 5h-2V3H7v2H5c-1.1 0-2 .9-2 2v1c0 2.55 1.92 4.63 4.39 4.94.63 1.5 1.98 2.63 3.61 2.96V19H7v2h10v-2h-4v-3.1c1.63-.33 2.98-1.46 3.61-2.96C19.08 12.63 21 10.55 21 8V7c0-1.1-.9-2-2-2z\"/></svg> In the defense (before master's and doctoral faculty):\n                </div>\n                <div style=\"font-size: 0.9rem; line-height: 1.6; color: var(--text-color); padding-left: 8px; border-left: 2px solid #8e44ad88; margin-left: 4px;\">\"This result is Axiom 4 made real: the operator is robust to noise. If the data have small measurement errors, the subsequent discretization will not produce spurious results. The proof uses the quotient formula and the Cauchy-Schwarz inequality.\"</div>\n            </div>\n        </div>\n                        \n            </div>\n        </div>"},"s0i4":{"title":"4.5 — Algorithmic Complexity","content":"\n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(0,100,60,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #2c3e50, #34495e);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M22.7 19l-9.1-9.1c.9-2.3.4-5-1.5-6.9-2-2-5-2.4-7.4-1.3L9 6 6 9 1.6 4.7C.4 7.1.9 10.1 2.9 12.1c1.9 1.9 4.6 2.4 6.9 1.5l9.1 9.1c.4.4 1 .4 1.4 0l2.3-2.3c.5-.4.5-1.1.1-1.4z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Computational Complexity</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                <div style=\"overflow-x:auto; margin:10px 0;\"><table style=\"width:100%;border-collapse:collapse;font-size:0.88rem;\"><thead><tr><th style=\"background:#00664415;color:#006644;padding:8px 10px;text-align:left;border-bottom:2px solid #00664430;font-weight:700;\">Method</th><th style=\"background:#00664415;color:#006644;padding:8px 10px;text-align:left;border-bottom:2px solid #00664430;font-weight:700;\">Complexity</th><th style=\"background:#00664415;color:#006644;padding:8px 10px;text-align:left;border-bottom:2px solid #00664430;font-weight:700;\">TCROC Advantage</th></tr></thead><tbody><tr><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">TCROC / ETCROC</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">O(T)</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">Closed-form, linear solution</td></tr><tr><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">TCROCM / ETCROCM</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">O(T &middot; W)</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">No iteration</td></tr><tr><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">MLE (Hamilton)</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">O(T&sup2;) &ndash; O(T&sup3;)</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\"><b>TCROC is much faster</b></td></tr><tr><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">ARIMA</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">O(T&sup2;)</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\"><b>TCROC does not require iteration</b></td></tr><tr><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">Neural Networks</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">O(T &middot; L)</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">TCROC does not need training</td></tr></tbody></table></div>\n        <div style=\"\n            background: #00664408;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #006644; font-size: 0.92rem;\">\n                Recursive ETCROC implementation\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">\n                            ETCROC supports O(1) incremental computation per observation:<br>\n                            <code style=\"font-family:'Courier New',Consolas,monospace;background:rgba(0,0,0,0.04);padding:1px 5px;border-radius:4px;font-size:0.95em;\">S₁(t) = &lambda; S₁(t&minus;1) + v(t)v(t&minus;1)</code><br>\n                            <code style=\"font-family:'Courier New',Consolas,monospace;background:rgba(0,0,0,0.04);padding:1px 5px;border-radius:4px;font-size:0.95em;\">S₂(t) = &lambda; S₂(t&minus;1) + v(t&minus;1)²</code>\n                        </div>\n        </div>\n            </div>\n        </div>"},"s1":{"sectionTitle":"5. Integrating TCROC with Markov Chains"},"s1i0":{"title":"5.1 — Quantization Function &pi;","content":"\n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(0,100,60,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #8e44ad, #6c3483);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M11.99 18.54l-7.37-5.73L3 14.07l9 7 9-7-1.63-1.27zM12 16l7.36-5.73L21 9l-9-7-9 7 1.63 1.27L12 16z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">State Discretization</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                <p>The function &pi; maps the continuous rate &alpha;<sub>t</sub> to a discrete state S<sub>t</sub>.</p>\n                        \n        <div style=\"\n            background: #1a527608;\n            border-left: 4px solid #1a5276;\n            border-radius: 0 12px 12px 0;\n            padding: 16px 18px;\n            margin: 14px 0;\n        \">\n            <div style=\"font-size: 1.05rem; font-weight: 600; text-align: center; margin-bottom: 10px; padding: 12px; background: rgba(0,0,0,0.03); border-radius: 8px; font-family: 'Courier New', Consolas, monospace; color: var(--text-color);\">\n                S<sub>t</sub> = &pi;(&alpha;<sub>t,&lambda;,W</sub>)\n            </div>\n            <div style=\"margin-top: 10px;\">\n                <div style=\"font-weight: 700; color: #2e86c1; font-size: 0.85rem; margin-bottom: 4px; display:flex; align-items:center; gap:6px;\">\n                    <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#2e86c1\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M18 2H6c-1.1 0-2 .9-2 2v16c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2zM6 4h5v8l-2.5-1.5L6 12V4z\"/></svg> How to read it (without reading it literally):\n                </div>\n                <div style=\"font-size: 0.9rem; line-height: 1.6; color: var(--text-color); padding-left: 8px; border-left: 2px solid #2e86c188; margin-left: 4px;\">\"The state S at time t is obtained by applying the quantization function pi to the rate alpha.\"</div>\n            </div>\n            <div style=\"margin-top: 10px;\">\n                <div style=\"font-weight: 700; color: #8e44ad; font-size: 0.85rem; margin-bottom: 4px; display:flex; align-items:center; gap:6px;\">\n                    <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#8e44ad\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M19 5h-2V3H7v2H5c-1.1 0-2 .9-2 2v1c0 2.55 1.92 4.63 4.39 4.94.63 1.5 1.98 2.63 3.61 2.96V19H7v2h10v-2h-4v-3.1c1.63-.33 2.98-1.46 3.61-2.96C19.08 12.63 21 10.55 21 8V7c0-1.1-.9-2-2-2z\"/></svg> In the defense (before master's and doctoral faculty):\n                </div>\n                <div style=\"font-size: 0.9rem; line-height: 1.6; color: var(--text-color); padding-left: 8px; border-left: 2px solid #8e44ad88; margin-left: 4px;\">\"Quantization is the bridge between the continuous world of the TCROC operator and the discrete world of Markov chains. We use K-Means instead of fixed thresholds because it adapts the cutoff points to the empirical distribution of each series.\"</div>\n            </div>\n        </div>\n                        <div style=\"overflow-x:auto; margin:10px 0;\"><table style=\"width:100%;border-collapse:collapse;font-size:0.88rem;\"><thead><tr><th style=\"background:#00664415;color:#006644;padding:8px 10px;text-align:left;border-bottom:2px solid #00664430;font-weight:700;\">State</th><th style=\"background:#00664415;color:#006644;padding:8px 10px;text-align:left;border-bottom:2px solid #00664430;font-weight:700;\">Threshold (theoretical)</th><th style=\"background:#00664415;color:#006644;padding:8px 10px;text-align:left;border-bottom:2px solid #00664430;font-weight:700;\">Interpretation</th></tr></thead><tbody><tr><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">s₁</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">&alpha; &gt; 0.05</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">Strong growth</td></tr><tr><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">s₂</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">0 &lt; &alpha; &le; 0.05</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">Moderate growth</td></tr><tr><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">s₃</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">&minus;0.05 &le; &alpha; &le; 0</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">Mild decline</td></tr><tr><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">s₄</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">&alpha; &lt; &minus;0.05</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">Severe decline</td></tr></tbody></table></div>\n                        \n        <div style=\"\n            background: #00664408;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #006644; font-size: 0.92rem;\">\n                In practice: K-Means\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">The fixed &plusmn;0.05 thresholds are theoretical.\n                        In the empirical chapters, the thresholds are determined <b>endogenously by K-Means</b>,\n                        adapting to the observed distribution of each series.</div>\n        </div>\n                        \n            </div>\n        </div>"},"s1i1":{"title":"5.2 — First-Order Markovian Structure","content":"\n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(0,100,60,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #2c3e50, #1a252f);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M19 3H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zM9 17H7v-7h2v7zm4 0h-2V7h2v10zm4 0h-2v-4h2v4z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Markovian Theorem</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                <p><b>Theorem:</b> The sequence {S<sub>t</sub>} satisfies the first-order Markov property.</p>\n                        \n        <div style=\"\n            background: #1a527608;\n            border-left: 4px solid #1a5276;\n            border-radius: 0 12px 12px 0;\n            padding: 16px 18px;\n            margin: 14px 0;\n        \">\n            <div style=\"font-size: 1.05rem; font-weight: 600; text-align: center; margin-bottom: 10px; padding: 12px; background: rgba(0,0,0,0.03); border-radius: 8px; font-family: 'Courier New', Consolas, monospace; color: var(--text-color);\">\n                P(S<sub>t+1</sub>=s<sub>j</sub> | S<sub>t</sub>=s<sub>i</sub>, S<sub>t&minus;1</sub>, ...) = P(S<sub>t+1</sub>=s<sub>j</sub> | S<sub>t</sub>=s<sub>i</sub>) = P<sub>ji</sub>\n            </div>\n            <div style=\"margin-top: 10px;\">\n                <div style=\"font-weight: 700; color: #2e86c1; font-size: 0.85rem; margin-bottom: 4px; display:flex; align-items:center; gap:6px;\">\n                    <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#2e86c1\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M18 2H6c-1.1 0-2 .9-2 2v16c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2zM6 4h5v8l-2.5-1.5L6 12V4z\"/></svg> How to read it (without reading it literally):\n                </div>\n                <div style=\"font-size: 0.9rem; line-height: 1.6; color: var(--text-color); padding-left: 8px; border-left: 2px solid #2e86c188; margin-left: 4px;\">\"The probability of being in state s_j at t+1, given the entire past history, depends only on the current state s_i.\"</div>\n            </div>\n            <div style=\"margin-top: 10px;\">\n                <div style=\"font-weight: 700; color: #8e44ad; font-size: 0.85rem; margin-bottom: 4px; display:flex; align-items:center; gap:6px;\">\n                    <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#8e44ad\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M19 5h-2V3H7v2H5c-1.1 0-2 .9-2 2v1c0 2.55 1.92 4.63 4.39 4.94.63 1.5 1.98 2.63 3.61 2.96V19H7v2h10v-2h-4v-3.1c1.63-.33 2.98-1.46 3.61-2.96C19.08 12.63 21 10.55 21 8V7c0-1.1-.9-2-2-2z\"/></svg> In the defense (before master's and doctoral faculty):\n                </div>\n                <div style=\"font-size: 0.9rem; line-height: 1.6; color: var(--text-color); padding-left: 8px; border-left: 2px solid #8e44ad88; margin-left: 4px;\">\"The proof proceeds in three steps: first, &alpha;<sub>t</sub> depends functionally on exactly W+1 values (bounded dependence). Second, under stationary AR(1), the block vector z<sub>t</sub> is Markovian. Third, since &pi; is deterministic, the Markov property carries over to the discrete process.\"</div>\n            </div>\n        </div>\n                        \n            </div>\n        </div>"},"s1i2":{"title":"5.3 — &phi;-Mixing and Ergodic Convergence","content":"\n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(0,100,60,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #27ae60, #1e8449);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M5 9.2h3V19H5V9.2zM10.6 5h2.8v14h-2.8V5zm5.6 8H19v6h-2.8v-6z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Asymptotic Properties</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n        <div style=\"\n            background: #1a527608;\n            border-left: 4px solid #1a5276;\n            border-radius: 0 12px 12px 0;\n            padding: 16px 18px;\n            margin: 14px 0;\n        \">\n            <div style=\"font-size: 1.05rem; font-weight: 600; text-align: center; margin-bottom: 10px; padding: 12px; background: rgba(0,0,0,0.03); border-radius: 8px; font-family: 'Courier New', Consolas, monospace; color: var(--text-color);\">\n                &phi;(n) &le; C<sub>&phi;</sub> &middot; &rho;<sup>n</sup> &nbsp;&nbsp; &forall; n &ge; 1\n            </div>\n            <div style=\"margin-top: 10px;\">\n                <div style=\"font-weight: 700; color: #2e86c1; font-size: 0.85rem; margin-bottom: 4px; display:flex; align-items:center; gap:6px;\">\n                    <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#2e86c1\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M18 2H6c-1.1 0-2 .9-2 2v16c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2zM6 4h5v8l-2.5-1.5L6 12V4z\"/></svg> How to read it (without reading it literally):\n                </div>\n                <div style=\"font-size: 0.9rem; line-height: 1.6; color: var(--text-color); padding-left: 8px; border-left: 2px solid #2e86c188; margin-left: 4px;\">\"The mixing coefficient phi decays exponentially with the number of steps n, at a rate rho less than 1.\"</div>\n            </div>\n            <div style=\"margin-top: 10px;\">\n                <div style=\"font-weight: 700; color: #8e44ad; font-size: 0.85rem; margin-bottom: 4px; display:flex; align-items:center; gap:6px;\">\n                    <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#8e44ad\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M19 5h-2V3H7v2H5c-1.1 0-2 .9-2 2v1c0 2.55 1.92 4.63 4.39 4.94.63 1.5 1.98 2.63 3.61 2.96V19H7v2h10v-2h-4v-3.1c1.63-.33 2.98-1.46 3.61-2.96C19.08 12.63 21 10.55 21 8V7c0-1.1-.9-2-2-2z\"/></svg> In the defense (before master's and doctoral faculty):\n                </div>\n                <div style=\"font-size: 0.9rem; line-height: 1.6; color: var(--text-color); padding-left: 8px; border-left: 2px solid #8e44ad88; margin-left: 4px;\">\"The &phi;-mixing property guarantees that the chain 'forgets' its past at a geometric rate. It is crucial for the validity of the asymptotic estimators. The spectral gap &gamma; = 1 &minus; |&lambda;₂| quantifies the speed.\"</div>\n            </div>\n        </div>\n                        \n        <div style=\"\n            background: #00664408;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #006644; font-size: 0.92rem;\">\n                Asymptotic Normality of P&#x0302;\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">\n                            Each entry of the estimated transition matrix is asymptotically normal:<br>\n                            <code style=\"font-family:'Courier New',Consolas,monospace;background:rgba(0,0,0,0.04);padding:1px 5px;border-radius:4px;font-size:0.95em;\">√T (&hat;P<sub>ij</sub> &minus; P<sub>ij</sub>) &xrarr; N(0, P<sub>ij</sub>(1&minus;P<sub>ij</sub>)/&pi;<sub>j</sub>)</code><br>\n                            This makes it possible to build confidence intervals for the transition probabilities.\n                        </div>\n        </div>\n                        \n            </div>\n        </div>"},"s1i3":{"title":"5.4 — Prediction Error Bound","content":"\n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(0,100,60,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #c0392b, #922b21);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M3 13h8V3H3v10zm0 8h8v-6H3v6zm10 0h8V11h-8v10zm0-18v6h8V3h-8z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Mean Squared Error</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n        <div style=\"\n            background: #1a527608;\n            border-left: 4px solid #1a5276;\n            border-radius: 0 12px 12px 0;\n            padding: 16px 18px;\n            margin: 14px 0;\n        \">\n            <div style=\"font-size: 1.05rem; font-weight: 600; text-align: center; margin-bottom: 10px; padding: 12px; background: rgba(0,0,0,0.03); border-radius: 8px; font-family: 'Courier New', Consolas, monospace; color: var(--text-color);\">\n                MSE(v&#x0302;<sub>T+1</sub>) = &sigma;&sup2;<sub>&epsilon;</sub> + C(&lambda;,W) / W<sub>eff</sub> + o(W<sub>eff</sub><sup>&minus;1</sup>)\n            </div>\n            <div style=\"margin-top: 10px;\">\n                <div style=\"font-weight: 700; color: #2e86c1; font-size: 0.85rem; margin-bottom: 4px; display:flex; align-items:center; gap:6px;\">\n                    <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#2e86c1\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M18 2H6c-1.1 0-2 .9-2 2v16c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2zM6 4h5v8l-2.5-1.5L6 12V4z\"/></svg> How to read it (without reading it literally):\n                </div>\n                <div style=\"font-size: 0.9rem; line-height: 1.6; color: var(--text-color); padding-left: 8px; border-left: 2px solid #2e86c188; margin-left: 4px;\">\"The mean squared prediction error decomposes into the irreducible noise variance plus a term that decreases inversely with the effective sample size.\"</div>\n            </div>\n            <div style=\"margin-top: 10px;\">\n                <div style=\"font-weight: 700; color: #8e44ad; font-size: 0.85rem; margin-bottom: 4px; display:flex; align-items:center; gap:6px;\">\n                    <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#8e44ad\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M19 5h-2V3H7v2H5c-1.1 0-2 .9-2 2v1c0 2.55 1.92 4.63 4.39 4.94.63 1.5 1.98 2.63 3.61 2.96V19H7v2h10v-2h-4v-3.1c1.63-.33 2.98-1.46 3.61-2.96C19.08 12.63 21 10.55 21 8V7c0-1.1-.9-2-2-2z\"/></svg> In the defense (before master's and doctoral faculty):\n                </div>\n                <div style=\"font-size: 0.9rem; line-height: 1.6; color: var(--text-color); padding-left: 8px; border-left: 2px solid #8e44ad88; margin-left: 4px;\">\"This decomposition reveals the fundamental trade-off: &sigma;&sup2;<sub>&epsilon;</sub> is irreducible (inherent noise), while the second term is the estimation error, which decreases with W<sub>eff</sub>. The effective size W<sub>eff</sub> = (1&minus;&lambda;<sup>W</sup>)/(1&minus;&lambda;) generalizes the notion of sample size when there are exponential weights.\"</div>\n            </div>\n        </div>\n                        \n            </div>\n        </div>"},"s2":{"sectionTitle":"6. Hybrid TCROC-Markov Model with NNLS"},"s2i0":{"title":"6.1 — NNLS Optimization Problem","content":"\n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(0,100,60,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #d35400, #e67e22);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M5 3h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2zm4.5 5L7 11l2.5 3H11l-2-2.5L11 9H9.5zm5 0H13l2 2.5L13 13h1.5L17 10l-2.5-3z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Estimating the Transition Matrix</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                <p>The heart of the estimation: find a P&#x0302; that is stochastic by construction.</p>\n                        \n        <div style=\"\n            background: #1a527608;\n            border-left: 4px solid #1a5276;\n            border-radius: 0 12px 12px 0;\n            padding: 16px 18px;\n            margin: 14px 0;\n        \">\n            <div style=\"font-size: 1.05rem; font-weight: 600; text-align: center; margin-bottom: 10px; padding: 12px; background: rgba(0,0,0,0.03); border-radius: 8px; font-family: 'Courier New', Consolas, monospace; color: var(--text-color);\">\n                P&#x0302; = argmin<sub>P&ge;0</sub> &Vert;X₁ &minus; P X₀&Vert;<sub>F</sub>&sup2; &nbsp;&nbsp; s.t. &nbsp;&nbsp; <b>1</b><sup>T</sup> P = <b>1</b><sup>T</sup>\n            </div>\n            <div style=\"margin-top: 10px;\">\n                <div style=\"font-weight: 700; color: #2e86c1; font-size: 0.85rem; margin-bottom: 4px; display:flex; align-items:center; gap:6px;\">\n                    <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#2e86c1\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M18 2H6c-1.1 0-2 .9-2 2v16c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2zM6 4h5v8l-2.5-1.5L6 12V4z\"/></svg> How to read it (without reading it literally):\n                </div>\n                <div style=\"font-size: 0.9rem; line-height: 1.6; color: var(--text-color); padding-left: 8px; border-left: 2px solid #2e86c188; margin-left: 4px;\">\"P hat is the matrix that minimizes the squared Frobenius norm of the error between the next states X₁ and the prediction PX₀, subject to all entries being nonnegative and each column summing to one.\"</div>\n            </div>\n            <div style=\"margin-top: 10px;\">\n                <div style=\"font-weight: 700; color: #8e44ad; font-size: 0.85rem; margin-bottom: 4px; display:flex; align-items:center; gap:6px;\">\n                    <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#8e44ad\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M19 5h-2V3H7v2H5c-1.1 0-2 .9-2 2v1c0 2.55 1.92 4.63 4.39 4.94.63 1.5 1.98 2.63 3.61 2.96V19H7v2h10v-2h-4v-3.1c1.63-.33 2.98-1.46 3.61-2.96C19.08 12.63 21 10.55 21 8V7c0-1.1-.9-2-2-2z\"/></svg> In the defense (before master's and doctoral faculty):\n                </div>\n                <div style=\"font-size: 0.9rem; line-height: 1.6; color: var(--text-color); padding-left: 8px; border-left: 2px solid #8e44ad88; margin-left: 4px;\">\"The key advantage of NNLS over OLS is that it GUARANTEES a valid stochastic matrix by construction: nonnegative entries and columns that sum to one. Unconstrained OLS can produce negative probabilities.\"</div>\n            </div>\n        </div>\n                        \n        <div style=\"\n            background: #00664408;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #006644; font-size: 0.92rem;\">\n                Vectorization via Kronecker\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">\n                            The key algebraic trick: transform the matrix problem into a vector problem:<br>\n                            \n        <span style=\"\n            display: inline-block;\n            background: #d3540018;\n            color: #d35400;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #d3540030;\n            margin: 2px 3px;\n        \">vec(X₁) = (X₀ᵀ ⊗ Iₙ) vec(P&#x0302;)</span><br>\n                            Using the identity vec(ABC) = (C<sup>T</sup> ⊗ A) vec(B), this makes it possible to apply the standard NNLS solver (Lawson & Hanson, 1995).\n                        </div>\n        </div>\n                        \n            </div>\n        </div>"},"s2i1":{"title":"6.2 — SRep Algorithm","content":"\n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(0,100,60,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #2c3e50, #34495e);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M22.7 19l-9.1-9.1c.9-2.3.4-5-1.5-6.9-2-2-5-2.4-7.4-1.3L9 6 6 9 1.6 4.7C.4 7.1.9 10.1 2.9 12.1c1.9 1.9 4.6 2.4 6.9 1.5l9.1 9.1c.4.4 1 .4 1.4 0l2.3-2.3c.5-.4.5-1.1.1-1.4z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Constructive Implementation</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                <p>The SRep Algorithm formalizes the estimation of P&#x0302; step by step.</p>\n                        \n        <div style=\"\n            background: #1a527608;\n            border-left: 4px solid #1a5276;\n            border-radius: 0 12px 12px 0;\n            padding: 16px 18px;\n            margin: 14px 0;\n        \">\n            <div style=\"font-size: 1.05rem; font-weight: 600; text-align: center; margin-bottom: 10px; padding: 12px; background: rgba(0,0,0,0.03); border-radius: 8px; font-family: 'Courier New', Consolas, monospace; color: var(--text-color);\">\n                c&#x0302; = argmin<sub>c&ge;0</sub> &Vert; [A; wC] c &minus; [b; w<b>1</b><sub>N</sub>] &Vert;&sup2;\n            </div>\n            <div style=\"margin-top: 10px;\">\n                <div style=\"font-weight: 700; color: #2e86c1; font-size: 0.85rem; margin-bottom: 4px; display:flex; align-items:center; gap:6px;\">\n                    <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#2e86c1\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M18 2H6c-1.1 0-2 .9-2 2v16c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2zM6 4h5v8l-2.5-1.5L6 12V4z\"/></svg> How to read it (without reading it literally):\n                </div>\n                <div style=\"font-size: 0.9rem; line-height: 1.6; color: var(--text-color); padding-left: 8px; border-left: 2px solid #2e86c188; margin-left: 4px;\">\"c hat minimizes the norm of the augmented system, where the first part captures the fit to the data and the second (weighted by a large w) forces the columns to sum to one.\"</div>\n            </div>\n            <div style=\"margin-top: 10px;\">\n                <div style=\"font-weight: 700; color: #8e44ad; font-size: 0.85rem; margin-bottom: 4px; display:flex; align-items:center; gap:6px;\">\n                    <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#8e44ad\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M19 5h-2V3H7v2H5c-1.1 0-2 .9-2 2v1c0 2.55 1.92 4.63 4.39 4.94.63 1.5 1.98 2.63 3.61 2.96V19H7v2h10v-2h-4v-3.1c1.63-.33 2.98-1.46 3.61-2.96C19.08 12.63 21 10.55 21 8V7c0-1.1-.9-2-2-2z\"/></svg> In the defense (before master's and doctoral faculty):\n                </div>\n                <div style=\"font-size: 0.9rem; line-height: 1.6; color: var(--text-color); padding-left: 8px; border-left: 2px solid #8e44ad88; margin-left: 4px;\">\"The weight w acts as a soft Lagrange multiplier: a very large w (typically 10⁶) makes violating the unit-sum constraint extremely costly, which enforces stochasticity.\"</div>\n            </div>\n        </div>\n                        <div style=\"overflow-x:auto; margin:10px 0;\"><table style=\"width:100%;border-collapse:collapse;font-size:0.88rem;\"><thead><tr><th style=\"background:#00664415;color:#006644;padding:8px 10px;text-align:left;border-bottom:2px solid #00664430;font-weight:700;\">Step</th><th style=\"background:#00664415;color:#006644;padding:8px 10px;text-align:left;border-bottom:2px solid #00664430;font-weight:700;\">Description</th></tr></thead><tbody><tr><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">1</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">Encode states as one-hot: s₁ → [1,0,0,0]ᵀ</td></tr><tr><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">2</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">Build X₀ (current states) and X₁ (next states)</td></tr><tr><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">3</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">Form A = X₀ᵀ ⊗ Iₙ (Kronecker)</td></tr><tr><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">4</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">Build the augmented system with the constraint w·C</td></tr><tr><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">5</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">Solve NNLS: min&Vert;A&#x0303;c &minus; b&#x0303;&Vert;&sup2; with c &ge; 0</td></tr><tr><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">6</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">Reconstruct P&#x0302; = vec⁻¹(c&#x0302;) and normalize the columns</td></tr></tbody></table></div>\n                        \n            </div>\n        </div>"},"s2i2":{"title":"6.3 — Validation: Honduras GDP","content":"\n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(0,100,60,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #27ae60, #1e8449);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M5 9.2h3V19H5V9.2zM10.6 5h2.8v14h-2.8V5zm5.6 8H19v6h-2.8v-6z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Real Numerical Example</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                <p>Application to GDP per capita in Lempiras (2000-2023), 22 observed transitions.</p>\n                        \n        <div style=\"\n            background: #00664408;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #006644; font-size: 0.92rem;\">\n                Estimated Transition Matrix\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">\n                            <div style=\"font-family:'Courier New',Consolas,monospace; text-align:center; padding:8px;\">\n                            P&#x0302; =<br>\n                            | 0.50 &nbsp; 0.11 &nbsp; 0.14 &nbsp; 0.00 |<br>\n                            | 0.25 &nbsp; 0.67 &nbsp; 0.14 &nbsp; 0.00 |<br>\n                            | 0.00 &nbsp; 0.22 &nbsp; 0.71 &nbsp; 1.00 |<br>\n                            | 0.25 &nbsp; 0.00 &nbsp; 0.00 &nbsp; 0.00 |\n                            </div>\n                            Reading by columns: from s₁ (contraction), there is 50% persistence, 25% chance of moving to stability, and 25% of a strong rebound.\n                        </div>\n        </div>\n                        \n        <div style=\"\n            background: #00664408;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #006644; font-size: 0.92rem;\">\n                Key finding: State s₄ is transient\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">\n                            Strong growth (s₄) occurred <b>only once</b> (2022, post-COVID rebound).\n                            Column 4 shows P(s₃|s₄) = 100%: it always moderates quickly.\n                            This transient anomaly does not represent sustainable structural dynamics.\n                        </div>\n        </div>\n                        \n            </div>\n        </div>"},"s3":{"sectionTitle":"7. Detection and Forecasting of Fuel Regimes"},"s3i0":{"title":"7.1 — Model Degeneration Phenomenon","content":"\n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(0,100,60,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #c0392b, #922b21);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M7 2v11h3v9l7-12h-4l4-8z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Critical Discovery</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                <p><b>Theorem (Degeneration due to over-smoothing):</b> When W = T, the operator is constant.</p>\n                        \n        <div style=\"\n            background: #1a527608;\n            border-left: 4px solid #1a5276;\n            border-radius: 0 12px 12px 0;\n            padding: 16px 18px;\n            margin: 14px 0;\n        \">\n            <div style=\"font-size: 1.05rem; font-weight: 600; text-align: center; margin-bottom: 10px; padding: 12px; background: rgba(0,0,0,0.03); border-radius: 8px; font-family: 'Courier New', Consolas, monospace; color: var(--text-color);\">\n                W = T &rArr; &alpha;<sub>t</sub>(T) = &alpha;&#x0304; &forall; t &rArr; Var(&alpha;<sub>t</sub>) = 0 &rArr; K<sub>eff</sub> = 1\n            </div>\n            <div style=\"margin-top: 10px;\">\n                <div style=\"font-weight: 700; color: #2e86c1; font-size: 0.85rem; margin-bottom: 4px; display:flex; align-items:center; gap:6px;\">\n                    <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#2e86c1\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M18 2H6c-1.1 0-2 .9-2 2v16c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2zM6 4h5v8l-2.5-1.5L6 12V4z\"/></svg> How to read it (without reading it literally):\n                </div>\n                <div style=\"font-size: 0.9rem; line-height: 1.6; color: var(--text-color); padding-left: 8px; border-left: 2px solid #2e86c188; margin-left: 4px;\">\"If the window W equals the length T of the series, alpha is identical at all times, its variance is zero, K-Means assigns everything to a single cluster, and the transition matrix degenerates into the identity.\"</div>\n            </div>\n            <div style=\"margin-top: 10px;\">\n                <div style=\"font-weight: 700; color: #8e44ad; font-size: 0.85rem; margin-bottom: 4px; display:flex; align-items:center; gap:6px;\">\n                    <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#8e44ad\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M19 5h-2V3H7v2H5c-1.1 0-2 .9-2 2v1c0 2.55 1.92 4.63 4.39 4.94.63 1.5 1.98 2.63 3.61 2.96V19H7v2h10v-2h-4v-3.1c1.63-.33 2.98-1.46 3.61-2.96C19.08 12.63 21 10.55 21 8V7c0-1.1-.9-2-2-2z\"/></svg> In the defense (before master's and doctoral faculty):\n                </div>\n                <div style=\"font-size: 0.9rem; line-height: 1.6; color: var(--text-color); padding-left: 8px; border-left: 2px solid #8e44ad88; margin-left: 4px;\">\"This is an original finding of the thesis. It explains why an unrestricted hyperparameter search produces artificially good metrics but useless models. The constraint W &le; 52 weeks (one annual cycle) prevents degeneration and has an economic justification.\"</div>\n            </div>\n        </div>\n                        \n            </div>\n        </div>"},"s3i1":{"title":"7.2 — Optimal Hyperparameters","content":"\n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(0,100,60,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #2e86c1, #1a5276);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M3 13h8V3H3v10zm0 8h8v-6H3v6zm10 0h8V11h-8v10zm0-18v6h8V3h-8z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Optimization Results</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                <div style=\"overflow-x:auto; margin:10px 0;\"><table style=\"width:100%;border-collapse:collapse;font-size:0.88rem;\"><thead><tr><th style=\"background:#00664415;color:#006644;padding:8px 10px;text-align:left;border-bottom:2px solid #00664430;font-weight:700;\">Series</th><th style=\"background:#00664415;color:#006644;padding:8px 10px;text-align:left;border-bottom:2px solid #00664430;font-weight:700;\">W*</th><th style=\"background:#00664415;color:#006644;padding:8px 10px;text-align:left;border-bottom:2px solid #00664430;font-weight:700;\">&lambda;*</th><th style=\"background:#00664415;color:#006644;padding:8px 10px;text-align:left;border-bottom:2px solid #00664430;font-weight:700;\">K*</th><th style=\"background:#00664415;color:#006644;padding:8px 10px;text-align:left;border-bottom:2px solid #00664430;font-weight:700;\">Accuracy</th><th style=\"background:#00664415;color:#006644;padding:8px 10px;text-align:left;border-bottom:2px solid #00664430;font-weight:700;\">RMSE</th></tr></thead><tbody><tr><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">Regular</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">50</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">0.99</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">3</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\"><b>85.10%</b></td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">0.8394</td></tr><tr><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">Super</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">52</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">0.99</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">4</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">62.78%</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">0.9769</td></tr><tr><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">Diesel</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">50</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">0.97</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">3</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">71.56%</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">1.0816</td></tr><tr><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">Kerosene</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">52</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">0.98</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">5</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">68.20%</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">1.1714</td></tr></tbody></table></div>\n        <div style=\"\n            background: #00664408;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #006644; font-size: 0.92rem;\">\n                Interpretation\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">\n                            \n        <span style=\"\n            display: inline-block;\n            background: #1a527618;\n            color: #1a5276;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #1a527630;\n            margin: 2px 3px;\n        \">W &asymp; 50-52</span>: Long windows (~1 year) capture long-term trends.<br>\n                            \n        <span style=\"\n            display: inline-block;\n            background: #27ae6018;\n            color: #27ae60;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #27ae6030;\n            margin: 2px 3px;\n        \">&lambda; &asymp; 0.97-0.99</span>: Close to uniform weights within the window.<br>\n                            \n        <span style=\"\n            display: inline-block;\n            background: #c0392b18;\n            color: #c0392b;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #c0392b30;\n            margin: 2px 3px;\n        \">K ranges from 3 to 5</span>: Complexity hierarchy &rarr; Regular (simple) vs. Kerosene (complex).\n                        </div>\n        </div>\n            </div>\n        </div>"},"s3i2":{"title":"7.3 — Spectral Properties","content":"\n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(0,100,60,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #8e44ad, #6c3483);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M12 4.5C7 4.5 2.73 7.61 1 12c1.73 4.39 6 7.5 11 7.5s9.27-3.11 11-7.5c-1.73-4.39-6-7.5-11-7.5zM12 17c-2.76 0-5-2.24-5-5s2.24-5 5-5 5 2.24 5 5-2.24 5-5 5z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Spectral Analysis</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n        <div style=\"\n            background: #1a527608;\n            border-left: 4px solid #1a5276;\n            border-radius: 0 12px 12px 0;\n            padding: 16px 18px;\n            margin: 14px 0;\n        \">\n            <div style=\"font-size: 1.05rem; font-weight: 600; text-align: center; margin-bottom: 10px; padding: 12px; background: rgba(0,0,0,0.03); border-radius: 8px; font-family: 'Courier New', Consolas, monospace; color: var(--text-color);\">\n                t<sub>mix</sub>(&epsilon;) = ⌈ ln(1/&epsilon;) / &gamma; ⌉\n            </div>\n            <div style=\"margin-top: 10px;\">\n                <div style=\"font-weight: 700; color: #2e86c1; font-size: 0.85rem; margin-bottom: 4px; display:flex; align-items:center; gap:6px;\">\n                    <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#2e86c1\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M18 2H6c-1.1 0-2 .9-2 2v16c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2zM6 4h5v8l-2.5-1.5L6 12V4z\"/></svg> How to read it (without reading it literally):\n                </div>\n                <div style=\"font-size: 0.9rem; line-height: 1.6; color: var(--text-color); padding-left: 8px; border-left: 2px solid #2e86c188; margin-left: 4px;\">\"The mixing time is the ceiling of the logarithm of one over epsilon, divided by the spectral gap gamma.\"</div>\n            </div>\n            <div style=\"margin-top: 10px;\">\n                <div style=\"font-weight: 700; color: #8e44ad; font-size: 0.85rem; margin-bottom: 4px; display:flex; align-items:center; gap:6px;\">\n                    <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#8e44ad\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M19 5h-2V3H7v2H5c-1.1 0-2 .9-2 2v1c0 2.55 1.92 4.63 4.39 4.94.63 1.5 1.98 2.63 3.61 2.96V19H7v2h10v-2h-4v-3.1c1.63-.33 2.98-1.46 3.61-2.96C19.08 12.63 21 10.55 21 8V7c0-1.1-.9-2-2-2z\"/></svg> In the defense (before master's and doctoral faculty):\n                </div>\n                <div style=\"font-size: 0.9rem; line-height: 1.6; color: var(--text-color); padding-left: 8px; border-left: 2px solid #8e44ad88; margin-left: 4px;\">\"The spectral gap &gamma; = 1 &minus; |&lambda;₂| measures how quickly the chain forgets its initial state. A small gap means high market inertia. Kerosene has &gamma; = 0.021 (the smallest), with a mixing time of ~47 weeks.\"</div>\n            </div>\n        </div>\n                        <div style=\"overflow-x:auto; margin:10px 0;\"><table style=\"width:100%;border-collapse:collapse;font-size:0.88rem;\"><thead><tr><th style=\"background:#00664415;color:#006644;padding:8px 10px;text-align:left;border-bottom:2px solid #00664430;font-weight:700;\">Metric</th><th style=\"background:#00664415;color:#006644;padding:8px 10px;text-align:left;border-bottom:2px solid #00664430;font-weight:700;\">Regular</th><th style=\"background:#00664415;color:#006644;padding:8px 10px;text-align:left;border-bottom:2px solid #00664430;font-weight:700;\">Diesel</th><th style=\"background:#00664415;color:#006644;padding:8px 10px;text-align:left;border-bottom:2px solid #00664430;font-weight:700;\">Super</th><th style=\"background:#00664415;color:#006644;padding:8px 10px;text-align:left;border-bottom:2px solid #00664430;font-weight:700;\">Kerosene</th></tr></thead><tbody><tr><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">|&lambda;₂|</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">0.963</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">0.960</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">0.961</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\"><b>0.979</b></td></tr><tr><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">Gap &gamma;</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">0.037</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">0.040</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">0.039</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\"><b>0.021</b></td></tr><tr><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">t<sub>mix</sub> (wk)</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">~27</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">~25</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\">~26</td><td style=\"padding:7px 10px;border-bottom:1px solid #eee;\"><b>~47</b></td></tr></tbody></table></div>\n                        \n            </div>\n        </div>"},"s3i3":{"title":"7.4 — Superiority over Alternatives","content":"\n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(0,100,60,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #d4ac0d, #b7950b);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Comparative Benchmark</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                <p>TCROC-Markov (K-Means) statistically outperforms fixed quantiles and classical MS-AR.</p>\n                        \n        <div style=\"\n            background: #00664408;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #006644; font-size: 0.92rem;\">\n                Key results\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">\n                            \n        <span style=\"\n            display: inline-block;\n            background: #27ae6018;\n            color: #27ae60;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #27ae6030;\n            margin: 2px 3px;\n        \">Regular: 85.1% accuracy</span> — The most predictable series (K=3, simple structure).<br>\n                            \n        <span style=\"\n            display: inline-block;\n            background: #c0392b18;\n            color: #c0392b;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #c0392b30;\n            margin: 2px 3px;\n        \">Kerosene: 68.2%</span> — The hardest (K=5, greater structural complexity).<br>\n                            \n        <span style=\"\n            display: inline-block;\n            background: #8e44ad18;\n            color: #8e44ad;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #8e44ad30;\n            margin: 2px 3px;\n        \">Superior to MS-AR</span> — MS-AR failed on 3 of 4 series due to numerical instability.<br>\n                            Diebold-Mariano tests with Holm-Bonferroni correction confirm statistical significance (p &lt; 0.05).\n                        </div>\n        </div>\n                        \n            </div>\n        </div>"},"s4":{"sectionTitle":"8. Nonlinear Extension — Reservoir Computing (SSRC)"},"s4i0":{"title":"8.1 — Echo State Network (ESN) Equation","content":"\n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(0,100,60,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #1a5276, #2e86c1);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M17 16l-4-4V8.82C14.16 8.4 15 7.3 15 6c0-1.66-1.34-3-3-3S9 4.34 9 6c0 1.3.84 2.4 2 2.82V12l-4 4H2v5h5v-3.05l4-4.2 4 4.2V21h5v-5h-3z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Reservoir State Map</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n        <div style=\"\n            background: #1a527608;\n            border-left: 4px solid #1a5276;\n            border-radius: 0 12px 12px 0;\n            padding: 16px 18px;\n            margin: 14px 0;\n        \">\n            <div style=\"font-size: 1.05rem; font-weight: 600; text-align: center; margin-bottom: 10px; padding: 12px; background: rgba(0,0,0,0.03); border-radius: 8px; font-family: 'Courier New', Consolas, monospace; color: var(--text-color);\">\n                <b>h</b><sub>t</sub> = &sigma;(<b>W</b><sub>in</sub> <b>u</b><sub>t</sub> + <b>W</b><sub>res</sub> <b>h</b><sub>t&minus;1</sub>)\n            </div>\n            <div style=\"margin-top: 10px;\">\n                <div style=\"font-weight: 700; color: #2e86c1; font-size: 0.85rem; margin-bottom: 4px; display:flex; align-items:center; gap:6px;\">\n                    <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#2e86c1\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M18 2H6c-1.1 0-2 .9-2 2v16c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2zM6 4h5v8l-2.5-1.5L6 12V4z\"/></svg> How to read it (without reading it literally):\n                </div>\n                <div style=\"font-size: 0.9rem; line-height: 1.6; color: var(--text-color); padding-left: 8px; border-left: 2px solid #2e86c188; margin-left: 4px;\">\"The state vector h at time t is obtained by applying the activation function sigma to the product of the input matrix and the signal u_t plus the product of the reservoir matrix and the previous state.\"</div>\n            </div>\n            <div style=\"margin-top: 10px;\">\n                <div style=\"font-weight: 700; color: #8e44ad; font-size: 0.85rem; margin-bottom: 4px; display:flex; align-items:center; gap:6px;\">\n                    <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#8e44ad\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M19 5h-2V3H7v2H5c-1.1 0-2 .9-2 2v1c0 2.55 1.92 4.63 4.39 4.94.63 1.5 1.98 2.63 3.61 2.96V19H7v2h10v-2h-4v-3.1c1.63-.33 2.98-1.46 3.61-2.96C19.08 12.63 21 10.55 21 8V7c0-1.1-.9-2-2-2z\"/></svg> In the defense (before master's and doctoral faculty):\n                </div>\n                <div style=\"font-size: 0.9rem; line-height: 1.6; color: var(--text-color); padding-left: 8px; border-left: 2px solid #8e44ad88; margin-left: 4px;\">\"The reservoir is a recurrent neural network whose internal matrices (W<sub>in</sub> and W<sub>res</sub>) are generated randomly and are NOT trained. Only the readout layer W<sub>out</sub> is estimated. This avoids backpropagation through time (BPTT).\"</div>\n            </div>\n        </div>\n                        \n            </div>\n        </div>"},"s4i1":{"title":"8.2 — Leaky-ESN Variant","content":"\n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(0,100,60,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #27ae60, #1e8449);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M11.99 18.54l-7.37-5.73L3 14.07l9 7 9-7-1.63-1.27zM12 16l7.36-5.73L21 9l-9-7-9 7 1.63 1.27L12 16z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Leaky Integration</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n        <div style=\"\n            background: #1a527608;\n            border-left: 4px solid #1a5276;\n            border-radius: 0 12px 12px 0;\n            padding: 16px 18px;\n            margin: 14px 0;\n        \">\n            <div style=\"font-size: 1.05rem; font-weight: 600; text-align: center; margin-bottom: 10px; padding: 12px; background: rgba(0,0,0,0.03); border-radius: 8px; font-family: 'Courier New', Consolas, monospace; color: var(--text-color);\">\n                <b>h</b><sub>t</sub> = (1&minus;a) <b>h</b><sub>t&minus;1</sub> + a &middot; &sigma;(<b>W</b><sub>in</sub> <b>u</b><sub>t</sub> + <b>W</b><sub>res</sub> <b>h</b><sub>t&minus;1</sub>)\n            </div>\n            <div style=\"margin-top: 10px;\">\n                <div style=\"font-weight: 700; color: #2e86c1; font-size: 0.85rem; margin-bottom: 4px; display:flex; align-items:center; gap:6px;\">\n                    <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#2e86c1\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M18 2H6c-1.1 0-2 .9-2 2v16c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2zM6 4h5v8l-2.5-1.5L6 12V4z\"/></svg> How to read it (without reading it literally):\n                </div>\n                <div style=\"font-size: 0.9rem; line-height: 1.6; color: var(--text-color); padding-left: 8px; border-left: 2px solid #2e86c188; margin-left: 4px;\">\"The state h_t is a convex mixture of the previous state (with weight 1-a) and the nonlinear activation of the new input (with weight a). The factor a controls the time scale.\"</div>\n            </div>\n            <div style=\"margin-top: 10px;\">\n                <div style=\"font-weight: 700; color: #8e44ad; font-size: 0.85rem; margin-bottom: 4px; display:flex; align-items:center; gap:6px;\">\n                    <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#8e44ad\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M19 5h-2V3H7v2H5c-1.1 0-2 .9-2 2v1c0 2.55 1.92 4.63 4.39 4.94.63 1.5 1.98 2.63 3.61 2.96V19H7v2h10v-2h-4v-3.1c1.63-.33 2.98-1.46 3.61-2.96C19.08 12.63 21 10.55 21 8V7c0-1.1-.9-2-2-2z\"/></svg> In the defense (before master's and doctoral faculty):\n                </div>\n                <div style=\"font-size: 0.9rem; line-height: 1.6; color: var(--text-color); padding-left: 8px; border-left: 2px solid #8e44ad88; margin-left: 4px;\">\"For markets with high persistence (such as regulated fuels in Honduras), values a &Lt; 1 emphasize long-term trends. Interpret it as an Euler discretization with time constant &tau; = 1/a: if a = 0.1, the effective memory is ~10 weeks.\"</div>\n            </div>\n        </div>\n                        \n            </div>\n        </div>"},"s4i2":{"title":"8.3 — Echo State Property (ESP)","content":"\n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(0,100,60,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #c0392b, #922b21);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M12 1L3 5v6c0 5.55 3.84 10.74 9 12 5.16-1.26 9-6.45 9-12V5l-9-4z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Stability Condition</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                <p><b>Theorem:</b> If &rho;(<b>W</b><sub>res</sub>) &lt; 1, the reservoir has the ESP.</p>\n                        \n        <div style=\"\n            background: #1a527608;\n            border-left: 4px solid #1a5276;\n            border-radius: 0 12px 12px 0;\n            padding: 16px 18px;\n            margin: 14px 0;\n        \">\n            <div style=\"font-size: 1.05rem; font-weight: 600; text-align: center; margin-bottom: 10px; padding: 12px; background: rgba(0,0,0,0.03); border-radius: 8px; font-family: 'Courier New', Consolas, monospace; color: var(--text-color);\">\n                &rho;(<b>W</b><sub>res</sub>) &lt; 1 &rArr; &Vert;<b>h</b><sub>t</sub> &minus; <b>h</b>'<sub>t</sub>&Vert; &le; &Vert;<b>W</b><sub>res</sub>&Vert;<sup>t</sup> &Vert;<b>h</b>₀ &minus; <b>h</b>'₀&Vert; &rarr; 0\n            </div>\n            <div style=\"margin-top: 10px;\">\n                <div style=\"font-weight: 700; color: #2e86c1; font-size: 0.85rem; margin-bottom: 4px; display:flex; align-items:center; gap:6px;\">\n                    <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#2e86c1\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M18 2H6c-1.1 0-2 .9-2 2v16c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2zM6 4h5v8l-2.5-1.5L6 12V4z\"/></svg> How to read it (without reading it literally):\n                </div>\n                <div style=\"font-size: 0.9rem; line-height: 1.6; color: var(--text-color); padding-left: 8px; border-left: 2px solid #2e86c188; margin-left: 4px;\">\"If the spectral radius of the reservoir matrix is less than one, the difference between two trajectories with different initial conditions decays exponentially to zero.\"</div>\n            </div>\n            <div style=\"margin-top: 10px;\">\n                <div style=\"font-weight: 700; color: #8e44ad; font-size: 0.85rem; margin-bottom: 4px; display:flex; align-items:center; gap:6px;\">\n                    <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#8e44ad\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M19 5h-2V3H7v2H5c-1.1 0-2 .9-2 2v1c0 2.55 1.92 4.63 4.39 4.94.63 1.5 1.98 2.63 3.61 2.96V19H7v2h10v-2h-4v-3.1c1.63-.33 2.98-1.46 3.61-2.96C19.08 12.63 21 10.55 21 8V7c0-1.1-.9-2-2-2z\"/></svg> In the defense (before master's and doctoral faculty):\n                </div>\n                <div style=\"font-size: 0.9rem; line-height: 1.6; color: var(--text-color); padding-left: 8px; border-left: 2px solid #8e44ad88; margin-left: 4px;\">\"The ESP guarantees that the output depends only on the input sequence, not on the initial condition. It is the fundamental requirement for the reservoir to work as a memory encoder.\"</div>\n            </div>\n        </div>\n                        \n            </div>\n        </div>"},"s4i3":{"title":"8.4 — Inclusion Theorem: TCROC-Markov ⊂ SSRC","content":"\n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(0,100,60,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #d4ac0d, #b7950b);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Central Result of the Chapter</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                <p><b>Theorem:</b> TCROC-Markov is a degenerate case of the SSRC.</p>\n                        \n        <div style=\"\n            background: #00664408;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #006644; font-size: 0.92rem;\">\n                Degeneration Conditions\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">\n                            \n        <span style=\"\n            display: inline-block;\n            background: #c0392b18;\n            color: #c0392b;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #c0392b30;\n            margin: 2px 3px;\n        \">W<sub>res</sub> = 0</span> — Zero reservoir matrix (no recurrence)<br>\n                            \n        <span style=\"\n            display: inline-block;\n            background: #2e86c118;\n            color: #2e86c1;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #2e86c130;\n            margin: 2px 3px;\n        \">&sigma; = id</span> — Identity activation (no nonlinearity)<br>\n                            \n        <span style=\"\n            display: inline-block;\n            background: #27ae6018;\n            color: #27ae60;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #27ae6030;\n            margin: 2px 3px;\n        \">a = 1</span> — No leaky integration<br>\n                            \n        <span style=\"\n            display: inline-block;\n            background: #8e44ad18;\n            color: #8e44ad;\n            font-weight: 600;\n            font-size: 0.82rem;\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid #8e44ad30;\n            margin: 2px 3px;\n        \">D = K</span> — Dimension equal to the number of states\n                        </div>\n        </div>\n                        \n        <div style=\"\n            background: #00664408;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #006644; font-size: 0.92rem;\">\n                Consequence\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">\n                            This establishes a <b>formal hierarchy of models</b>:<br>\n                            TCROC &sub; TCROC-Markov &sub; TCROC-SSRC<br>\n                            Each level adds expressive capacity. By the Universal Approximation Theorem (Grigoryeva & Ortega, 2018),\n                            the SSRC can approximate <b>any continuous causal functional on sequences</b>.\n                        </div>\n        </div>\n                        \n            </div>\n        </div>"},"s4i4":{"title":"8.5 — Forecast Stability Bound","content":"\n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(0,100,60,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #1a5276, #154360);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M12 1L3 5v6c0 5.55 3.84 10.74 9 12 5.16-1.26 9-6.45 9-12V5l-9-4z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Robustness to Perturbations</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n        <div style=\"\n            background: #1a527608;\n            border-left: 4px solid #1a5276;\n            border-radius: 0 12px 12px 0;\n            padding: 16px 18px;\n            margin: 14px 0;\n        \">\n            <div style=\"font-size: 1.05rem; font-weight: 600; text-align: center; margin-bottom: 10px; padding: 12px; background: rgba(0,0,0,0.03); border-radius: 8px; font-family: 'Courier New', Consolas, monospace; color: var(--text-color);\">\n                &Vert;&delta;y&#x0302;<sub>t+1</sub>&Vert; &le; &Vert;W&#x0302;<sub>out</sub>&Vert; &middot; &Vert;W<sub>in</sub>&Vert; &middot; &epsilon; / (1 &minus; &rho;<sub>res</sub>)\n            </div>\n            <div style=\"margin-top: 10px;\">\n                <div style=\"font-weight: 700; color: #2e86c1; font-size: 0.85rem; margin-bottom: 4px; display:flex; align-items:center; gap:6px;\">\n                    <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#2e86c1\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M18 2H6c-1.1 0-2 .9-2 2v16c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2zM6 4h5v8l-2.5-1.5L6 12V4z\"/></svg> How to read it (without reading it literally):\n                </div>\n                <div style=\"font-size: 0.9rem; line-height: 1.6; color: var(--text-color); padding-left: 8px; border-left: 2px solid #2e86c188; margin-left: 4px;\">\"The perturbation in the output is bounded by the norm of the readout matrix, multiplied by the norm of the input scaled by epsilon, divided by one minus the spectral radius.\"</div>\n            </div>\n            <div style=\"margin-top: 10px;\">\n                <div style=\"font-weight: 700; color: #8e44ad; font-size: 0.85rem; margin-bottom: 4px; display:flex; align-items:center; gap:6px;\">\n                    <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#8e44ad\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M19 5h-2V3H7v2H5c-1.1 0-2 .9-2 2v1c0 2.55 1.92 4.63 4.39 4.94.63 1.5 1.98 2.63 3.61 2.96V19H7v2h10v-2h-4v-3.1c1.63-.33 2.98-1.46 3.61-2.96C19.08 12.63 21 10.55 21 8V7c0-1.1-.9-2-2-2z\"/></svg> In the defense (before master's and doctoral faculty):\n                </div>\n                <div style=\"font-size: 0.9rem; line-height: 1.6; color: var(--text-color); padding-left: 8px; border-left: 2px solid #8e44ad88; margin-left: 4px;\">\"The denominator 1 &minus; &rho; acts as an amplifier: the closer &rho; is to 1, the greater the sensitivity. However, the NNLS constraint provides implicit regularization that the theoretical bound does not capture.\"</div>\n            </div>\n        </div>\n                        \n            </div>\n        </div>"},"s5":{"sectionTitle":"9. Strategic Summary for the Defense"},"s5i0":{"title":"The Thesis Narrative in 5 Minutes","content":"\n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(0,100,60,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #006644, #004d33);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M12 2a9 9 0 0 0-9 9c0 3.07 1.98 5.73 4.73 6.73A1 1 0 0 1 8.5 19H12v3h1v-3h3.5a1 1 0 0 1 .77-1.27A7 7 0 0 0 21 11a9 9 0 0 0-9-9z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Common Thread</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n        <div style=\"\n            background: #00664408;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #006644; font-size: 0.92rem;\">\n                1. The Problem\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">Economic time series (GDP, fuels) are non-stationary and noisy. Classical methods (MS-AR, ARIMA) require costly iterative optimization and strong distributional assumptions.</div>\n        </div>\n                        \n        <div style=\"\n            background: #1a527608;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #1a5276; font-size: 0.92rem;\">\n                2. The Solution (Ch. 4)\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">We define the TCROC family: an operator with a closed-form analytical solution that transforms the series into stationary rates of change. Four hierarchically related variants, all with proven properties.</div>\n        </div>\n                        \n        <div style=\"\n            background: #8e44ad08;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #8e44ad; font-size: 0.92rem;\">\n                3. The Integration (Chs. 5-6)\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">We integrate TCROC with Markov chains to model transitions between economic regimes. We use NNLS to estimate matrices that are stochastic by construction.</div>\n        </div>\n                        \n        <div style=\"\n            background: #27ae6008;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #27ae60; font-size: 0.92rem;\">\n                4. The Validation (Ch. 7)\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">We apply it to 4 Honduran fuel series (400+ observations). We discover the degeneration phenomenon (W&rarr;T) and resolve it. We statistically outperform MS-AR and quantiles. Regular: 85.1% accuracy.</div>\n        </div>\n                        \n        <div style=\"\n            background: #c0392b08;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #c0392b; font-size: 0.92rem;\">\n                5. The Extension (Ch. 8)\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">We generalize to the SSRC (nonlinear reservoir). We prove that TCROC-Markov is a degenerate special case. The SSRC is a universal approximator — strictly more powerful.</div>\n        </div>\n                        \n            </div>\n        </div>"},"s5i1":{"title":"Frequently Asked Defense Questions","content":"\n        <div style=\"\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n            margin-bottom: 1.5rem;\n            border: 1px solid rgba(0,100,60,0.12);\n            background: var(--bg-card, #fff);\n        \">\n            <div style=\"\n                background: linear-gradient(135deg, #c0392b, #922b21);\n                padding: 14px 20px;\n                display: flex;\n                align-items: center;\n                gap: 10px;\n            \">\n                <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"#fff\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M12 4.5C7 4.5 2.73 7.61 1 12c1.73 4.39 6 7.5 11 7.5s9.27-3.11 11-7.5c-1.73-4.39-6-7.5-11-7.5zM12 17c-2.76 0-5-2.24-5-5s2.24-5 5-5 5 2.24 5 5-2.24 5-5 5z\"/></svg>\n                <span style=\"color: #fff; font-weight: 700; font-size: 1.05rem; letter-spacing: 0.02em;\">Anticipating the Questions</span>\n            </div>\n            <div style=\"padding: 18px 20px; line-height: 1.7; color: var(--text-color, #333);\">\n                \n        <div style=\"\n            background: #c0392b08;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #c0392b; font-size: 0.92rem;\">\n                <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#c0392b\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M1 21h22L12 2 1 21zm12-3h-2v-2h2v2zm0-4h-2v-4h2v4z\"/></svg> Why TCROC and not ARIMA/MS-AR?\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">TCROC has an O(T) closed-form solution, while ARIMA/MS-AR require O(T²&ndash;T³) iteration. In addition, MS-AR failed numerically on 3 of 4 fuel series.</div>\n        </div>\n                        \n        <div style=\"\n            background: #d3540008;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #d35400; font-size: 0.92rem;\">\n                <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#d35400\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M1 21h22L12 2 1 21zm12-3h-2v-2h2v2zm0-4h-2v-4h2v4z\"/></svg> Why K-Means and not fixed thresholds?\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">Fixed thresholds are exogenous. K-Means adapts the cutoff points to the empirical distribution of each series. Superiority demonstrated with the Diebold-Mariano test.</div>\n        </div>\n                        \n        <div style=\"\n            background: #8e44ad08;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #8e44ad; font-size: 0.92rem;\">\n                <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#8e44ad\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M1 21h22L12 2 1 21zm12-3h-2v-2h2v2zm0-4h-2v-4h2v4z\"/></svg> What does NNLS add over OLS?\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">OLS can produce negative (inadmissible) transition probabilities. NNLS guarantees by construction P<sub>ij</sub> &ge; 0 and &sum;P<sub>ij</sub> = 1.</div>\n        </div>\n                        \n        <div style=\"\n            background: #00664408;\n            border-radius: 12px;\n            padding: 14px 18px;\n            margin: 12px 0;\n        \">\n            <div style=\"font-weight: 700; margin-bottom: 6px; color: #006644; font-size: 0.92rem;\">\n                <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"#006644\" style=\"vertical-align:middle;flex-shrink:0;\"><path d=\"M1 21h22L12 2 1 21zm12-3h-2v-2h2v2zm0-4h-2v-4h2v4z\"/></svg> What is the original contribution?\n            </div>\n            <div style=\"font-size: 0.93rem; line-height: 1.65;\">(1) The TCROC family with 4 variants and axiomatic proofs. (2) The degeneration phenomenon and its solution. (3) The TCROC-Markov &sub; SSRC inclusion theorem. (4) Comprehensive empirical validation with real data from Honduras.</div>\n        </div>\n                        \n            </div>\n        </div>"}}},"flashcards":{"databricksDAFlashcards":{"from":"en","t":{"0":{"tema":"Dominio 1: Arquitectura Lakehouse","pregunta":"¿Qué es un Lakehouse y en qué se diferencia de un Data Lake y de un Data Warehouse?","respuesta":"Un <strong>Lakehouse</strong> combina la <strong>flexibilidad</strong> de un Data Lake (bajo costo, archivos sin procesar) con la <strong>gestión</strong> de un Data Warehouse (transacciones ACID mediante Delta Lake, aplicación de esquema).<br><br>Elimina los silos de datos al permitir que BI y ML operen sobre los mismos datos."},"1":{"tema":"Dominio 1: Arquitectura Lakehouse","pregunta":"¿Cuáles son las tres capas de la Medallion Architecture?","respuesta":"<strong>Bronze (Raw):</strong> Datos sin validar cargados 'tal cual'. Solo anexado (append-only). Archivo histórico.<br><br><strong>Silver (Clean):</strong> 'Vista empresarial'. Limpios, sin duplicados, con esquema aplicado. Fuente de verdad.<br><br><strong>Gold (Curated):</strong> 'Capa de presentación'. Agregados para BI/reportes. Esquemas en estrella."},"2":{"tema":"Dominio 1: Arquitectura Lakehouse","pregunta":"¿Cuál es la regla mnemotécnica para las capas de la Medallion Architecture?","respuesta":"<strong>Bronze:</strong> Historia (Pasado) — archivo sin procesar<br><strong>Silver:</strong> Calidad (Presente) — verdad limpia<br><strong>Gold:</strong> BI/Agregados (Futuro) — listo para el negocio<br><br><strong>Trampa:</strong> Nunca hagas agregaciones de negocio en Bronze. Nunca almacenes datos sin procesar y desordenados en Gold."},"3":{"tema":"Dominio 1: Arquitectura Lakehouse","pregunta":"¿Qué es Delta Lake y qué proporciona?","respuesta":"<strong>Delta Lake</strong> es la capa de almacenamiento que agrega <strong>transacciones ACID</strong> sobre archivos Parquet.<br><br>Características clave:<br>• Aplicación y evolución de esquema<br>• Time Travel (consultar versiones históricas)<br>• Comandos OPTIMIZE y VACUUM<br>• Procesamiento unificado de streaming + batch"},"4":{"tema":"Dominio 2: Gestión de datos","pregunta":"¿Qué es Unity Catalog y qué espacio de nombres utiliza?","respuesta":"<strong>Unity Catalog</strong> proporciona gobernanza centralizada para los activos de datos e IA en todos los workspaces.<br><br>Espacio de nombres: <code>catalog.schema.table</code> (tres niveles).<br><br>Se encarga del control de acceso, la auditoría, el seguimiento del linaje y el uso compartido de datos."},"5":{"tema":"Dominio 2: Gestión de datos","pregunta":"¿Cuál es la diferencia entre las tablas Managed y External?","respuesta":"<strong>Managed Table:</strong><br>• Almacenamiento gestionado por Unity Catalog<br>• DROP TABLE → <strong>elimina los datos Y los metadatos</strong><br><br><strong>External Table:</strong><br>• Almacenamiento en una ruta específica (S3/ADLS/GCS)<br>• DROP TABLE → <strong>elimina solo los metadatos</strong> (los archivos permanecen)<br><br><strong>Consejo de examen:</strong> Esta distinción se evalúa con frecuencia."},"6":{"tema":"Dominio 2: Gestión de datos","pregunta":"¿Qué es Liquid Clustering y cuándo debes usarlo?","respuesta":"<strong>Liquid Clustering</strong> es una distribución dinámica moderna que <strong>reemplaza el particionamiento y Z-Order</strong>.<br><br>• Ideal para datos de alta cardinalidad o con sesgo<br>• Optimiza automáticamente la distribución de los datos<br>• No es necesario elegir columnas de partición<br><br><strong>Alternativa heredada:</strong> Particionamiento = carpetas físicas, solo para baja cardinalidad (Año/Mes)."},"7":{"tema":"Dominio 2: Gestión de datos","pregunta":"¿Qué es el Delta Log?","respuesta":"El <strong>Delta Log</strong> es la capa transaccional de Delta Lake:<br><br>• Contiene archivos JSON que registran cada operación<br>• Habilita las garantías ACID<br>• Impulsa las capacidades de Time Travel<br>• Rastrea el historial de evolución del esquema<br>• Se generan checkpoints periódicamente para mejorar el rendimiento"},"8":{"tema":"Dominio 3: Time Travel","pregunta":"¿Cómo consultas una tabla en una versión o marca de tiempo específica?","respuesta":"<strong>Estándar ANSI:</strong><br><code>SELECT * FROM t TIMESTAMP AS OF '2023-10-01';</code><br><code>SELECT * FROM t VERSION AS OF 5;</code><br><br><strong>Forma abreviada (@):</strong><br><code>SELECT * FROM t@v123;</code><br><br>Usa <code>DESCRIBE HISTORY table;</code> para ver todas las versiones."},"9":{"tema":"Dominio 3: Time Travel","pregunta":"¿Qué hace VACUUM y cuál es su limitación crítica?","respuesta":"<strong>VACUUM</strong> elimina archivos físicos antiguos para ahorrar espacio de almacenamiento.<br><br><strong>Advertencia crítica:</strong> <strong>No puedes</strong> hacer Time Travel a versiones más antiguas que el umbral de retención una vez que se ejecuta VACUUM.<br><br>Retención predeterminada: 7 días.<br><code>VACUUM table RETAIN 168 HOURS;</code>"},"10":{"tema":"Dominio 3: Time Travel","pregunta":"¿Para qué se usa el comando RESTORE?","respuesta":"<strong>RESTORE TABLE t TO VERSION AS OF 5;</strong><br><br>Devuelve la tabla a un estado anterior. A diferencia de las consultas de Time Travel (de solo lectura), RESTORE <strong>realmente modifica</strong> la tabla actual para que coincida con la versión histórica.<br><br>Crea una nueva versión en el Delta Log (se puede deshacer)."},"11":{"tema":"Dominio 4: Visualizaciones","pregunta":"¿Cómo funcionan los parámetros de los dashboards en Databricks SQL?","respuesta":"Los valores seleccionados en los parámetros del dashboard deben <strong>asignarse a variables de la consulta</strong> (<code>{{ param }}</code>).<br><br>Si un gráfico no se actualiza, revisa la asignación de parámetros.<br><br><strong>Trampa:</strong> Las alertas se evalúan con base en el <strong>valor predeterminado (Default Value)</strong> del parámetro, no en la selección actual del dashboard."},"12":{"tema":"Dominio 4: Visualizaciones","pregunta":"¿Cuáles son los requisitos de una consulta de alerta?","respuesta":"Una consulta de alerta debe devolver <strong>una sola fila y un solo valor</strong>.<br><br>Las alertas se activan cuando el valor:<br>• Supera un umbral<br>• Queda por debajo de un umbral<br>• Es igual a un valor específico<br><br>Las consultas de alerta se ejecutan con los <strong>valores predeterminados de los parámetros</strong>, no con las selecciones actuales del dashboard."},"13":{"tema":"Dominio 4: Visualizaciones","pregunta":"¿Para qué se usan las visualizaciones de tipo counter?","respuesta":"Las <strong>visualizaciones de tipo counter</strong> muestran una sola métrica de forma destacada:<br><br>• Muestran un número grande (KPI)<br>• Pueden compararse con un objetivo o con el período anterior<br>• Ideales para dashboards ejecutivos<br>• La consulta debe devolver un solo valor<br><br>Uso común: ingresos totales, número de usuarios, tasa de conversión."},"14":{"tema":"Dominio 5: Ingesta","pregunta":"¿Cuándo debes usar COPY INTO frente a CTAS?","respuesta":"<strong>Regla de decisión:</strong><br><br><strong>¿Origen = archivos?</strong> → Usa <code>COPY INTO</code><br>• Idempotente (omite los archivos ya procesados)<br>• Más económico para cargas incrementales<br><br><strong>¿Origen = consulta/tabla?</strong> → Usa <code>CTAS</code><br>• CREATE TABLE AS SELECT<br>• Transformación masiva única"},"15":{"tema":"Dominio 5: Ingesta","pregunta":"¿Qué es Partner Connect en Databricks?","respuesta":"<strong>Partner Connect</strong> es la forma más rápida de conectarte con socios de ingesta como <strong>Fivetran</strong> o <strong>dbt</strong>.<br><br>• Crea automáticamente un SQL Warehouse oculto<br>• Genera tokens de API<br>• Configura los permisos de conexión<br>• Integraciones prediseñadas para herramientas populares"},"16":{"tema":"Dominio 5: Ingesta","pregunta":"¿Qué es Auto Loader y cuándo debe usarse?","respuesta":"<strong>Auto Loader</strong> procesa de forma incremental los archivos nuevos a medida que llegan al almacenamiento en la nube.<br><br>• Usa el formato <code>cloudFiles</code><br>• Escala a millones de archivos<br>• Inferencia y evolución de esquema<br>• <strong>Ideal para:</strong> ingesta de archivos en streaming<br><br>Más eficiente que COPY INTO para flujos de datos continuos."},"17":{"tema":"Dominio 6: Consultas avanzadas","pregunta":"¿Qué es la cláusula QUALIFY y cuándo debes usarla?","respuesta":"<strong>QUALIFY</strong> filtra los resultados con base en funciones de ventana, lo que evita subconsultas anidadas.<br><br><code>SELECT * FROM t<br>QUALIFY ROW_NUMBER() OVER(PARTITION BY id ORDER BY ts DESC) = 1</code><br><br>Esto devuelve solo el registro más reciente por ID — mucho más limpio que CTE + WHERE."},"18":{"tema":"Dominio 6: Consultas avanzadas","pregunta":"¿Cuál es la diferencia entre SEMI JOIN y ANTI JOIN?","respuesta":"<strong>LEFT SEMI JOIN:</strong><br>Devuelve las filas de la izquierda que <strong>tienen una coincidencia</strong> en la derecha. Sin duplicados de la derecha. Solo se devuelven las columnas de la izquierda.<br><br><strong>LEFT ANTI JOIN:</strong><br>Devuelve las filas de la izquierda que <strong>NO tienen coincidencia</strong> en la derecha.<br><br><strong>Caso de uso:</strong> SEMI = 'existe en', ANTI = 'no existe en'."},"19":{"tema":"Dominio 6: Consultas avanzadas","pregunta":"¿Cómo funciona PIVOT en Databricks SQL?","respuesta":"<strong>PIVOT</strong> rota los valores únicos de una columna en múltiples columnas.<br><br><strong>Debe</strong> usar una función de agregación:<br><code>SELECT * FROM t<br>PIVOT (SUM(sales) FOR region IN ('North', 'South'))</code><br><br>La cláusula IN especifica qué valores se convierten en encabezados de columna."},"20":{"tema":"Dominio 7: Tipos complejos","pregunta":"¿Cuándo debes usar EXPLODE frente a Higher-Order Functions?","respuesta":"<strong>EXPLODE(arr):</strong><br>Transforma una fila con un arreglo en múltiples filas (una por elemento). Úsalo cuando necesites hacer join/agregar elementos individuales.<br><br><strong>Higher-Order Functions (FILTER, TRANSFORM):</strong><br>Procesan arreglos sin expandirlos — mantienen intacto el número de filas. Son más eficientes cuando solo necesitas filtrar o transformar en el lugar."},"21":{"tema":"Dominio 7: Tipos complejos","pregunta":"¿Cómo extraes campos JSON en Databricks SQL?","respuesta":"<strong>Si la columna es STRUCT:</strong><br>Usa notación de punto: <code>col.field</code><br><br><strong>Si la columna es STRING:</strong><br>Usa <code>from_json(col, schema)</code> para analizarla.<br>O usa <code>col:field</code> (ruta JSON) para datos semiestructurados.<br><br><strong>Trampa de examen:</strong> La notación de punto solo funciona en STRUCT, no en cadenas sin procesar."},"22":{"tema":"Dominio 7: Tipos complejos","pregunta":"¿Qué son las higher-order functions FILTER y TRANSFORM?","respuesta":"<code>FILTER(arr, x -> x > 100)</code><br>Conserva solo los elementos que cumplen la condición.<br><br><code>TRANSFORM(arr, x -> x * 1.2)</code><br>Aplica una transformación a cada elemento del arreglo.<br><br><strong>Beneficio clave:</strong> No se necesita EXPLODE — mucho más eficiente para arreglos grandes."},"23":{"tema":"Dominio 8: Seguridad","pregunta":"¿Qué permisos se necesitan para hacer SELECT de una tabla en Unity Catalog?","respuesta":"Para hacer SELECT de una tabla, necesitas <strong>los tres</strong>:<br><br>1. <code>USAGE</code> en el Catalog<br>2. <code>USAGE</code> en el Schema<br>3. <code>SELECT</code> en la Table<br><br><strong>Regla clave:</strong> Los privilegios fluyen hacia abajo, pero el acceso requiere USAGE explícito en todos los contenedores por encima del objetivo."},"24":{"tema":"Dominio 8: Seguridad","pregunta":"¿Cómo habilitan las Dynamic Views la seguridad por fila y por columna?","respuesta":"<strong>Filtro de fila:</strong><br><code>WHERE region = current_user()</code><br>Solo muestra las filas que pertenecen a la región del usuario actual.<br><br><strong>Máscara de columna:</strong><br><code>CASE WHEN is_member('admin') THEN val ELSE '***' END</code><br>Oculta los valores sensibles a los usuarios que no son administradores."},"25":{"tema":"Dominio 8: Seguridad","pregunta":"¿Cuál es la diferencia entre GRANT y DENY en Unity Catalog?","respuesta":"<strong>GRANT:</strong> Otorga un privilegio a un usuario/grupo.<br><code>GRANT SELECT ON TABLE t TO user;</code><br><br><strong>REVOKE:</strong> Elimina un privilegio otorgado previamente.<br><code>REVOKE SELECT ON TABLE t FROM user;</code><br><br><strong>Nota:</strong> Unity Catalog usa un modelo de permisos aditivo — no existe la instrucción DENY."},"26":{"tema":"Dominio 9: Cómputo","pregunta":"¿Cuál es la diferencia entre los SQL Warehouses Serverless y Pro?","respuesta":"<strong>Serverless SQL Warehouse:</strong><br>• Arranca en <strong>segundos</strong><br>• El escalado es instantáneo<br>• Ideal para consultas ad hoc<br>• Administrado por Databricks<br><br><strong>Pro SQL Warehouse:</strong><br>• Arranca en <strong>minutos</strong><br>• Rendimiento predecible<br>• Ideal para producción con patrones de carga conocidos"},"27":{"tema":"Dominio 9: Cómputo","pregunta":"¿Qué es Photon y qué cargas de trabajo se benefician de él?","respuesta":"<strong>Photon</strong> es el motor de consultas vectorizado de Databricks escrito en C++.<br><br>• <strong>Hasta 12 veces más rápido</strong> que Spark estándar<br>• Ideal para cargas de trabajo intensivas en SQL y ETL<br>• Habilitado automáticamente en los warehouses Serverless<br>• Mejoras significativas en escaneos, agregaciones y joins"},"28":{"tema":"Dominio 9: Cómputo","pregunta":"¿Cuál es la diferencia entre los clústeres All-Purpose y Jobs?","respuesta":"<strong>All-Purpose Clusters:</strong><br>• Interactivos, para notebooks y exploración<br>• Pueden compartirse entre usuarios<br>• Siguen en ejecución hasta que se terminan<br><br><strong>Jobs Clusters:</strong><br>• Se crean para un job específico<br>• Se terminan automáticamente al completar el job<br>• Más económicos y eficientes para producción<br>• No se pueden compartir"},"29":{"tema":"Dominio 10: Rendimiento","pregunta":"¿Qué muestra Query Profile y cómo lo usas?","respuesta":"<strong>Query Profile</strong> es un plan de ejecución visual que identifica los cuellos de botella:<br><br>• <strong>Spill to Disk:</strong> Memoria insuficiente — se necesita un clúster más grande u optimización<br>• <strong>Full Table Scans:</strong> Faltan índices/poda — agrega clustering o filtros<br>• <strong>Skew:</strong> Distribución desigual de los datos entre particiones"},"30":{"tema":"Dominio 10: Rendimiento","pregunta":"¿Cuál es la diferencia entre OPTIMIZE y VACUUM?","respuesta":"<strong>OPTIMIZE:</strong><br>• Compacta archivos pequeños en archivos más grandes<br>• Reescribe los datos para mejorar el rendimiento de lectura<br>• NO elimina archivos antiguos<br><br><strong>VACUUM:</strong><br>• Elimina archivos antiguos sin referencias<br>• Ahorra espacio de almacenamiento<br>• <strong>Rompe el Time Travel</strong> para las versiones eliminadas<br>• Retención predeterminada: 7 días"},"31":{"tema":"Dominio 11: Estructuras","pregunta":"¿Cuál es la diferencia entre CTE, Temp View y Global Temp View?","respuesta":"<strong>CTE:</strong> Alcance = una sola consulta. Sin persistencia.<br><code>WITH cte AS (...) SELECT * FROM cte;</code><br><br><strong>Temp View:</strong> Alcance = sesión. Hasta cerrar sesión.<br><code>CREATE TEMP VIEW v AS ...;</code><br><br><strong>Global Temp View:</strong> Alcance = clúster. Hasta reiniciar.<br><code>CREATE GLOBAL TEMP VIEW v AS ...;</code>"},"32":{"tema":"Dominio 11: Estructuras","pregunta":"¿Cómo creas una SQL UDF en Databricks?","respuesta":"Las <strong>User Defined Functions</strong> encapsulan lógica reutilizable:<br><br><code>CREATE FUNCTION double_it(x INT)<br>RETURNS INT<br>RETURN x * 2;</code><br><br>Uso: <code>SELECT double_it(price) FROM products;</code><br><br>Las UDF pueden registrarse en Unity Catalog para usarlas entre workspaces."},"33":{"tema":"Dominio 11: Estructuras","pregunta":"¿Cuál es la diferencia entre las Views y las Materialized Views?","respuesta":"<strong>View:</strong><br>• Solo definición lógica (no almacena datos)<br>• La consulta se ejecuta cada vez<br>• Siempre actualizada<br><br><strong>Materialized View:</strong><br>• Almacena resultados precalculados<br>• Lecturas más rápidas (sin recálculo)<br>• Debe actualizarse (refresh) para mantenerse al día<br>• Excelente para agregaciones costosas"},"34":{"tema":"Dominio 12: AI/BI Genie","pregunta":"¿Qué son las Instructions y los Trusted Assets en AI/BI Genie?","respuesta":"<strong>Instructions:</strong><br>Reglas en texto plano que le enseñan a Genie conocimiento del dominio.<br>Ejemplo: 'Churn significa una suscripción cancelada.'<br><br><strong>Trusted Assets:</strong><br>Consultas SQL verificadas que se usan como fuente de verdad.<br>Genie las usa como ejemplos confiables al generar respuestas."},"35":{"tema":"Dominio 12: AI/BI Genie","pregunta":"¿Cuál es el papel de un Genie Space?","respuesta":"Un <strong>Genie Space</strong> es un entorno configurado para AI/BI Genie:<br><br>• Conectado a tablas y vistas específicas<br>• Contiene instrucciones seleccionadas<br>• Incluye consultas SQL de confianza<br>• Los usuarios de negocio hacen preguntas en lenguaje natural<br>• Genie genera SQL y devuelve resultados<br><br><strong>Clave:</strong> La calidad de las instrucciones determina la precisión."},"36":{"tema":"Transversal","pregunta":"¿Cuál es la diferencia clave entre DEEP CLONE y SHALLOW CLONE?","respuesta":"<strong>DEEP CLONE:</strong><br>• Copia datos + metadatos<br>• Copia independiente (los cambios no afectan al origen)<br>• Requiere más tiempo y almacenamiento<br><br><strong>SHALLOW CLONE:</strong><br>• Copia solo los metadatos (hace referencia a los datos del origen)<br>• Rápido y ligero<br>• Si se dañan los archivos del origen, se daña el clon<br>• Bueno para entornos de pruebas/desarrollo"},"37":{"tema":"Transversal","pregunta":"¿Qué es Change Data Feed (CDF)?","respuesta":"<strong>CDF</strong> rastrea los cambios a nivel de fila (inserciones, actualizaciones, eliminaciones) en una tabla Delta.<br><br>Habilitar: <code>ALTER TABLE t SET TBLPROPERTIES (delta.enableChangeDataFeed = true)</code><br><br>Leer los cambios: <code>SELECT * FROM table_changes('t', start_version)</code><br><br>Columnas agregadas: <code>_change_type</code>, <code>_commit_version</code>, <code>_commit_timestamp</code>"},"38":{"tema":"Transversal","pregunta":"¿Qué formato de archivo usa Delta Lake internamente?","respuesta":"<strong>Parquet</strong> — un formato de almacenamiento columnar.<br><br>Delta Lake = <strong>archivos Parquet + Delta Log (registro de transacciones JSON)</strong><br><br>Beneficios de Parquet:<br>• Compresión columnar (ocupa poco espacio)<br>• Predicate pushdown (filtrado eficiente)<br>• Esquema almacenado en los metadatos del archivo<br>• Interoperable con muchas herramientas"},"39":{"tema":"Transversal","pregunta":"¿Cuáles son los cuatro tipos de objetos principales en Unity Catalog?","respuesta":"<strong>1. Catalog:</strong> Contenedor de nivel superior (como un servidor de bases de datos)<br><strong>2. Schema:</strong> Colección de tablas/vistas (como una base de datos)<br><strong>3. Table:</strong> Objeto de datos (managed o external)<br><strong>4. View:</strong> Consulta lógica almacenada como una definición<br><br>Patrón de acceso: <code>catalog.schema.object</code>"},"40":{"tema":"Dominio 1: Inteligencia de la plataforma","pregunta":"¿Qué es el Data Intelligence Engine en Databricks?","respuesta":"El <strong>Data Intelligence Engine</strong> es el cerebro de IA que impulsa toda la plataforma Databricks.<br><br>Aporta inteligencia a:<br>• <strong>Databricks Assistant</strong> (copiloto de IA)<br>• <strong>AI/BI Genie</strong> (analítica en lenguaje natural)<br>• Optimizaciones automáticas (ajuste de consultas, distribución de archivos)<br><br>Comprende la semántica de los datos, los metadatos y los patrones de uso para mejorar la productividad y la precisión."},"41":{"tema":"Dominio 1: Inteligencia de la plataforma","pregunta":"¿Qué es Databricks Assistant y dónde puedes usarlo?","respuesta":"<strong>Databricks Assistant</strong> es un copiloto de IA integrado en los <strong>Notebooks</strong> y el <strong>SQL Editor</strong>.<br><br>Ayuda a:<br>• Escribir y depurar consultas SQL/Python<br>• Explicar errores y sugerir correcciones<br>• Generar automáticamente documentación para notebooks<br>• Optimizar el rendimiento de las consultas<br><br><strong>Consejo de examen:</strong> Ten presente que Assistant se evalúa en el Dominio 4 (Ejecución de consultas)."},"42":{"tema":"Dominio 1: Inteligencia de la plataforma","pregunta":"¿Qué son Mosaic AI y Lakeflow Jobs?","respuesta":"<strong>Mosaic AI:</strong><br>• Plataforma unificada para ML y GenAI<br>• Incluye Model Serving, Vector Search, Feature Store<br>• Para el examen DA: debes saber que existe como componente de la plataforma<br><br><strong>Lakeflow Jobs:</strong><br>• Orquestación y programación de flujos de trabajo<br>• Encadena notebooks, consultas SQL y pipelines<br>• Evolución de Databricks Workflows<br>• Para el examen DA: debes saber que ejecuta pipelines programados"},"43":{"tema":"Dominio 1: Inteligencia de la plataforma","pregunta":"¿Qué es Databricks Marketplace?","respuesta":"<strong>Databricks Marketplace</strong> es un mercado abierto para descubrir y acceder a:<br><br>• Conjuntos de datos de terceros<br>• Notebooks y soluciones<br>• Modelos de ML<br><br>Permite importar datos externos <strong>sin pipelines de ingesta complejos</strong>.<br><br><strong>Cobertura en el examen:</strong><br>• Dominio 1: Componente de la plataforma<br>• Dominio 3: Método para importar datos"},"44":{"tema":"Dominio 4: SQL Warehouses","pregunta":"¿Qué son las Materialized Views y en qué se diferencian de las Streaming Tables?","respuesta":"<strong>Materialized View:</strong><br>• Almacena resultados de consultas precalculados<br>• Debe hacerse REFRESH para actualizarla<br>• Ideal para agregaciones costosas<br>• Actualización a demanda o programada<br><br><strong>Streaming Table:</strong><br>• Se actualiza de forma incremental con datos nuevos (append-only)<br>• No necesita recálculo completo<br>• Ideal para ingesta continua<br><br><strong>Consejo de examen:</strong> Se evalúa con frecuencia: cuándo usar cada una."},"45":{"tema":"Dominio 4: SQL Warehouses","pregunta":"¿Qué son las Federated Queries en Databricks?","respuesta":"Las <strong>Federated Queries</strong> te permiten hacer JOIN de tablas Delta con orígenes de datos externos (PostgreSQL, MySQL, SQL Server) <strong>sin mover los datos</strong>.<br><br>• Usan <strong>Foreign Catalogs</strong> en Unity Catalog<br>• Registran conexiones con sistemas externos<br>• Las consultas se ejecutan en el lugar<br>• Habilitan la analítica entre sistemas<br><br><strong>Consejo de examen:</strong> Ten presente que las consultas federadas usan Foreign Catalogs."},"46":{"tema":"Dominio 5: Análisis de consultas","pregunta":"¿Cómo funciona el Query Caching en Databricks SQL?","respuesta":"El <strong>Query Caching</strong> almacena automáticamente los resultados de las consultas.<br><br>• Misma consulta + mismos datos = <strong>resultado instantáneo desde la caché</strong><br>• No se necesita recálculo<br>• Reduce la latencia y los costos de cómputo<br>• La caché se <strong>invalida automáticamente</strong> cuando cambian los datos subyacentes<br><br><strong>Consejo de examen:</strong> Ten presente que el almacenamiento en caché reduce el tiempo de desarrollo y la latencia de las consultas (objetivo del Dominio 5)."},"47":{"tema":"Dominio 6: Dashboards","pregunta":"¿Cómo funcionan los permisos y el uso compartido de los dashboards?","respuesta":"<strong>Niveles de permiso:</strong><br>• <strong>CAN VIEW:</strong> Acceso de solo lectura<br>• <strong>CAN RUN:</strong> Ver + actualizar datos<br>• <strong>CAN EDIT:</strong> Modificar widgets y diseño<br><br><strong>Métodos para compartir:</strong><br>• Usuarios/grupos del workspace (directo)<br>• Enlaces compartibles (usuarios externos sin cuenta de Databricks)<br>• Incrustados en aplicaciones externas<br><br><strong>Clave:</strong> El <strong>propietario (Owner)</strong> controla todos los permisos."},"48":{"tema":"Dominio 6: Dashboards","pregunta":"¿Cómo configuras la programación y la actualización de un dashboard?","respuesta":"<strong>Programación del dashboard:</strong><br>• Configura intervalos de actualización automática (de 1 min a 1 semana)<br>• Cada visualización actualiza su consulta subyacente<br>• Usa el SQL Warehouse configurado<br><br><strong>Suscriptores:</strong><br>• Reciben capturas del dashboard por correo electrónico<br>• Según la programación de actualización<br><br><strong>Consejo de examen:</strong> Ten presente que las programaciones usan el warehouse asociado al dashboard."},"49":{"tema":"Dominio 8: Modelado de datos","pregunta":"¿Cómo se alinean Star Schema y Data Vault con la Medallion Architecture?","respuesta":"<strong>Star Schema:</strong><br>• Tabla de hechos rodeada de tablas de dimensiones<br>• Optimizado para BI y consultas analíticas<br>• Ideal para la <strong>capa Gold</strong> de Medallion<br><br><strong>Data Vault:</strong><br>• Hubs (entidades), Links (relaciones), Satellites (atributos)<br>• Diseñado para la auditabilidad y la trazabilidad<br>• Adecuado para entornos empresariales complejos<br><br><strong>Consejo de examen:</strong> Ambos patrones se alinean con la capa Gold/de presentación."},"50":{"tema":"Dominio 2: Gestión de datos","pregunta":"¿Qué son las Certified Tables y los Tags en Unity Catalog?","respuesta":"<strong>Certified Tables:</strong><br>• Marcadas como orígenes de datos verificados y confiables<br>• Los usuarios pueden filtrar Catalog Explorer por certificación<br>• Indican la calidad y confiabilidad de los datos<br><br><strong>Tags:</strong><br>• Etiquetas clave-valor para clasificar activos de datos<br>• Permiten la búsqueda y el descubrimiento entre catálogos<br>• Ejemplos: 'pii=true', 'domain=finance'<br><br><strong>Consejo de examen:</strong> La certificación + los Tags ayudan al descubrimiento de datos (Dominio 2)."},"51":{"tema":"Dominio 2: Gestión de datos","pregunta":"¿Cómo funciona Data Lineage en Unity Catalog?","respuesta":"<strong>Data Lineage</strong> en Unity Catalog rastrea automáticamente:<br><br>• <strong>De dónde provienen los datos</strong> (dependencias upstream)<br>• <strong>Qué consume los datos</strong> (impacto downstream)<br>• Linaje a nivel de columna para un seguimiento granular<br><br>Visible en <strong>Catalog Explorer</strong> como un grafo interactivo.<br><br><strong>Casos de uso:</strong><br>• Cumplimiento normativo y auditoría<br>• Análisis de impacto antes de cambios de esquema<br>• Análisis de causa raíz de problemas de datos"},"52":{"tema":"Dominio 9: Protección de datos","pregunta":"¿Cómo funcionan la propiedad de tablas y la protección de PII?","respuesta":"<strong>Propiedad de tablas:</strong><br>• El propietario tiene control total sobre los permisos<br>• Solo el propietario o el Metastore Admin pueden hacer GRANT/REVOKE<br>• La propiedad se puede transferir<br><br><strong>Protección de PII:</strong><br>• <strong>Column Masks:</strong> Ocultan datos sensibles (p. ej., enmascarar el SSN para quienes no son administradores)<br>• <strong>Row Filters:</strong> Limitan las filas visibles por usuario/grupo<br>• Ambos se configuran en Unity Catalog<br><br><strong>Clave:</strong> PII = Personally Identifiable Information (información de identificación personal)"},"53":{"tema":"Dominio 7: AI/BI Genie","pregunta":"¿Cómo mantienes y optimizas un Genie Space?","respuesta":"<strong>Mantenimiento de Genie Spaces:</strong><br><br>• <strong>Actualizar Instructions:</strong> Refina las reglas de texto según la retroalimentación de las partes interesadas<br>• <strong>Revisar Trusted Assets:</strong> Revisa y aprueba consultas SQL como fuente de verdad<br>• <strong>Actualizar metadatos:</strong> Sincroniza los metadatos de Unity Catalog cuando cambien los esquemas<br>• <strong>Validar la precisión:</strong> Compara las respuestas de Genie con consultas conocidas<br><br><strong>Consejo de examen:</strong> La calidad de las instrucciones y de los trusted assets determina directamente la precisión de Genie."},"54":{"tema":"Dominio 7: AI/BI Genie","pregunta":"¿Cómo compartes y administras los permisos de los AI/BI Genie Spaces?","respuesta":"<strong>Compartir Genie Spaces:</strong><br>• Otorga acceso a usuarios o grupos del workspace<br>• Roles: <strong>Owner</strong> (control total), <strong>Editor</strong> (modificar instrucciones), <strong>Viewer</strong> (solo hacer preguntas)<br><br><strong>Buenas prácticas:</strong><br>• Limita el acceso de editor a los data stewards que entienden el dominio<br>• Revisa periódicamente la precisión de las consultas generadas<br>• Usa Trusted Assets para prevenir alucinaciones<br><br><strong>Clave:</strong> Los permisos de Genie son independientes de los permisos de las tablas."},"55":{"tema":"Dominio 8: Seguridad","pregunta":"Tienes SELECT sobre una tabla y USAGE sobre su schema, pero no puedes ver los datos. ¿Por qué?","respuesta":"Te falta <strong>USE CATALOG</strong> sobre el catálogo padre.<br><br><strong>Regla de la ruta de acceso:</strong><br>1. USAGE en el Catalog<br>2. USAGE en el Schema<br>3. SELECT en la Table<br><br>Si falta cualquier eslabón de esta cadena, se deniega el acceso (incluso para los propietarios de la tabla si no son administradores del workspace)."},"56":{"tema":"Dominio 2: Gestión de datos","pregunta":"¿Cuál es la diferencia entre la retención del Transaction Log y la retención de los archivos de datos?","respuesta":"<strong>Transaction Log (metadatos):</strong> 30 días de forma predeterminada. Controla hasta cuándo existen los metadatos.<br><br><strong>Archivos de datos (físicos):</strong> 7 días de forma predeterminada. Controla hasta cuándo VACUUM conserva los datos.<br><br><strong>Consejo de examen:</strong> El Time Travel depende de AMBOS. Si se ejecuta VACUUM, no puedes retroceder más de 7 días aunque existan los logs."},"57":{"tema":"Dominio 2: Gestión de datos","pregunta":"¿Cómo marcas programáticamente una tabla como 'Certified' o 'Deprecated'?","respuesta":"Usa <strong>System Tags</strong> en Unity Catalog:<br><code>ALTER TABLE t SET TAGS ('system.certification_status' = 'certified');</code><br><code>ALTER TABLE t SET TAGS ('system.certification_status' = 'deprecated');</code><br><br>Esto garantiza que el estado sea visible en los filtros de Catalog Explorer."},"58":{"tema":"Dominio 6: Ejecución de consultas","pregunta":"¿Cómo compruebas si un arreglo 'tags' contiene el valor 'sql'?","respuesta":"Usa la sintaxis <strong>'val' IN array</strong>:<br><code>SELECT * FROM table WHERE 'sql' IN (tags);</code><br><br><strong>Nota:</strong> <code>array_contains(tags, 'sql')</code> también funciona, pero la sintaxis 'IN' es más común en el examen. <code>tags = 'sql'</code> fallará porque compara un arreglo con una cadena."},"59":{"tema":"Dominio 6: Ejecución de consultas","pregunta":"¿Cuál es el resultado de ejecutar 'USE CATALOG main; USE SCHEMA default;'?","respuesta":"Establece el <strong>espacio de nombres de la sesión (Session Namespace)</strong>. Las consultas posteriores, como <code>SELECT * FROM my_table;</code>, se resolverán automáticamente como <code>main.default.my_table</code>.<br><br>Esto evita usar nombres calificados en cada consulta mientras dure esa sesión."},"60":{"tema":"Dominio 1: Comprensión de la plataforma","pregunta":"¿Qué es el Data Intelligence Engine (DIE)?","respuesta":"El 'cerebro' de IA del Lakehouse. Incorpora machine learning a la plataforma para:<br>• Comprender la semántica de los datos (el significado de las columnas)<br>• Impulsar Assistant y Genie<br>• Automatizar optimizaciones (Predictive Optimization)<br>• Mejorar automáticamente el rendimiento de las consultas."},"61":{"tema":"Dominio 7: AI/BI Genie","pregunta":"Genie está dando respuestas inexactas. ¿Cuál es el MEJOR primer paso para corregirlo?","respuesta":"<strong>Actualizar las Instructions</strong> y agregar <strong>Trusted Assets</strong> (ejemplos de SQL).<br><br>Agregar más tablas suele añadir ruido. Desactivar la retroalimentación impide el aprendizaje. Las Instructions guían la lógica; los Trusted Assets proporcionan patrones verificados de fuente de verdad."},"62":{"tema":"Dominio 4: SQL Warehouses","pregunta":"¿Qué son los Lakeflow Spark Declarative Pipelines?","respuesta":"Una forma <strong>declarativa (YAML/JSON)</strong> de definir pipelines de ETL. <br><br>Características clave:<br>• Aplicación automática de la calidad de los datos (expectations)<br>• Manejo de errores sin código manual<br>• Totalmente administrado por Databricks<br>• Se enfoca en 'Qué hacer' en lugar de 'Cómo programarlo'."},"63":{"tema":"Dominio 3: Importación de datos","pregunta":"¿Qué hace el modo 'rescue' en Auto Loader?","respuesta":"Captura automáticamente datos que no coinciden con el esquema esperado en una columna JSON llamada <strong>_rescued_data</strong>, evitando que la query falle y permitiendo auditar datos corruptos."},"64":{"tema":"Dominio 3: Importación de datos","pregunta":"¿Cuál es el propósito de COPY INTO ... VALIDATE?","respuesta":"Permite realizar un <strong>'dry-run'</strong> de la carga de datos para identificar errores de formato, delimitadores o tipos antes de que se inserten registros reales en la tabla Delta."},"65":{"tema":"Dominio 3: Importación de datos","pregunta":"¿Listing vs Notifications en Auto Loader?","respuesta":"<strong>Directory Listing</strong> escanea el bucket recursivamente (lento a gran escala). <strong>File Notifications</strong> usa servicios de nube (SQS/SNS) para actuar solo sobre archivos nuevos, siendo mucho más eficiente para millones de archivos."},"66":{"tema":"Dominio 3: Importación de datos","pregunta":"¿Cómo auditar archivos cargados vía COPY INTO?","respuesta":"Ejecutando <code>DESCRIBE HISTORY table_name;</code> y analizando el campo <strong>operationMetrics</strong> de la transacción correspondiente, donde se listan metadatos de la ingesta."},"67":{"tema":"Dominio 9: Protección de datos","pregunta":"¿Storage Credential vs External Location?","respuesta":"El <strong>Storage Credential</strong> es el objeto que contiene el acceso seguro (IAM/Role) a la nube. El <strong>External Location</strong> es el path específico que usa dicha credencial para otorgar acceso a los usuarios."},"68":{"tema":"Dominio 6: Dashboards y visualizaciones","pregunta":"¿Cómo evitar refrescos constantes al cambiar filtros?","respuesta":"Desactivando <strong>'Automatic Update'</strong> en la configuración del filtro para permitir cambios por 'lotes' de filtros antes de refrescar manualmente."},"69":{"tema":"Dominio 6: Dashboards y visualizaciones","pregunta":"¿Cómo crear Table Hyperlinks dinámicos?","respuesta":"Cambiando el tipo de columna a <strong>'Link'</strong> y usando <code>{{column_name}}</code> dentro del template de la URL."},"70":{"tema":"Dominio 6: Dashboards y visualizaciones","pregunta":"¿Qué sucede con un Schedule si el Owner es eliminado?","respuesta":"El refresh <strong>fallará</strong>, ya que no hay una identidad válida para la ejecución. Se debe transferir la propiedad del dashboard o usar un Service Principal."},"71":{"tema":"Dominio 6: Dashboards y visualizaciones","pregunta":"¿Qué es Cross-Filtering?","respuesta":"Una funcionalidad interactiva que permite que un gráfico (ej. barras) actúe como filtro para el resto de la página al hacer clic en un elemento visual."},"72":{"tema":"Dominio 6: Dashboards y visualizaciones","pregunta":"¿Run as Owner vs Run as Viewer en Dashboards?","respuesta":"<strong>Run as Owner:</strong> Los usuarios ven los datos sin tener permisos directos a las tablas. <strong>Run as Viewer:</strong> Requiere que el usuario final tenga permisos en el Warehouse y en los datos de origen."},"73":{"tema":"Dominio 7: AI/BI Genie Spaces","pregunta":"¿Qué es un 'Trusted Asset' en Genie?","respuesta":"Una consulta SQL <strong>verificada y predefinida</strong> que Genie usa cuando detecta una pregunta relacionada, garantizando 100% de precisión en métricas clave."},"74":{"tema":"Dominio 7: AI/BI Genie Spaces","pregunta":"¿Por qué son vitales los comentarios en Unity Catalog?","respuesta":"Genie usa los <strong>comentarios de tablas y columnas</strong> como contexto semántico para entender el lenguaje natural. Sin metadatos, Genie no puede distinguir términos de negocio similares."},"75":{"tema":"Dominio 7: AI/BI Genie Spaces","pregunta":"¿Permisos mínimos para un consumidor de Genie?","respuesta":"El permiso <strong>'Can Use'</strong>, que permite hacer preguntas y ver resultados sin modificar la configuración del espacio."},"76":{"tema":"Dominio 7: AI/BI Genie Spaces","pregunta":"¿Cómo mejorar Genie tras un feedback negativo (Thumbs Down)?","respuesta":"Revisando el historial, corrigiendo el SQL generado manualmente y guardándolo como una <strong>Sample Question</strong> o 'Trusted Asset'."}},"fix":{"63":{"tema":"Domain 3: Importing Data","pregunta":"What does 'rescue' mode do in Auto Loader?","respuesta":"It automatically captures data that does not match the expected schema in a JSON column named <strong>_rescued_data</strong>, preventing the query from failing and allowing you to audit corrupt data."},"64":{"tema":"Domain 3: Importing Data","pregunta":"What is the purpose of COPY INTO ... VALIDATE?","respuesta":"It lets you perform a <strong>'dry-run'</strong> of the data load to identify format, delimiter, or type errors before any real records are inserted into the Delta table."},"65":{"tema":"Domain 3: Importing Data","pregunta":"Listing vs. Notifications in Auto Loader?","respuesta":"<strong>Directory Listing</strong> scans the bucket recursively (slow at large scale). <strong>File Notifications</strong> uses cloud services (SQS/SNS) to act only on new files, making it much more efficient for millions of files."},"66":{"tema":"Domain 3: Importing Data","pregunta":"How do you audit files loaded via COPY INTO?","respuesta":"By running <code>DESCRIBE HISTORY table_name;</code> and analyzing the <strong>operationMetrics</strong> field of the corresponding transaction, where the ingestion metadata is listed."},"67":{"tema":"Domain 9: Securing Data","pregunta":"Storage Credential vs. External Location?","respuesta":"The <strong>Storage Credential</strong> is the object that holds the secure access (IAM/Role) to the cloud. The <strong>External Location</strong> is the specific path that uses that credential to grant access to users."},"68":{"tema":"Domain 6: Dashboards & Visualizations","pregunta":"How do you avoid constant refreshes when changing filters?","respuesta":"By disabling <strong>'Automatic Update'</strong> in the filter settings, so you can change filters in 'batches' before refreshing manually."},"69":{"tema":"Domain 6: Dashboards & Visualizations","pregunta":"How do you create dynamic Table Hyperlinks?","respuesta":"By changing the column type to <strong>'Link'</strong> and using <code>{{column_name}}</code> inside the URL template."},"70":{"tema":"Domain 6: Dashboards & Visualizations","pregunta":"What happens to a Schedule if the Owner is deleted?","respuesta":"The refresh <strong>will fail</strong>, because there is no valid identity to run it. You must transfer ownership of the dashboard or use a Service Principal."},"71":{"tema":"Domain 6: Dashboards & Visualizations","pregunta":"What is Cross-Filtering?","respuesta":"An interactive feature that lets a chart (e.g., a bar chart) act as a filter for the rest of the page when you click a visual element."},"72":{"tema":"Domain 6: Dashboards & Visualizations","pregunta":"Run as Owner vs. Run as Viewer in Dashboards?","respuesta":"<strong>Run as Owner:</strong> Users see the data without having direct permissions on the tables. <strong>Run as Viewer:</strong> Requires the end user to have permissions on the Warehouse and on the source data."},"73":{"tema":"Domain 7: AI/BI Genie Spaces","pregunta":"What is a 'Trusted Asset' in Genie?","respuesta":"A <strong>verified, predefined</strong> SQL query that Genie uses when it detects a related question, guaranteeing 100% accuracy on key metrics."},"74":{"tema":"Domain 7: AI/BI Genie Spaces","pregunta":"Why are comments in Unity Catalog vital?","respuesta":"Genie uses <strong>table and column comments</strong> as semantic context to understand natural language. Without metadata, Genie cannot distinguish between similar business terms."},"75":{"tema":"Domain 7: AI/BI Genie Spaces","pregunta":"Minimum permissions for a Genie consumer?","respuesta":"The <strong>'Can Use'</strong> permission, which lets you ask questions and view results without modifying the space configuration."},"76":{"tema":"Domain 7: AI/BI Genie Spaces","pregunta":"How do you improve Genie after negative feedback (Thumbs Down)?","respuesta":"By reviewing the history, manually correcting the generated SQL, and saving it as a <strong>Sample Question</strong> or 'Trusted Asset'."}}},"unirVizFlashcards":{"from":"es","t":{"0":{"tema":"Topic 1: Introduction","pregunta":"What is the fundamental difference between an infographic and a data visualization?","respuesta":"<strong>Infographic:</strong> It is a <em>closed</em> narrative piece in which the author tells a predefined story.<br><br><strong>Data visualization:</strong> It is an <em>open and exploratory</em> system in which the user can interact, filter, and discover their own patterns.<br><br><strong>Note:</strong> Both share the goal of communicating data, but they differ in user autonomy."},"1":{"tema":"Topic 1: Introduction","pregunta":"What does 'amplifying cognition' mean in the context of visualization?","respuesta":"It means that visualization acts as an <strong>extension of the human visual system</strong>, making it possible to understand relationships and patterns that would be impossible to detect by looking only at raw data (tables, numbers).<br><br>The human brain processes visual information much faster than text, detecting anomalies <strong>pre-attentively</strong> (automatically and unconsciously)."},"2":{"tema":"Topic 1: Introduction","pregunta":"What are the 5 phases of the process of creating a visualization?","respuesta":"<ol style='padding-left:20px;'><li><strong>Research</strong> of sources</li><li><strong>Selection</strong> and curation of data</li><li><strong>Sketch</strong> (sketch)</li><li>Technical <strong>development</strong></li><li><strong>Reception</strong> and knowledge generation</li></ol>"},"3":{"tema":"Topic 1: Introduction","pregunta":"What is the Data → Information → Knowledge hierarchy?","respuesta":"<strong>Data:</strong> Pure value without context (e.g., '42')<br><br><strong>Information:</strong> Processed data with meaning (e.g., 'a temperature of 42°C')<br><br><strong>Knowledge:</strong> Understood information that allows decisions to be made (e.g., '42°C = fever, needs medical attention')<br><br><strong>Note:</strong> Visualization facilitates this transition from data to knowledge."},"4":{"tema":"Topic 1: Introduction","pregunta":"Why is the human visual system the foundation of data visualization?","respuesta":"Because the brain <strong>detects visual patterns at high speed</strong>, processing information almost instantly. It is the most powerful sensory channel of human beings.<br><br>We process images much faster than text and detect anomalies <strong>pre-attentively</strong> (before conscious attention)."},"5":{"tema":"Topic 2: History","pregunta":"What did Leonardo Da Vinci contribute to visualization?","respuesta":"Da Vinci was a pioneer because his drawings <strong>were not simple illustrations</strong>: they were <strong>tools for empirical research</strong> to understand anatomy, engineering, and nature.<br><br>He fused science and art through technical and anatomical drawing."},"6":{"tema":"Topic 2: History","pregunta":"What is Isotype and who created it?","respuesta":"<strong>Isotype</strong> (International System of Typographic Picture Education) was a system of <strong>standardized pictograms</strong> created by <strong>Otto Neurath and Gerd Arntz</strong> in the 1920s.<br><br>It was used to communicate social and economic statistics to people of any educational level."},"7":{"tema":"Topic 2: History","pregunta":"When and where was the first journalistic infographic published?","respuesta":"On <strong>April 7, 1806</strong> in <strong>The Times of London</strong>. A plan of a crime scene was published (the murder of Isaac Blight).<br><br>Other milestones:<br>• <strong>1982:</strong> USA Today launches its 'Snapshots'<br>• <strong>1991:</strong> The Gulf War consolidates the infographic in journalism"},"8":{"tema":"Topic 2: History","pregunta":"What is the main flaw of the Mercator projection?","respuesta":"<strong>It distorts the real size of areas</strong>, especially in regions close to the poles.<br><br>Example: Greenland appears to be the size of Africa when it is actually <strong>14 times smaller</strong>.<br><br>The projection preserves angles (useful for navigation) but sacrifices area proportions."},"9":{"tema":"Topic 2: History","pregunta":"What made the coverage of the Gulf War (1991) special?","respuesta":"Faced with the <strong>lack of images from the battlefront</strong>, the media turned massively to <strong>vector infographics and maps</strong>.<br><br>This consolidated the infographic as an <strong>indispensable resource in journalism</strong> when photography could not reach the front."},"10":{"tema":"Topic 3: Data","pregunta":"What does 'Garbage In, Garbage Out' (GIGO) mean?","respuesta":"If the <strong>input data is wrong</strong>, the resulting visualizations will be <strong>misleading or useless</strong>.<br><br>No visual design can make up for incorrect data. The quality of the result depends directly on the quality of the input data."},"11":{"tema":"Topic 3: Data","pregunta":"What is Data Wrangling?","respuesta":"It is the process of <strong>cleaning, transforming, and preparing</strong> raw data for analysis. It includes:<br><br>• Removing duplicates<br>• Handling null/missing values<br>• Normalizing formats (dates, units)<br>• Restructuring tables<br>• Splitting compound fields"},"12":{"tema":"Topic 3: Data","pregunta":"What is the difference between categorical and quantitative variables?","respuesta":"<strong>Categorical:</strong> They represent groups or labels (Country, Gender). They are encoded with <em>color/shape</em>.<br><br><strong>Quantitative:</strong> They represent numeric magnitudes (sales, temperature). They are encoded with <em>position/length</em>.<br><br><strong>Note:</strong> Choosing the correct visual attribute according to the type of variable is essential."},"13":{"tema":"Topic 3: Data","pregunta":"What are the data measurement scales (NOIR)?","respuesta":"<strong>N</strong>ominal: No order (colors, countries)<br><strong>O</strong>rdinal: With order but no fixed distance (low/medium/high)<br><strong>I</strong>nterval: With a fixed distance but no absolute zero (temperature °C)<br><strong>R</strong>atio: With an absolute zero (weight, income)<br><br><strong>Note:</strong> The type of scale determines which operations and charts are valid."},"14":{"tema":"Topic 4: Psychology","pregunta":"What is iconic memory?","respuesta":"It is a type of <strong>sensory memory</strong> that operates in <strong>milliseconds</strong>, capturing visual attributes such as color, position, and orientation <strong>before conscious attention</strong>.<br><br>It is the first filter of the visual system and detects 'preattentive' attributes automatically and unconsciously."},"15":{"tema":"Topic 4: Psychology","pregunta":"What are the 3 types of memory in visual perception?","respuesta":"<ol style='padding-left:20px;'><li><strong>Iconic memory</strong> (sensory): Captures in milliseconds</li><li><strong>Short-term memory</strong> (working memory): Processes consciously (~7 items)</li><li><strong>Long-term memory:</strong> Recognizes learned conventions and symbols</li></ol><br><strong>Note:</strong> The flow goes from sensory → short-term → long-term."},"16":{"tema":"Topic 4: Psychology","pregunta":"What are preattentive attributes?","respuesta":"They are visual properties that the brain detects <strong>automatically and instantly</strong>, without conscious effort:<br><br>• <strong>Color</strong> (hue, saturation)<br>• <strong>Size</strong><br>• <strong>Orientation</strong><br>• <strong>Shape</strong><br>• <strong>Motion</strong><br><br>They are used to guide attention toward the most relevant information in a visualization."},"17":{"tema":"Topic 4: Psychology","pregunta":"Name 4 Gestalt principles relevant to visualization.","respuesta":"<strong>1. Proximity:</strong> Elements that are close together are perceived as a group<br><strong>2. Similarity:</strong> Elements with the same shape/color are grouped together<br><strong>3. Closure:</strong> The brain completes incomplete shapes<br><strong>4. Continuity:</strong> We follow smooth lines and curves<br><br>Others: Figure-ground, Common fate, Connection."},"18":{"tema":"Topic 4: Psychology","pregunta":"Which Gestalt principle uses similarity?","respuesta":"The principle of <strong>similarity</strong> states that we perceive as a group the elements that <strong>share color, shape, or size</strong>.<br><br>In visualization: points of the same color are perceived as the same category, without needing to read the legend."},"19":{"tema":"Topic 5: Design","pregunta":"What is the difference between RGB and CMYK?","respuesta":"<strong>RGB (Additive):</strong> Sum of lights (Red + Green + Blue). Used on <em>screens</em>. The sum produces white.<br><br><strong>CMYK (Subtractive):</strong> Mix of inks (Cyan + Magenta + Yellow + Key/black). Used in <em>printing</em>. The sum produces black.<br><br><strong>Note:</strong> The visualization must be prepared according to its destination (screen vs. print)."},"20":{"tema":"Topic 5: Design","pregunta":"Why Serif for print and Sans Serif for screen?","respuesta":"<strong>Serif (with serifs):</strong> The serifs create a 'visual guide' that helps reading on printed paper.<br><br><strong>Sans Serif (without serifs):</strong> On screen, serifs create visual noise because of the low resolution, so clean fonts without serifs are preferred.<br><br>Examples: Times New Roman (serif) vs. Inter, Roboto (sans serif)."},"21":{"tema":"Topic 5: Design","pregunta":"What does it mean that 'form must serve function'?","respuesta":"It is a fundamental principle of functional design: <strong>aesthetics must not compromise the clarity of the message</strong>.<br><br>A chart can be beautiful, but if it makes the data hard to read, <strong>it fails in its purpose</strong>.<br><br>Function (communicating data) always takes priority over form (visual decoration)."},"22":{"tema":"Topic 5: Design","pregunta":"What is the standard unit of measurement in digital design vs. print?","respuesta":"<strong>Digital:</strong> The <strong>pixel</strong> is the smallest unit of information. Typical resolution: 72-96 ppi.<br><br><strong>Print:</strong> <strong>Millimeters</strong> and <strong>DPI (dots per inch)</strong> are used. For professional printing: at least <strong>300 DPI</strong>."},"23":{"tema":"Topic 6: Chart Anatomy","pregunta":"What are the elements of a chart's anatomy?","respuesta":"• <strong>Title:</strong> Captures attention<br>• <strong>Subtitle:</strong> Additional context<br>• <strong>X and Y axes:</strong> Encode variables<br>• <strong>Legend:</strong> Decodes symbols/colors<br>• <strong>Data area:</strong> The chart itself<br>• <strong>Labels:</strong> Specific values<br>• <strong>Source:</strong> Credibility<br>• <strong>Scale:</strong> Units of measurement<br>• <strong>Grid:</strong> Helps read values"},"24":{"tema":"Topic 6: Chart Anatomy","pregunta":"What is a choropleth map?","respuesta":"A map that <strong>encodes geographic areas with colors</strong> to represent statistical data by region.<br><br>It uses territorial divisions with a color scale proportional to the represented value.<br><br>Examples: GDP by country, population density by state, unemployment rate by municipality."},"25":{"tema":"Topic 6: Chart Anatomy","pregunta":"What is the difference between figurative and non-figurative charts?","respuesta":"<strong>Figurative:</strong> They maintain an iconic connection with reality. They resemble what they represent (maps, pictograms).<br><br><strong>Non-figurative:</strong> They use <em>abstract</em> shapes whose length or position represents magnitudes (bars, lines, areas).<br><br><strong>Note:</strong> Non-figurative charts are more precise; figurative charts are more intuitive."},"26":{"tema":"Topic 6: Chart Anatomy","pregunta":"What is the most suitable chart for comparing quantities across categories?","respuesta":"The <strong>bar chart</strong>. It is the most precise visual tool for comparing magnitudes across categories thanks to its <strong>alignment on a common axis</strong>.<br><br>According to Cleveland and McGill, length/position are the most precise visual attributes."},"27":{"tema":"Topic 7: Graphic Encoding","pregunta":"What is Cleveland and McGill's hierarchy for quantitative data?","respuesta":"From most to least precise:<br><br><strong>1. Position</strong> (scatter plots) — Most precise<br><strong>2. Length</strong> (bars)<br><strong>3. Angle</strong> (pie chart)<br><strong>4. Area</strong> (bubbles)<br><strong>5. Color/Saturation</strong> — Least precise<br><br><strong>Note:</strong> That is why bars are better than pies for comparing values."},"28":{"tema":"Topic 7: Graphic Encoding","pregunta":"What is the difference between scientific visualization and information visualization?","respuesta":"<strong>Scientific:</strong> Works with data that has a physical structure (anatomy, climate, molecules). It 'inherits' the spatial structure of the data.<br><br><strong>Information:</strong> Works with abstract data (sales, social networks). It must 'invent' the encoding because the data has no inherent shape."},"29":{"tema":"Topic 7: Graphic Encoding","pregunta":"Which visual attribute is best for categorical vs. quantitative data?","respuesta":"<strong>Categorical (types, groups):</strong> → <strong>Color (hue)</strong> — red vs. blue vs. green distinguishes groups without implying order.<br><br><strong>Quantitative (magnitudes):</strong> → <strong>Position/Length</strong> — allows values to be compared precisely.<br><br><strong>Important:</strong> Avoid color for quantitative data: the eye cannot order intensities precisely."},"30":{"tema":"Topic 7: Graphic Encoding","pregunta":"Why are pie charts criticized?","respuesta":"Because they use <strong>angle and area</strong>, which are at the <strong>lowest levels</strong> of Cleveland and McGill's hierarchy.<br><br>The human eye has difficulty comparing angles precisely.<br><br><strong>Superior alternative:</strong> Bar chart (length is a much more precise attribute than angle)."},"31":{"tema":"Topic 8: Static Visualization","pregunta":"What is the professional tool par excellence for static infographics?","respuesta":"<strong>Adobe Illustrator</strong> — It is the industry standard for professional vector graphics.<br><br>It exports to SVG, EPS, and PDF.<br><br><strong>Free alternative:</strong> Inkscape (uses SVG as its native format)."},"32":{"tema":"Topic 8: Static Visualization","pregunta":"What is the difference between a vector image and a raster image (bitmap)?","respuesta":"<strong>Vector</strong> (SVG, AI, EPS):<br>• Defined by mathematical formulas<br>• Scales infinitely without losing quality<br>• Ideal for logos, graphics, icons<br><br><strong>Raster</strong> (JPEG, PNG, TIFF):<br>• Fixed grid of pixels<br>• Becomes pixelated when enlarged<br>• Ideal for photographs"},"33":{"tema":"Topic 8: Static Visualization","pregunta":"What resolution is needed for professional print vs. screen?","respuesta":"<strong>Screen:</strong> 72-96 ppi (enough for monitors)<br><br><strong>Professional print:</strong> At least <strong>300 dots per inch (DPI)</strong><br><br><strong>Note:</strong> A file intended for the web (72 ppi) will look blurry when printed. You must always prepare the file according to its destination."},"34":{"tema":"Topic 8: Static Visualization","pregunta":"Which image format does NOT render in web browsers?","respuesta":"<strong>EPS</strong> (Encapsulated PostScript). It is a format for the printing industry and is not natively supported by web browsers.<br><br>Formats that DO work on the web: SVG, PNG, JPEG, GIF, WebP."},"35":{"tema":"Topic 9: Exploratory Visualization","pregunta":"What is the technology triad for interactive web visualizations?","respuesta":"<strong>HTML:</strong> Defines the structure of the document<br><strong>CSS:</strong> Controls appearance and style<br><strong>JavaScript:</strong> Programs the interactivity (filters, animations, tooltips)<br><br><strong>Note:</strong> Key libraries: D3.js, Chart.js, Plotly, Vega-Lite"},"36":{"tema":"Topic 9: Exploratory Visualization","pregunta":"What is Gapminder and who created it?","respuesta":"A tool created by <strong>Hans Rosling</strong>. It is the emblematic example of <strong>exploratory visualization</strong>.<br><br>It uses <strong>animated bubble</strong> charts to show relationships between global indicators:<br>• X axis: Income per capita<br>• Y axis: Life expectancy<br>• Bubble size: Population<br>• Color: Continent"},"37":{"tema":"Topic 9: Exploratory Visualization","pregunta":"What is the difference between static and exploratory visualization?","respuesta":"<strong>Static:</strong> A closed piece (PDF, image). It tells a story predefined by the author. It does not allow interaction.<br><br><strong>Exploratory:</strong> Allows the user to interact (filter, zoom, select, animate). It puts the data in the user's hands so they can discover their own patterns."},"38":{"tema":"Topic 9: Exploratory Visualization","pregunta":"What is D3.js?","respuesta":"<strong>D3.js</strong> (Data-Driven Documents) is a JavaScript library for creating dynamic, interactive visualizations in the browser.<br><br>• Manipulates the DOM based on data<br>• Works with SVG, HTML, and CSS<br>• Offers full control over every visual element<br>• Steep learning curve but maximum flexibility"},"39":{"tema":"Topic 10: Communicating","pregunta":"What is Data Storytelling?","respuesta":"The art of guiding the reader through the data with a <strong>narrative structure</strong>:<br><br><strong>1. Introduction:</strong> Context and question<br><strong>2. Development:</strong> Discoveries and visual evidence<br><strong>3. Conclusion:</strong> Findings and call-to-action<br><br>It combines: Data + Visualization + Narrative."},"40":{"tema":"Topic 10: Communicating","pregunta":"What is Datawrapper?","respuesta":"A <strong>web platform</strong> for creating interactive charts, maps, and tables, widely used in <strong>journalism</strong>.<br><br>• Requires no programming<br>• Creates clean, responsive visualizations in minutes<br>• Adopted by the newsrooms of major newspapers<br>• Allows charts to be embedded in websites"},"41":{"tema":"Topic 10: Communicating","pregunta":"What is Timeline.js and which institution developed it?","respuesta":"An <strong>open-source</strong> tool for creating interactive timelines, developed by <strong>Knight Lab</strong> (Northwestern University).<br><br>It uses Google Sheets as a data source to create interactive chronological narratives that are embedded in web pages."},"42":{"tema":"Topic 10: Communicating","pregunta":"Why is 'Scrollytelling' important?","respuesta":"It is a narrative technique that turns <strong>the user's scrolling into the story's timeline</strong>.<br><br>As the user moves down the page, the visualization transforms, reveals data progressively, and guides the narrative smoothly.<br><br>Examples: New York Times, The Pudding, Bloomberg."},"43":{"tema":"Topic 11: Ethics","pregunta":"What are the most common bad practices in visualization?","respuesta":"• <strong>Truncated axes:</strong> Exaggerate small differences<br>• <strong>Unnecessary 3D:</strong> Distorts proportions (especially pies)<br>• <strong>Cherry-picking:</strong> Selecting only convenient data<br>• <strong>Misleading colors:</strong> Induce incorrect associations<br>• <strong>Non-linear scales:</strong> Without technical justification"},"44":{"tema":"Topic 11: Ethics","pregunta":"What are the ethical good practices in visualization?","respuesta":"• The Y axis must start at zero (in bar charts)<br>• Use proportional, linear scales<br>• Cite the original source of the data<br>• Clear, descriptive legends<br>• Use 'Own elaboration' when appropriate<br>• Do not manipulate the reader's perception"},"45":{"tema":"Topic 11: Ethics","pregunta":"Why is the London Underground map both a success and a critique?","respuesta":"<strong>Success:</strong> <strong>Harry Beck's (1933)</strong> design is extremely functional — easy to use and read.<br><br><strong>Critique:</strong> It is a <strong>topological diagram</strong>; it does not reflect the real geographic location of the stations. It sacrificed geographic accuracy for legibility.<br><br><strong>Note:</strong> A case study on the balance between form and function."},"46":{"tema":"Topic 11: Ethics","pregunta":"What is the guiding principle of ethical visualization?","respuesta":"<div style='text-align:center;padding:16px;background:linear-gradient(135deg,#4f6ef708,#7c3aed08);border-radius:12px;border:2px solid #4f6ef720;'><div style='font-size:1.15rem;font-weight:800;background:linear-gradient(135deg,#4f6ef7,#7c3aed);-webkit-background-clip:text;-webkit-text-fill-color:transparent;'>\"Visualization should illuminate, not obscure.\"</div><br>Every choice of color, chart, scale, or perspective must <strong>faithfully</strong> represent the reality of the data.</div>"},"47":{"tema":"Key Concepts","pregunta":"What is SVG and why is it ideal for web visualization?","respuesta":"<strong>SVG</strong> (Scalable Vector Graphics) defines graphics using mathematical formulas.<br><br>Advantages:<br>• Scalable to any size without losing quality<br>• Can be manipulated with CSS and JavaScript<br>• Accessible (text readable by screen readers)<br>• Lightweight<br>• Natively supported by all browsers"},"48":{"tema":"Key Concepts","pregunta":"What is the data-ink ratio according to Edward Tufte?","respuesta":"Tufte proposed maximizing the <strong>data-ink ratio</strong>: the proportion of ink devoted to representing real data vs. decoration.<br><br><strong>Rule:</strong> Remove every visual element that does not communicate information.<br><br>Example: Remove unnecessary borders, colored backgrounds with no purpose, decorative 3D effects."},"49":{"tema":"Key Concepts","pregunta":"What is Tufte's 'Lie Factor'?","respuesta":"<strong>Lie Factor = Size of the effect shown in the graphic / Size of the effect in the data</strong><br><br>If the Lie Factor ≠ 1, the chart is distorting reality.<br><br>• Lie Factor > 1: Exaggerates the differences<br>• Lie Factor < 1: Minimizes the differences<br>• Lie Factor = 1: Faithful representation"}}},"unirHerrFlashcards":{"from":"es","t":{"0":{"tema":"Topic 1: Introduction","pregunta":"What are the three fundamental steps for explaining a data-driven story?","respuesta":"<ol style='padding-left:20px;'><li>Understand the <strong>available data</strong>.</li><li>Be able to <strong>represent it graphically</strong> with the right tools.</li><li>Check that the recipients understand the <strong>same message</strong> you intend to explain.</li></ol>"},"1":{"tema":"Topic 1: Introduction","pregunta":"What is the difference between tools for developers and tools for non-developers?","respuesta":"<strong>Developers:</strong> They require programming but offer unlimited customization (Google Chart, D3.js, R).<br><br><strong>Non-Developers:</strong> They maximize ease of use with drag and drop (Tableau, Power BI, Qlik, CARTO)."},"2":{"tema":"Topic 1: Introduction","pregunta":"What are the three levels of a web page?","respuesta":"<strong>1. Structure and Content (HTML):</strong> text, images, links, tables.<br><br><strong>2. Appearance (CSS):</strong> colors, typefaces, backgrounds, sizes.<br><br><strong>3. Behavior (JavaScript):</strong> effects, animations, validations, APIs."},"3":{"tema":"Topic 1: Introduction","pregunta":"What are the three types of CSS selectors?","respuesta":"<strong>1. Element:</strong> <code>div { ... }</code> — selects all tags of that type.<br><br><strong>2. Identifier (#):</strong> <code>#header { ... }</code> — unique per page.<br><br><strong>3. Class (.):</strong> <code>.highlight { ... }</code> — reusable across multiple elements."},"4":{"tema":"Topic 1: Introduction","pregunta":"According to Gartner, what currently characterizes modern ABI platforms?","respuesta":"Modern Analytics and Business Intelligence platforms are <strong>no longer differentiated</strong> by their data visualization capabilities.<br><br>Their differentiation lies in:<br>- <strong>Enterprise integration</strong><br>- <strong>Augmented capabilities</strong> (AI/ML for automatic insights)"},"5":{"tema":"Topic 2: Google Chart","pregunta":"What are the basic steps to create a chart with Google Chart?","respuesta":"<ol style='padding-left:20px;'><li>Load the library: <code>google.charts.load()</code></li><li>Define the data: <code>DataTable</code></li><li>Configure options (title, colors, etc.)</li><li>Render: <code>draw()</code></li></ol>"},"6":{"tema":"Topic 2: Google Chart","pregunta":"How do you connect Google Spreadsheets as a data source?","respuesta":"You need <strong>public read permissions</strong> or 'anyone with the link'.<br><br><code>google.visualization.Query</code> is used to query the spreadsheet, and the <code>handleQueryResponse</code> method is used to process the response."},"7":{"tema":"Topic 2: Google Chart","pregunta":"How are events handled in Google Chart?","respuesta":"<code>google.visualization.events.addListener(chart, 'select', handler)</code><br><br>It allows charts to respond to user actions such as <strong>click, sort, hover</strong> and to connect visualizations with each other to create coordinated dashboards."},"8":{"tema":"Topic 2: Google Chart","pregunta":"What is a DataView in Google Charts?","respuesta":"<code>DataView</code> acts as a <strong>'mask'</strong> over the original DataTable.<br><br>It allows you to show only a subset of columns or rows to a specific chart without altering the master data table."},"9":{"tema":"Topic 2: Google Chart","pregunta":"How do you customize the colors of a pie chart in Google Charts?","respuesta":"By specifying a list of colors in the <code>colors</code> option of the configuration object:<br><br><code>options: { colors: ['#e0440e', '#e6693e', '#ec8f6e'] }</code><br><br>The colors are automatically assigned to the slices in the order of the data."},"10":{"tema":"Topic 3: D3.js Intro","pregunta":"What is D3.js and who created it?","respuesta":"<strong>D3.js (Data-Driven Documents)</strong> is a JavaScript library created by <strong>Mike Bostock</strong>.<br><br>It uses HTML, CSS, and SVG to create advanced, dynamic, and interactive visualizations in web browsers."},"11":{"tema":"Topic 3: D3.js Intro","pregunta":"What are selectors in D3.js?","respuesta":"<code>d3.select()</code> — selects the <strong>first</strong> element that matches the CSS selector.<br><br><code>d3.selectAll()</code> — selects <strong>all</strong> the matching elements.<br><br>They are the foundation for manipulating the DOM with D3."},"12":{"tema":"Topic 3: D3.js Intro","pregunta":"What is method chaining in D3?","respuesta":"D3 allows you to chain multiple methods in a single fluent expression:<br><br><code>d3.select('body')<br>&nbsp;&nbsp;.data(dataset)<br>&nbsp;&nbsp;.enter()<br>&nbsp;&nbsp;.append('div')<br>&nbsp;&nbsp;.attr('class', 'bar')<br>&nbsp;&nbsp;.style('height', d => d + 'px')</code>"},"13":{"tema":"Topic 3: D3.js Intro","pregunta":"What does the .data() method combined with .enter() do in D3?","respuesta":"<code>.data()</code> binds an <strong>array of data</strong> to DOM elements.<br><br><code>.enter()</code> creates <strong>new elements</strong> for each data item that does not have a corresponding DOM element.<br><br>It is the fundamental mechanism of 'data binding' in D3."},"14":{"tema":"Topic 4: D3.js SVG","pregunta":"Which data formats does D3.js support and how are they loaded?","respuesta":"<strong>JSON:</strong> <code>d3.json()</code> — key-value objects, ideal for hierarchical data.<br><br><strong>CSV:</strong> <code>d3.csv()</code> — comma-separated values.<br><br><strong>TSV:</strong> <code>d3.tsv()</code> — tab-separated values."},"15":{"tema":"Topic 4: D3.js SVG","pregunta":"What are the main SVG elements?","respuesta":"<code>rect</code> — rectangles (bars): x, y, width, height<br><code>circle</code> — circles (points): cx, cy, r<br><code>line</code> — lines: x1, y1, x2, y2<br><code>text</code> — labels: x, y, font-size<br><code>path</code> — complex paths: d attribute"},"16":{"tema":"Topic 4: D3.js SVG","pregunta":"What is special about the SVG coordinate system?","respuesta":"The origin (0,0) is in the <strong>top-left corner</strong>.<br><br>The Y axis grows <strong>downward</strong>, which is counterintuitive for conventional charts.<br><br>You need to <strong>invert calculations</strong> so that the bars grow upward."},"17":{"tema":"Topic 4: D3.js SVG","pregunta":"How do you build a Bar Chart from scratch in D3?","respuesta":"It is built with SVG <code>rect</code> elements:<br><br>- <code>.attr('x', ...)</code> — horizontal position<br>- <code>.attr('y', ...)</code> — vertical position (inverted)<br>- <code>.attr('width', ...)</code> — bar width<br>- <code>.attr('height', ...)</code> — height based on the data"},"18":{"tema":"Topic 5: Scales and Axes","pregunta":"What are scales in D3.js?","respuesta":"They are <strong>functions that map an input data domain to a visual output range</strong> (pixels).<br><br>Types: linear (<code>d3.scale.linear()</code>), ordinal (<code>d3.scale.ordinal()</code>), logarithmic (<code>d3.scale.log()</code>)."},"19":{"tema":"Topic 5: Scales and Axes","pregunta":"What is the difference between domain and range in D3?","respuesta":"<strong>Domain (.domain()):</strong> range of values of the input data (e.g., [0, 1000]).<br><br><strong>Range (.range()):</strong> range of visual output pixels (e.g., [0, 500]).<br><br>Example: a value of 500 in the domain maps to 250px in the range."},"20":{"tema":"Topic 5: Scales and Axes","pregunta":"How are axes created in D3?","respuesta":"<code>d3.svg.axis()</code> automatically generates:<br>- <strong>Reference lines</strong><br>- <strong>Marks (ticks)</strong><br>- <strong>Labels</strong><br><br>It is configured with <code>.orient()</code> for the position and <code>.ticks()</code> for the number of marks."},"21":{"tema":"Topic 5: Scales and Axes","pregunta":"What is rangeRoundBands in D3?","respuesta":"<code>.rangeRoundBands()</code> divides the available space into <strong>discrete bands</strong> for categorical data.<br><br>It includes a <strong>padding</strong> parameter to control the spacing between bands. Ideal for bar charts with categories."},"22":{"tema":"Topic 6: Interactivity","pregunta":"What is a Force Layout in D3?","respuesta":"It is a <strong>physics simulation</strong> that positions nodes automatically using repulsion and attraction forces.<br><br>Key parameters:<br>- <code>.charge()</code> — repulsion/attraction force<br>- <code>.linkDistance()</code> — ideal distance between nodes<br>- <code>force.on('tick', ...)</code> — updates positions"},"23":{"tema":"Topic 6: Interactivity","pregunta":"What is the enter-update-exit pattern in D3?","respuesta":"<strong>Enter:</strong> <code>.enter()</code> — for new data, creates elements.<br><br><strong>Update:</strong> direct update — for existing data, modifies properties.<br><br><strong>Exit:</strong> <code>.exit().remove()</code> — for removed data, removes elements from the DOM."},"24":{"tema":"Topic 6: Interactivity","pregunta":"How do transitions work in D3?","respuesta":"<code>.transition()</code> automatically interpolates values between an initial state and a final state.<br><br><code>.duration(750)</code> — duration in milliseconds<br><code>.delay(100)</code> — delay before starting<br><br>It enables smooth animations without complex code."},"25":{"tema":"Topic 6: Interactivity","pregunta":"Which export formats does D3 support?","respuesta":"<strong>SVG:</strong> vector, editable, scalable without loss.<br><br><strong>PDF:</strong> export from the browser.<br><br><strong>PNG/Bitmap:</strong> rasterized, loses scalability when enlarged."},"26":{"tema":"Topic 7: Power BI","pregunta":"What are the versions of Power BI?","respuesta":"<strong>Desktop:</strong> free, personal analysis.<br><strong>Pro:</strong> collaboration in the cloud.<br><strong>Premium:</strong> enterprise capacity.<br><strong>Server:</strong> on-premises.<br><br>Power BI is a leader in the Gartner Magic Quadrant along with Tableau and Qlik."},"27":{"tema":"Topic 7: Power BI","pregunta":"What is Power Query in Power BI?","respuesta":"It is Power BI's <strong>ETL editor</strong> (Extract, Transform, Load).<br><br>It allows you to:<br>- Remove unnecessary columns<br>- Filter rows<br>- Change data types<br>- Combine queries from multiple sources<br><br>All <strong>before</strong> loading the data into the analysis model."},"28":{"tema":"Topic 7: Power BI","pregunta":"What are the three main views of Power BI Desktop?","respuesta":"<strong>1. Report:</strong> where the visualizations are created.<br><br><strong>2. Data:</strong> where the loaded data tables are viewed.<br><br><strong>3. Model:</strong> where the relationships between tables are managed."},"29":{"tema":"Topic 7: Power BI","pregunta":"What are Slicers in Power BI?","respuesta":"<strong>Slicers</strong> are interactive visual filters that allow the user to select specific values to filter all the visualizations in the report simultaneously.<br><br>They are essential for creating interactive dashboards."},"30":{"tema":"Topic 8: Qlik Sense","pregunta":"What is Qlik Sense and what are its versions?","respuesta":"A complete <strong>Business Intelligence</strong> platform oriented toward data discovery.<br><br><strong>Business:</strong> SaaS, small teams, limitations on APIs and spaces.<br><br><strong>Enterprise:</strong> multi-cloud, massive deployment, includes Nprinting, GeoAnalytics."},"31":{"tema":"Topic 8: Qlik Sense","pregunta":"What is the difference between dimensions and measures in Qlik Sense?","respuesta":"<strong>Dimensions:</strong> define the <strong>grouping categories</strong> (e.g., country, month, product).<br><br><strong>Measures:</strong> define the <strong>numeric values to calculate</strong> (e.g., sum(ventas), avg(precio), count(pedidos))."},"32":{"tema":"Topic 8: Qlik Sense","pregunta":"What are Stories in Qlik Sense?","respuesta":"They are <strong>narrative</strong> presentations created from existing visualizations.<br><br>They allow you to tell a guided story with data, combining charts with explanatory text to communicate findings persuasively."},"33":{"tema":"Topic 8: Qlik Sense","pregunta":"What is a Filter Pane in Qlik Sense?","respuesta":"It is a filter panel that allows you to <strong>select and combine filters</strong> to explore subsets of data interactively.<br><br>The selected filter states are applied globally to all the visualizations in the app."},"34":{"tema":"Topic 9: Tableau Intro","pregunta":"What is VizQL in Tableau?","respuesta":"<strong>VizQL (Visual Query Language)</strong> is Tableau's patented technology that translates <strong>drag and drop</strong> actions into optimized database queries and automatic visual representations.<br><br>It was developed at Stanford University as part of the Polaris system."},"35":{"tema":"Topic 9: Tableau Intro","pregunta":"What is the Marks Card in Tableau?","respuesta":"It is the panel that assigns fields to the chart's <strong>aesthetic properties</strong>:<br><br>- <strong>Color:</strong> differentiate categories<br>- <strong>Size:</strong> represent magnitude<br>- <strong>Text/Label:</strong> values on the marks<br>- <strong>Detail:</strong> level of granularity<br>- <strong>Shape:</strong> type of marker<br>- <strong>Tooltip:</strong> pop-up information"},"36":{"tema":"Topic 9: Tableau Intro","pregunta":"Which versions of Tableau exist?","respuesta":"<strong>Desktop:</strong> personal analysis, individual license.<br><strong>Server:</strong> on-premises, sharing within the organization.<br><strong>Online/Cloud:</strong> SaaS, no infrastructure.<br><strong>Public:</strong> free, data must be public.<br><br>In 2019 it was acquired by <strong>Salesforce</strong>."},"37":{"tema":"Topic 9: Tableau Intro","pregunta":"What is Tableau's Hyper Engine?","respuesta":"It is Tableau's data engine that enables <strong>fast ad hoc analysis of massive data</strong> even on computers with standard specifications.<br><br>It optimizes queries to deliver interactive responses without needing to pre-aggregate the data."},"38":{"tema":"Topic 10: Advanced Tableau","pregunta":"What is the difference between Filters and Pages in Tableau?","respuesta":"<strong>Filters:</strong> <strong>remove</strong> data from the visualization based on conditions.<br><br><strong>Pages:</strong> <strong>organize</strong> the data into sequential navigable layers (usually by time). The data is NOT removed; it is only split into views."},"39":{"tema":"Topic 10: Advanced Tableau","pregunta":"How do you create an interactive Dashboard in Tableau?","respuesta":"1. Create individual <strong>worksheets</strong>.<br>2. Open a <strong>new Dashboard</strong> from the bottom bar.<br>3. Drag the sheets onto the canvas.<br>4. Use the <strong>'Funnel' icon (Use as filter)</strong> so that selections filter the other sheets.<br>5. Configure <strong>actions</strong> (filter, highlight, navigation)."},"40":{"tema":"Topic 10: Advanced Tableau","pregunta":"What types of actions exist in Tableau?","respuesta":"<strong>Filter:</strong> filter data on other sheets based on the selection.<br><br><strong>Highlight:</strong> highlight related marks without removing data.<br><br><strong>Navigation:</strong> 'Go to sheet' for dynamic exploration between views."},"41":{"tema":"Topic 10: Advanced Tableau","pregunta":"What are Stories in Tableau?","respuesta":"They are <strong>narrative presentations</strong> that guide the user through a sequence of visualizations.<br><br>Each 'story point' can be a worksheet or dashboard with annotations, creating a data-driven narrative."},"42":{"tema":"Topic 11: CARTO","pregunta":"What is CARTO and what is it used for?","respuesta":"It is a leading <strong>Location Intelligence</strong> platform that turns location data into strategic decisions.<br><br>Founded in 2007, used by NASA, Google, and the Wall Street Journal. Engine: <strong>PostgreSQL/PostGIS</strong> in the cloud."},"43":{"tema":"Topic 11: CARTO","pregunta":"What is the the_geom column in CARTO?","respuesta":"It is the <strong>geometry column</strong> required to map records. It transforms <strong>latitude/longitude</strong> pairs into spatial objects that can be rendered on the map.<br><br>Without it, the data cannot be represented geographically."},"44":{"tema":"Topic 11: CARTO","pregunta":"What types of widgets does CARTO offer?","respuesta":"<strong>Category:</strong> filters by categorical values.<br><strong>Histogram:</strong> distribution of numeric values.<br><strong>Formula:</strong> aggregate calculations (sum, avg, count).<br><strong>Time series:</strong> temporal evolution of the data."},"45":{"tema":"Topic 11: CARTO","pregunta":"What spatial analyses does CARTO offer?","respuesta":"<strong>Create Lines from Points:</strong> connect points sequentially.<br><strong>Group By:</strong> differentiate routes or categories.<br><strong>Transform:</strong> geometric transformations.<br><strong>Analyze and Predict:</strong> spatial predictive analyses.<br><br>It also allows <strong>online SQL</strong> directly in the interface."},"46":{"tema":"Topic 11: CARTO","pregunta":"What is Location Intelligence?","respuesta":"It emerged with the widespread adoption of <strong>GPS in smartphones (2008)</strong>.<br><br>It combines Big Data, cloud computing, and IoT to optimize geospatial processes: delivery routes, behavioral marketing, strategic store locations."}}},"unahTesisFlashcards":{"from":"es","t":{"0":{"tema":"Ch. 4: TCROC","pregunta":"What is the general equation of the TCROC operator?","respuesta":"<strong>Master equation:</strong><br><code style='display:block;text-align:center;padding:8px;background:rgba(0,0,0,0.04);border-radius:6px;margin:6px 0;font-size:0.95em;'>&alpha;<sub>t,&lambda;,W</sub> = &minus;1 + argmin<sub>&beta;</sub> &sum;<sub>k=t&minus;W+1</sub><sup>t</sup> &lambda;<sup>t&minus;k</sup> (v(k) &minus; &beta; v(k&minus;1))&sup2;</code><br>It minimizes the weighted sum of squared errors within a window W with exponential weights &lambda;. All the variants are derived from it."},"1":{"tema":"Ch. 4: TCROC","pregunta":"What are the 4 variants of the TCROC family?","respuesta":"<ol style='padding-left:20px;'><li><strong>TCROC</strong> (&lambda;=1, W=T): theoretical baseline (degenerate)</li><li><strong>TCROCM</strong> (&lambda;=1, W&lt;T): moving window, uniform weights</li><li><strong>ETCROC</strong> (&lambda;&lt;1, W=T): global exponential decay</li><li><strong>ETCROCM</strong> (&lambda;&lt;1, W&lt;T): most general form (uses both)</li></ol><br><strong>Note:</strong> Each variant is a special case of the master equation."},"2":{"tema":"Ch. 4: TCROC","pregunta":"What form does the TCROC closed-form solution &beta;&#x0302; take?","respuesta":"<code style='display:block;text-align:center;padding:8px;background:rgba(0,0,0,0.04);border-radius:6px;margin:6px 0;font-size:0.95em;'>&beta;&#x0302; = &sum; &lambda;<sup>t&minus;k</sup> v(k)v(k&minus;1) / &sum; &lambda;<sup>t&minus;k</sup> v(k&minus;1)&sup2;</code><br>It is a <strong>ratio of two weighted dot products</strong>. It does not require numerical iteration.<br><br><strong>Proof:</strong> It is based on the strict convexity of the quadratic functional."},"3":{"tema":"Ch. 4: TCROC","pregunta":"What does the TCROC Asymptotic Consistency Theorem state?","respuesta":"Under stationary AR(1), as W &rarr; &infin;:<br><code style='display:block;text-align:center;padding:8px;background:rgba(0,0,0,0.04);border-radius:6px;margin:6px 0;font-size:0.95em;'>&beta;&#x0302; &xrarr;<sup>p</sup> &beta;*</code><br>The estimator converges to the true value of the parameter.<br><br><strong>Tools used in the proof:</strong> Law of Large Numbers for stationary weighted sequences and Slutsky's Lemma."},"4":{"tema":"Ch. 4: TCROC","pregunta":"What are the 4 axioms that TCROC satisfies?","respuesta":"<strong>1. Bounded locality:</strong> &alpha;<sub>t</sub> depends on at most W observations<br><strong>2. Geometric proportionality:</strong> Invariant under rescaling<br><strong>3. Global convexity:</strong> The functional has a unique minimum<br><strong>4. Lipschitz stability:</strong> Robustness to perturbations<br><br><strong>Note:</strong> It does NOT require normality of the residuals."},"5":{"tema":"Ch. 4: TCROC","pregunta":"What is the computational complexity of TCROC vs. the alternatives?","respuesta":"&bull; <strong>TCROC/ETCROC:</strong> O(T) — closed-form solution<br>&bull; <strong>TCROCM/ETCROCM:</strong> O(T&middot;W)<br>&bull; <strong>MLE (Hamilton):</strong> O(T&sup2;)&ndash;O(T&sup3;) — iterative<br>&bull; <strong>ARIMA:</strong> O(T&sup2;) — iterative<br><br>TCROC is <strong>significantly faster</strong>."},"6":{"tema":"Ch. 4: TCROC","pregunta":"How is TCROC related to OLS and GLS?","respuesta":"&bull; <strong>TCROC (&lambda;=1) &equiv; OLS</strong> (Ordinary Least Squares)<br>&bull; <strong>ETCROC (&lambda;&lt;1) &equiv; GLS</strong> (Generalized Least Squares)<br><br>The generalized Gauss-Markov Theorem (Aitken, 1936) guarantees that it is <strong>BLUE</strong> (Best Linear Unbiased Estimator)."},"7":{"tema":"Ch. 4: TCROC","pregunta":"What does the Lipschitz stability property of TCROC say?","respuesta":"<code style='display:block;text-align:center;padding:8px;background:rgba(0,0,0,0.04);border-radius:6px;margin:6px 0;font-size:0.95em;'>|&alpha;'<sub>t</sub> &minus; &alpha;<sub>t</sub>| &le; C<sub>t</sub> &middot; &epsilon;</code><br>Bounded perturbations (&epsilon;) in the series produce <strong>controlled</strong> deviations in &alpha;.<br><br>It guarantees <strong>robustness to measurement noise</strong>. The proof uses the quotient formula and the Cauchy-Schwarz inequality."},"8":{"tema":"Ch. 5: Markov","pregunta":"What is the quantization function &pi;?","respuesta":"<code style='display:block;text-align:center;padding:8px;background:rgba(0,0,0,0.04);border-radius:6px;margin:6px 0;font-size:0.95em;'>S<sub>t</sub> = &pi;(&alpha;<sub>t,&lambda;,W</sub>)</code><br>It maps the continuous rate &alpha;<sub>t</sub> to a discrete state S<sub>t</sub>. It is the <strong>bridge</strong> between TCROC (continuous) and Markov (discrete).<br><br>In practice we use <strong>K-Means</strong> instead of fixed thresholds because it adapts to each series."},"9":{"tema":"Ch. 5: Markov","pregunta":"What fundamental property does the sequence {S<sub>t</sub>} satisfy?","respuesta":"The <strong>first-order Markov property:</strong><br><code style='display:block;text-align:center;padding:8px;background:rgba(0,0,0,0.04);border-radius:6px;margin:6px 0;font-size:0.95em;'>P(S<sub>t+1</sub>=s<sub>j</sub> | S<sub>t</sub>=s<sub>i</sub>, S<sub>t&minus;1</sub>,...) = P(S<sub>t+1</sub>=s<sub>j</sub> | S<sub>t</sub>=s<sub>i</sub>)</code><br>The future depends <strong>only on the present</strong>, not on the full history."},"10":{"tema":"Ch. 5: Markov","pregunta":"What is the &phi;-mixing property and why does it matter?","respuesta":"<code style='display:block;text-align:center;padding:8px;background:rgba(0,0,0,0.04);border-radius:6px;margin:6px 0;font-size:0.95em;'>&phi;(n) &le; C<sub>&phi;</sub> &middot; &rho;<sup>n</sup></code><br>The mixing coefficient decays <strong>exponentially</strong>. The chain \"forgets\" its past at a geometric rate.<br><br>It is crucial for the validity of the <strong>asymptotic estimators</strong> and the confidence intervals."},"11":{"tema":"Ch. 5: Markov","pregunta":"How is the prediction error decomposed in TCROC-Markov?","respuesta":"<code style='display:block;text-align:center;padding:8px;background:rgba(0,0,0,0.04);border-radius:6px;margin:6px 0;font-size:0.95em;'>MSE(v&#x0302;<sub>T+1</sub>) = &sigma;&sup2;<sub>&epsilon;</sub> + C(&lambda;,W) / W<sub>eff</sub> + o(W<sub>eff</sub><sup>&minus;1</sup>)</code><br>&bull; <strong>&sigma;&sup2;&epsilon;:</strong> Irreducible variance (inherent noise)<br>&bull; <strong>Second term:</strong> Estimation error (decreases with W<sub>eff</sub>)<br>&bull; <strong>W<sub>eff</sub> = (1&minus;&lambda;<sup>W</sup>)/(1&minus;&lambda;):</strong> Effective sample size"},"12":{"tema":"Ch. 5: Markov","pregunta":"Why K-Means instead of fixed thresholds (&plusmn;5%)?","respuesta":"Fixed thresholds are <strong>exogenous</strong> and apply the same scheme to different series.<br><br>K-Means <strong>adapts</strong> the cutoff points to the empirical distribution of each series, better capturing the latent structure.<br><br>The <strong>Diebold-Mariano</strong> test confirms statistical superiority."},"13":{"tema":"Ch. 6: NNLS","pregunta":"What is the NNLS optimization problem for estimating P&#x0302;?","respuesta":"<code style='display:block;text-align:center;padding:8px;background:rgba(0,0,0,0.04);border-radius:6px;margin:6px 0;font-size:0.95em;'>P&#x0302; = argmin<sub>P&ge;0</sub> &Vert;X₁ &minus; PX₀&Vert;<sub>F</sub>&sup2;, &nbsp; <b>1</b><sup>T</sup>P = <b>1</b><sup>T</sup></code><br>It minimizes the Frobenius norm with nonnegativity and unit column-sum constraints. It guarantees a <strong>valid stochastic matrix</strong> by construction."},"14":{"tema":"Ch. 6: NNLS","pregunta":"What advantage does NNLS have over OLS for transition matrices?","respuesta":"<strong>Unconstrained OLS can produce negative probabilities</strong> (physically inadmissible).<br><br><strong>NNLS guarantees by construction:</strong> P<sub>ij</sub> &ge; 0 and &sum;P<sub>ij</sub> = 1, without the need for ad hoc post-processing."},"15":{"tema":"Ch. 6: NNLS","pregunta":"What algebraic trick vectorizes the NNLS problem?","respuesta":"The Kronecker identity:<br><code style='display:block;text-align:center;padding:8px;background:rgba(0,0,0,0.04);border-radius:6px;margin:6px 0;font-size:0.95em;'>vec(ABC) = (C<sup>T</sup> &otimes; A) vec(B)</code><br>It transforms the matrix problem into a vector problem:<br>vec(X₁) = (X₀ᵀ &otimes; I) vec(P&#x0302;)<br><br>It makes it possible to apply the standard NNLS solver by <strong>Lawson & Hanson</strong>."},"16":{"tema":"Ch. 6: NNLS","pregunta":"What are the 6 steps of the SRep Algorithm?","respuesta":"<ol style='padding-left:20px;'><li>Encode states as <strong>one-hot</strong></li><li>Build the matrices X₀ and X₁</li><li>Form A = X₀ᵀ &otimes; I<sub>n</sub> (Kronecker)</li><li>Build the augmented system with the constraint w&middot;C</li><li>Solve NNLS: min&Vert;A&#x0303;c &minus; b&#x0303;&Vert;&sup2; with c &ge; 0</li><li>Reconstruct P&#x0302; = vec⁻¹(c&#x0302;) and normalize the columns</li></ol>"},"17":{"tema":"Ch. 6: NNLS","pregunta":"What does the P&#x0302; matrix for Honduras GDP reveal?","respuesta":"State s₄ (strong growth) occurred <strong>only once</strong> (2022, post-COVID rebound) and always moderates: P(s₃|s₄) = 100%.<br><br>It is a <strong>transient state</strong>, not sustainable structural dynamics. States s₂ and s₃ dominate the stationary distribution."},"18":{"tema":"Ch. 7: Fuels","pregunta":"What is the degeneration phenomenon of the TCROC model?","respuesta":"When W = T (window = total length):<br><code style='display:block;text-align:center;padding:8px;background:rgba(0,0,0,0.04);border-radius:6px;margin:6px 0;font-size:0.95em;'>&alpha;<sub>t</sub>(T) = &alpha;&#x0304; &forall;t &rArr; Var(&alpha;<sub>t</sub>) = 0 &rArr; K<sub>eff</sub> = 1</code><br>Everything collapses into a single state. <strong>Solution:</strong> Restrict W &le; 52 weeks (one annual cycle)."},"19":{"tema":"Ch. 7: Fuels","pregunta":"What are the optimal hyperparameters for Honduran fuels?","respuesta":"&bull; <strong>Regular:</strong> W=50, &lambda;=0.99, K=3, Accuracy=85.1%<br>&bull; <strong>Super:</strong> W=52, &lambda;=0.99, K=4, 62.8%<br>&bull; <strong>Diesel:</strong> W=50, &lambda;=0.97, K=3, 71.6%<br>&bull; <strong>Kerosene:</strong> W=52, &lambda;=0.98, K=5, 68.2%<br><br>W &asymp; 1 year, &lambda; &asymp; 1 (nearly uniform weights)."},"20":{"tema":"Ch. 7: Fuels","pregunta":"What are the spectral gap &gamma; and the mixing time?","respuesta":"<code style='display:block;text-align:center;padding:8px;background:rgba(0,0,0,0.04);border-radius:6px;margin:6px 0;font-size:0.95em;'>&gamma; = 1 &minus; |&lambda;₂|, &nbsp; t<sub>mix</sub> = ⌈ ln(1/&epsilon;) / &gamma; ⌉</code><br>&gamma; measures how quickly the chain forgets its state.<br>&bull; <strong>Kerosene:</strong> &gamma; = 0.021, t<sub>mix</sub> &asymp; 47 weeks (most inert)<br>&bull; <strong>Diesel:</strong> &gamma; = 0.040, t<sub>mix</sub> &asymp; 25 weeks (most agile)"},"21":{"tema":"Ch. 7: Fuels","pregunta":"Why does Regular gasoline have the best accuracy (85.1%)?","respuesta":"It has only K=3 states (simple structure), high persistence (P(s<sub>i</sub>|s<sub>i</sub>) &asymp; 0.96), and it is the <strong>most regulated by the SEN</strong>.<br><br>Its predictability reflects a market with few abrupt changes and smooth transitions."},"22":{"tema":"Ch. 8: Reservoir","pregunta":"What is the reservoir state equation (ESN)?","respuesta":"<code style='display:block;text-align:center;padding:8px;background:rgba(0,0,0,0.04);border-radius:6px;margin:6px 0;font-size:0.95em;'><b>h</b><sub>t</sub> = &sigma;(<b>W</b><sub>in</sub> <b>u</b><sub>t</sub> + <b>W</b><sub>res</sub> <b>h</b><sub>t&minus;1</sub>)</code><br>W<sub>in</sub> and W<sub>res</sub> are generated randomly and <strong>are NOT trained</strong>. Only W<sub>out</sub> is estimated. This avoids backpropagation through time (BPTT)."},"23":{"tema":"Ch. 8: Reservoir","pregunta":"What does the Echo State Property (ESP) state?","respuesta":"If &rho;(W<sub>res</sub>) &lt; 1, the difference between trajectories converges to zero:<br><code style='display:block;text-align:center;padding:8px;background:rgba(0,0,0,0.04);border-radius:6px;margin:6px 0;font-size:0.95em;'>&Vert;h<sub>t</sub> &minus; h'<sub>t</sub>&Vert; &le; &Vert;W<sub>res</sub>&Vert;<sup>t</sup> &Vert;h₀ &minus; h'₀&Vert; &rarr; 0</code><br>The output depends <strong>only on the inputs</strong>, not on the initial condition."},"24":{"tema":"Ch. 8: Reservoir","pregunta":"What is the TCROC-Markov &sub; SSRC Inclusion Theorem?","respuesta":"TCROC-Markov is a <strong>degenerate</strong> case of the SSRC when:<br>&bull; W<sub>res</sub> = 0 (no recurrence)<br>&bull; &sigma; = identity (no nonlinearity)<br>&bull; a = 1 (no leakage)<br>&bull; D = K (dimension = no. of states)<br><br><strong>Hierarchy:</strong> TCROC &sub; TCROC-Markov &sub; TCROC-SSRC"},"25":{"tema":"Ch. 8: Reservoir","pregunta":"Why is the Universal Approximation Theorem important?","respuesta":"Grigoryeva & Ortega (2018) proved that the SSRC can approximate <strong>any continuous causal functional on sequences</strong> with finite memory.<br><br>It is <strong>strictly more powerful</strong> than TCROC-Markov (linear) and provides the theoretical justification for the proposed extension."},"26":{"tema":"Integrative","pregunta":"What is the main original contribution of the thesis?","respuesta":"<ol style='padding-left:20px;'><li>The <strong>TCROC family</strong> with 4 variants and axiomatic proofs</li><li>The W&rarr;T <strong>degeneration phenomenon</strong> and its solution</li><li>The <strong>Inclusion Theorem</strong>: TCROC-Markov &sub; SSRC</li><li>Comprehensive empirical validation with real data from Honduras</li><li>The <strong>SRep Algorithm</strong>: NNLS estimation of stochastic matrices</li></ol>"},"27":{"tema":"Integrative","pregunta":"What is the common thread of the 5 chapters?","respuesta":"<strong>Ch 4:</strong> Define TCROC (transformation operator)<br><strong>Ch 5:</strong> Integrate with Markov (probabilistic model)<br><strong>Ch 6:</strong> Estimate with NNLS (constructive algorithm)<br><strong>Ch 7:</strong> Validate with real data (Honduras fuels)<br><strong>Ch 8:</strong> Extend to SSRC (nonlinear, universal)"}}}}};
  function section(lang, html) { return '<div class="lang-section" data-lang="' + lang + '">' + html + '</div>'; }
  function block(lang, html) { return '<section class="fc-language-block" data-lang="' + lang + '"><div>' + html + '</div></section>'; }
  function pair(en, es) { return (en && es && en !== es) ? en + ' / ' + es : (es || en); }

  var study = window.studyData || {};
  Object.keys(T.study).forEach(function (courseId) {
    var sections = study[courseId], tr = T.study[courseId];
    if (!Array.isArray(sections)) return;
    sections.forEach(function (sec, si) {
      var st = tr['s' + si];
      if (st && st.sectionTitle) sec.title = pair(st.sectionTitle, sec.title);
      (sec.items || []).forEach(function (item, ii) {
        var it = tr['s' + si + 'i' + ii];
        if (!it || item._bilingual) return;
        item.title = pair(it.title, item.title);
        item.content = section('es', item.content) + section('en', it.content);
        item._bilingual = true;
      });
    });
  });

  Object.keys(T.flashcards).forEach(function (key) {
    var cards = window[key], spec = T.flashcards[key];
    if (!Array.isArray(cards)) return;
    cards.forEach(function (card, i) {
      var tr = spec.t[String(i)];
      if (!tr || card.front) return;
      var en, es;
      if (spec.from === 'es') { es = card; en = tr; }
      else if (spec.fix && spec.fix[String(i)]) { es = card; en = spec.fix[String(i)]; }
      else { en = card; es = tr; }
      card.pregunta_en = en.pregunta; card.pregunta_es = es.pregunta;
      card.respuesta_en = en.respuesta; card.respuesta_es = es.respuesta;
      card.tema = pair(en.tema, es.tema);
      card.front = block('en', en.pregunta) + block('es', es.pregunta);
      card.back = block('en', en.respuesta) + block('es', es.respuesta);
    });
  });
})();
